fn newton_sqrt(a: i32, b: i32, tol: i32) -> i32 {
    let mut lo = a;
    let mut hi = b;
    let mut mid = (lo + hi) / 2;
    let mut iter = 0;
    while hi - lo > tol {
        mid = (lo + hi) / 2;
        if mid * mid > a * b {
            hi = mid;
        } else {
            lo = mid;
        }
        iter = iter + 1;
        if iter > 50 {
            return mid;
        }
    }
    mid
}

fn main() {
    let r = newton_sqrt(1, 100, 1);
    println!("{}", r);
}

