fn gcd_euclid(a: i32, b: i32) -> i32 {
    let mut a_val = a;
    let mut b_val = b;
    while b_val != 0 {
        let temp = b_val;
        b_val = a_val % b_val;
        a_val = temp;
    }
    a_val
}

