fn run_sm(n: u32) -> u32 {
    let mut state = 0;
    let mut i = 0;
    while i < n {
        let next = match state {
            0 => match i % 3 { 0 => 1, _ => 0, },
            1 => match i % 2 { 0 => 2, _ => 0, },
            _ => match i % 4 { 0 => 0, _ => 2, },
        };
        state = next;
        i = i + 1;
    }
    return state;
}
fn main() { println!("{}", run_sm(10)); }

fn count_transitions(n: u32) -> u32 {
    let mut state = 0;
    let mut changes = 0;
    for i in 0..n {
        let next = match state {
            0 => match i % 3 { 0 => 0, _ => 1, },
            _ => match i % 2 { 0 => 0, _ => 1, },
        };
        if next != state { changes = changes + 1; }
        state = next;
    }
    return changes;
}
fn main() { println!("{}", count_transitions(15)); }

