fn search(n: u32) -> u32 {
    let mut i = 1;
    let mut best = 0;
    while i < n {
        let s = match i % 5 {
            0 => i * 3,
            1 => if i > 10 { i * 2 } else { i },
            _ => i,
        };
        if s > best { best = s; }
        if best > 50 { break; }
        i = i + 1;
    }
    return best;
}
