fn cellular(state: u32, rule: u32) -> u32 {
    let mut next = 0;
    let mut i = 0;
    while i < 8 {
        let left = if i == 0 { 0 } else { (state >> (i - 1)) & 1 };
        let center = (state >> i) & 1;
        let right = if i == 7 { 0 } else { (state >> (i + 1)) & 1 };
        let pattern = left * 4 + center * 2 + right;
        let new_bit = (rule >> pattern) & 1;
        next = next | (new_bit << i);
        i = i + 1;
    }
    return next;
}
