fn sieve_count(limit: u32) -> u32 {
    let mut count = 0;
    let mut n = 2;
    while n <= limit {
        let mut is_prime = 1;
        let mut d = 2;
        while d * d <= n {
            if n % d == 0 { is_prime = 0; }
            d = d + 1;
        }
        if is_prime == 1 { count = count + 1; }
        n = n + 1;
    }
    return count;
}
fn twin_prime_count(limit: u32) -> u32 {
    let mut count = 0;
    let mut n = 2;
    while n <= limit - 2 {
        let mut p1 = 1;
        let mut d = 2;
        while d * d <= n { if n % d == 0 { p1 = 0; } d = d + 1; }
        let m = n + 2;
        let mut p2 = 1;
        let mut d2 = 2;
        while d2 * d2 <= m { if m % d2 == 0 { p2 = 0; } d2 = d2 + 1; }
        if p1 == 1 && p2 == 1 { count = count + 1; }
        n = n + 1;
    }
    return count;
}
