    let mut sum = 0;
    while n > 0 {
        let d = n % 10;
        let mut f = 1;
        let mut i = 1;
        while i <= d { f = f * i; i = i + 1; }
        sum = sum + f;
        n = n / 10;
    }
    return sum;
}
