fn partition(pivot: u32, n: u32) -> u32 {
    let mut low = 0u32;
    let mut mid = 0u32;
    let mut high = 0u32;
    let mut i = 0u32;
    while i < n {
        let val = (i * 7 + 3) % 10;
        if val < pivot {
            low = low + 1;
        } else if val == pivot {
            mid = mid + 1;
        } else {
            high = high + 1;
        }
        i = i + 1;
    }
    low * 100 + mid * 10 + high
}

