    println!("{}", result);
}

fn maintain(n: u32) -> u32 {
    let mut sum = 0u32;
    let mut i = 0u32;
    let mut checks = 0u32;
    while i <= n {
        sum = sum + i;
        let expected = i * (i + 1) / 2;
        if sum == expected {
            checks = checks + 1;
        }
        i = i + 1;
    }
    checks
}

