fn crc(data: u32, poly: u32) -> u32 {
    let mut reg = data;
    let mut bit = 0u32;
    while bit < 8 {
        if reg % 2 == 1 {
            reg = (reg / 2) ^ poly;
        } else {
            reg = reg / 2;
        }
        bit = bit + 1;
    }
    reg
}

