fn approx_sqrt(n: u32) -> u32 {
    if n == 0 {
        return 0;
    }
    let mut x = n;
    let mut iter = 0u32;
    while iter < 20 {
        let nx = (x + n / x) / 2;
        if nx >= x {
            return x;
        }
        x = nx;
        iter = iter + 1;
    }
    x
}

