fn is_prime(n: i32) -> i32 {
    if n < 2 { return 0; }
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 { return 0; }
        d = d + 1;
    }
    1
}

fn main() {
    let mut count = 0;
    let mut i = 2;
    while i <= 200 {
        if is_prime(i) == 1 && is_prime(i + 2) == 1 {
            println!("({}, {})", i, i + 2);
            count = count + 1;
        }
        i = i + 1;
    }
    println!("total: {}", count);
}

