fn catalan(n: i32) -> i32 {
    if n <= 1 { return 1; }
    let mut sum = 0;
    let mut i = 0;
    while i < n {
        sum = sum + catalan(i) * catalan(n - 1 - i);
        i = i + 1;
    }
    sum
}

fn main() {
