fn find_index(target: i32) -> i32 {
    if target < 0 {
        return -1;
    }
    let arr = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91];
    let mut lo = 0;
    let mut hi = 9;
    while lo <= hi {
        let mid = (lo + hi) / 2;
        if arr[mid] == target {
            return mid;
        }
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    -1
}

fn main() {
    let tests = [2, 23, 91, 50, 0, 8];
    for t in tests {
        println!("{}: idx={}", t, find_index(t));
    }
}

