fn main() {
    let data = [1, 1, 1, 2, 2, 3, 3, 3, 3, 1];
    let n = 10;
    let mut i = 0;
    while i < n {
        let val = data[i];
        let mut count = 1;
        while i + count < n {
            if data[i + count] == val {
                count = count + 1;
            } else {
                i = i; // break simulation - just stop counting
                count = n; // force exit
            }
        }
        if count < n {
            println!("{}x{}", val, count);
            i = i + count;
        } else {
            i = n; // done
        }
    }
}

