fn bin_search(target: i32) -> i32 {
    let mut lo = 0; let mut hi = 100;
    while lo < hi {
        let mid = (lo + hi) / 2;
        if mid < target { lo = mid + 1; }
        else { hi = mid; }
    }
    lo
}
