fn op_add(a: i32, b: i32) -> i32 { a + b }
fn op_mul(a: i32, b: i32) -> i32 { a * b }
fn dispatch(mode: i32, a: i32, b: i32) -> i32 {
    match mode { 0 => { return op_add(a, b); } _ => { return op_mul(a, b); } }
}
fn main() { println!("{} {}", dispatch(0, 3, 4), dispatch(1, 3, 4)); }

fn ack(m: i32, n: i32) -> i32 {
    if m == 0 { return n + 1; }
    if n == 0 { return ack(m - 1, 1); }
    ack(m - 1, ack(m, n - 1))
}
fn main() { println!("{} {} {}", ack(0, 5), ack(1, 3), ack(2, 2)); }

fn hanoi_moves(n: i32) -> i32 {
    if n <= 0 { return 0; }
    2 * hanoi_moves(n - 1) + 1
}
fn main() { println!("{} {} {}", hanoi_moves(1), hanoi_moves(3), hanoi_moves(5)); }

fn choose(n: i32, k: i32) -> i32 {
    if k == 0 || k == n { return 1; }
    choose(n - 1, k - 1) + choose(n - 1, k)
}
fn main() { println!("{} {} {}", choose(5, 2), choose(6, 3), choose(4, 2)); }

fn catalan(n: i32) -> i32 {
    if n <= 1 { return 1; }
    let mut result = 0;
    let mut i = 0;
    while i < n {
        result = result + catalan(i) * catalan(n - 1 - i);
        i = i + 1;
    }
    result
}
fn main() { println!("{} {} {}", catalan(0), catalan(3), catalan(4)); }

