fn modpow(base: i32, exp: i32, modulus: i32) -> i32 {
    let mut result = 1;
    let mut b = base % modulus;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 { result = result * b % modulus; }
        e = e / 2;
        b = b * b % modulus;
    }
    result
}
