fn is_prime(n: i32) -> i32 {
    if n < 2 { return 0; }
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 { return 0; }
        d = d + 1;
    }
    1
}
fn sum_primes(limit: i32) -> i32 {
    let mut s = 0;
    let mut n = 2;
    while n < limit {
        if is_prime(n) == 1 { s = s + n; }
        n = n + 1;
    }
    s
}
fn count_primes(limit: i32) -> i32 {
    let mut c = 0;
    let mut n = 2;
    while n < limit {
        if is_prime(n) == 1 { c = c + 1; }
        n = n + 1;
    }
    c
}
fn main() { println!("{} {} {} {}", count_primes(50), sum_primes(50), count_primes(100), sum_primes(100)); }

struct Config { mode: i32, limit: i32 }
fn compute(cfg: Config) -> i32 {
    let mut result = 0;
    for i in 1..cfg.limit {
        match cfg.mode {
            0 => { result = result + i; }
            1 => { result = result + i * i; }
            _ => { result = result + 1; }
        }
    }
    result
}
fn main() {
    let c1 = Config { mode: 0, limit: 11 };
    let c2 = Config { mode: 1, limit: 11 };
    let c3 = Config { mode: 2, limit: 11 };
    println!("{} {} {}", compute(c1), compute(c2), compute(c3));
}

