fn isqrt(n: i32) -> i32 {
    let mut x = n;
    let mut y = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}
fn main() {
    println!("{} {} {} {} {}", isqrt(0), isqrt(1), isqrt(4), isqrt(15), isqrt(100));
}

