struct Point { x: i32, y: i32 }
fn manhattan(a: Point, b: Point) -> i32 {
    let dx = a.x - b.x;
    let dy = a.y - b.y;
    let adx = if dx < 0 { 0 - dx } else { dx };
    let ady = if dy < 0 { 0 - dy } else { dy };
    adx + ady
}
