struct Data { val: i32, factor: i32 }
fn transform(d: Data, mode: i32) -> i32 {
    match mode {
        0 => { return d.val + d.factor; }
        1 => { return d.val * d.factor; }
        2 => { return d.val - d.factor; }
        _ => { return d.val; }
    }
}
fn process(n: i32) -> i32 {
    if n < 0 { return 0; }
    let d = Data { val: n, factor: 3 };
    let mut total = 0;
    for mode in 0..4 {
        total = total + transform(d, mode);
    }
    total
}
