struct Config { base: i32, exp_limit: i32 }
fn power(base: i32, exp: i32) -> i32 {
    if exp <= 0 { return 1; }
    base * power(base, exp - 1)
}
fn compute_mode(cfg: Config, mode: i32) -> i32 {
    match mode {
        0 => {
            let mut sum = 0;
            let mut i = 1;
            while i <= cfg.exp_limit {
                sum = sum + power(cfg.base, i);
                i = i + 1;
            }
            return sum;
        }
        1 => {
            return power(cfg.base, cfg.exp_limit);
        }
        _ => { return cfg.base + cfg.exp_limit; }
    }
}
fn main() {
    let c = Config { base: 2, exp_limit: 5 };
    println!("{} {} {}", compute_mode(c, 0), compute_mode(c, 1), compute_mode(c, 2));
}

