fn f_mul(a: i32, b: i32) -> i32 { a * b }
fn f_div(a: i32, b: i32) -> i32 { if b == 0 { return 0; } a / b }
fn f_mod(a: i32, b: i32) -> i32 { if b == 0 { return 0; } a % b }
fn f_abs(x: i32) -> i32 { if x < 0 { return 0 - x; } x }
fn f_max(a: i32, b: i32) -> i32 { if a > b { return a; } b }
fn f_min(a: i32, b: i32) -> i32 { if a < b { return a; } b }
fn f_sqr(x: i32) -> i32 { f_mul(x, x) }
fn f_cube(x: i32) -> i32 { f_mul(x, f_sqr(x)) }
fn f_pow4(x: i32) -> i32 { f_sqr(f_sqr(x)) }
fn f_sign(x: i32) -> i32 { if x > 0 { return 1; } if x < 0 { return 0 - 1; } 0 }
fn main() {
