fn is_prime(n: i32) -> i32 {
    if n < 2 { return 0; }
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 { return 0; }
        d = d + 1;
    }
    1
}
fn next_prime(n: i32) -> i32 {
    let mut candidate = n + 1;
    while is_prime(candidate) == 0 {
        candidate = candidate + 1;
    }
    candidate
}
fn nth_prime(n: i32) -> i32 {
    let mut p = 2;
    let mut i = 1;
    while i < n {
        p = next_prime(p);
        i = i + 1;
    }
    p
}
