fn sum_divisors(n: i32) -> i32 {
    let mut sum = 0;
    let mut d = 1;
    while d * d <= n {
        if n % d == 0 {
            sum = sum + d;
            if d != 1 && d * d != n {
                sum = sum + n / d;
            }
        }
        d = d + 1;
    }
    sum
}
fn is_perfect(n: i32) -> i32 {
    if n < 2 { return 0; }
    if sum_divisors(n) == n { return 1; }
    0
}
