fn next_state(state: i32, input: i32) -> i32 {
    match state {
        0 => { if input == 1 { return 1; } return 0; }
        1 => { if input == 0 { return 2; } return 1; }
        2 => { if input == 1 { return 3; } return 0; }
        3 => { return 3; }
        _ => { return 0; }
    }
}
fn accepts(inputs: i32) -> i32 {
    let mut state = 0;
    let mut n = inputs;
    while n > 0 {
        let bit = n % 2;
        state = next_state(state, bit);
        n = n / 2;
    }
    if state == 3 { return 1; }
    0
}
