fn f(x: i32) -> i32 { x * x + 2 * x + 1 }
fn find_root(target: i32) -> i32 {
    let mut lo = 0;
    let mut hi = target;
    while lo < hi {
        let mid = (lo + hi) / 2;
        if f(mid) < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}
fn main() { println!("{} {} {}", find_root(100), find_root(400), find_root(10000)); }

fn digit_sum(mut n: i32) -> i32 {
    let mut s = 0;
    while n > 0 {
        s = s + n % 10;
        n = n / 10;
    }
    s
}
fn digital_root(mut n: i32) -> i32 {
    while n >= 10 {
        n = digit_sum(n);
    }
    n
}
