fn compute(op: i32, x: i32, y: i32) -> i32 {
    match op {
        0 => {
            let sum = x + y;
            let diff = x - y;
            return sum * diff;
        }
        1 => {
            let mut prod = 1;
            let mut i = 0;
            while i < y {
                prod = prod * x;
                i = i + 1;
            }
            return prod;
        }
        2 => {
            if y == 0 { return 0; }
            return x % y;
        }
        _ => { return x + y; }
    }
}
fn main() { println!("{} {} {} {}", compute(0, 10, 3), compute(1, 2, 10), compute(2, 17, 5), compute(3, 7, 8)); }

