fn smallest_prime_factor(n: i32) -> i32 {
    let mut d = 2;
    while d * d <= n { if n % d == 0 { return d; } d = d + 1; }
    n
}
fn mobius(n: i32) -> i32 {
    if n == 1 { return 1; }
    let mut x = n;
    let mut factors = 0;
    let mut d = 2;
    while d * d <= x {
        if x % d == 0 {
            if x % (d * d) == 0 { return 0; }
            factors = factors + 1;
            x = x / d;
        }
        d = d + 1;
    }
    if x > 1 { factors = factors + 1; }
    if factors % 2 == 0 { return 1; }
    0 - 1
}
fn main() {
    let mut sum = 0;
    for i in 1..101 { sum = sum + mobius(i); }
    println!("{} {} {} {}", mobius(1), mobius(6), mobius(12), sum);
}

fn digit_sq_sum(mut n: i32) -> i32 {
    let mut s = 0;
    while n > 0 { let d = n % 10; s = s + d * d; n = n / 10; }
    s
}
fn is_happy(n: i32) -> i32 {
    let mut slow = n;
    let mut fast = n;
    loop {
        slow = digit_sq_sum(slow);
        fast = digit_sq_sum(digit_sq_sum(fast));
        if slow == 1 { return 1; }
        if slow == fast { return 0; }
    }
}
fn main() {
    let mut count = 0;
    for i in 1..201 { if is_happy(i) == 1 { count = count + 1; } }
    println!("{} {} {}", is_happy(7), is_happy(4), count);
}

fn factorial(n: i32) -> i32 { if n <= 1 { return 1; } n * factorial(n - 1) }
fn choose(n: i32, k: i32) -> i32 {
    if k > n { return 0; }
    factorial(n) / (factorial(k) * factorial(n - k))
}
fn main() {
    let mut sum = 0;
    for k in 0..8 { sum = sum + choose(7, k); }
    println!("{} {} {} {}", choose(5, 2), choose(10, 3), choose(7, 0), sum);
}

fn count_partitions(n: i32, max_part: i32) -> i32 {
    if n == 0 { return 1; }
    if n < 0 || max_part <= 0 { return 0; }
    count_partitions(n - max_part, max_part) + count_partitions(n, max_part - 1)
}
fn main() { println!("{} {} {} {}", count_partitions(5, 5), count_partitions(10, 10), count_partitions(15, 15), count_partitions(7, 7)); }

struct Frac { num: i32, den: i32 }
fn gcd(a: i32, b: i32) -> i32 { if b == 0 { return a; } gcd(b, a % b) }
fn simplify(f: Frac) -> Frac {
    let g = gcd(f.num, f.den);
    Frac { num: f.num / g, den: f.den / g }
}
fn add_frac(a: Frac, b: Frac) -> Frac {
    let f = Frac { num: a.num * b.den + b.num * a.den, den: a.den * b.den };
    simplify(f)
}
fn main() {
    let a = Frac { num: 1, den: 3 };
    let b = Frac { num: 1, den: 6 };
    let c = add_frac(a, b);
    println!("{} {}", c.num, c.den);
}

