    let mut max_n = 0;
    let mut total = 0;
    for i in 1..100 {
        let l = collatz_len(i);
        total = total + l;
        if l > max_len { max_len = l; max_n = i; }
    }
    println!("{} {} {}", max_n, max_len, total);
}

fn analyze(limit: i32) -> i32 {
    let mut sum = 0;
    let mut count = 0;
    let mut max_val = 0;
    let mut min_val = limit;
    let mut sum_sq = 0;
    for i in 1..limit {
        if i % 3 == 0 || i % 5 == 0 {
            sum = sum + i;
            count = count + 1;
            if i > max_val { max_val = i; }
            if i < min_val { min_val = i; }
            sum_sq = sum_sq + i * i;
        }
    }
    sum + count + max_val + min_val + sum_sq / 100
}
