struct Interval { lo: i32, hi: i32 }
fn overlaps(a: Interval, b: Interval) -> i32 {
    if a.hi < b.lo || b.hi < a.lo { return 0; }
    1
}
fn overlap_len(a: Interval, b: Interval) -> i32 {
    if overlaps(a, b) == 0 { return 0; }
    let lo = if a.lo > b.lo { a.lo } else { b.lo };
    let hi = if a.hi < b.hi { a.hi } else { b.hi };
    hi - lo
}
fn main() {
    let a = Interval { lo: 1, hi: 10 };
    let b = Interval { lo: 5, hi: 15 };
    let c = Interval { lo: 20, hi: 30 };
    println!("{} {} {} {}", overlaps(a, b), overlaps(a, c), overlap_len(a, b), overlap_len(b, c));
}

