struct Stats { n: i32, sum: i32, sum_sq: i32, min: i32, max: i32 }
impl Stats {
    fn mean(&self) -> i32 { if self.n == 0 { return 0; } self.sum / self.n }
    fn range(&self) -> i32 { self.max - self.min }
    fn variance_approx(&self) -> i32 {
        if self.n == 0 { return 0; }
        self.sum_sq / self.n - (self.sum / self.n) * (self.sum / self.n)
    }
}
fn main() {
    let mut s = Stats { n: 0, sum: 0, sum_sq: 0, min: 999, max: 0 };
    for i in 1..21 {
        let v = i * 3 + 7;
        s.n = s.n + 1;
        s.sum = s.sum + v;
        s.sum_sq = s.sum_sq + v * v;
        if v < s.min { s.min = v; }
        if v > s.max { s.max = v; }
    }
    println!("{} {} {}", s.mean(), s.range(), s.variance_approx());
}

