fn power(base: i32, exp: i32) -> i32 {
    let mut r = 1;
    let mut i = 0;
    while i < exp { r = r * base; i = i + 1; }
    r
}
fn geometric_sum(a: i32, r: i32, n: i32) -> i32 {
    let mut sum = 0;
    let mut i = 0;
    while i < n { sum = sum + a * power(r, i); i = i + 1; }
    sum
}
fn main() { println!("{} {} {}", geometric_sum(1, 2, 10), geometric_sum(3, 2, 5), geometric_sum(1, 3, 6)); }

fn catalan(n: i32) -> i32 {
    if n <= 1 { return 1; }
    let mut sum = 0;
    let mut i = 0;
    while i < n {
        sum = sum + catalan(i) * catalan(n - 1 - i);
        i = i + 1;
    }
    sum
}
fn main() { println!("{} {} {} {} {}", catalan(0), catalan(1), catalan(3), catalan(5), catalan(7)); }

