struct Counter {
    val: i32,
    min: i32,
    max: i32,
}
impl Counter {
    fn new(lo: i32, hi: i32) -> Counter { Counter { val: lo, min: lo, max: hi } }
    fn inc(&self) -> Counter {
        let new_val = if self.val < self.max { self.val + 1 } else { self.val };
        Counter { val: new_val, min: self.min, max: self.max }
    }
    fn dec(&self) -> Counter {
        let new_val = if self.val > self.min { self.val - 1 } else { self.val };
        Counter { val: new_val, min: self.min, max: self.max }
    }
    fn get(&self) -> i32 { self.val }
    fn at_min(&self) -> i32 { if self.val == self.min { return 1; } 0 }
    fn at_max(&self) -> i32 { if self.val == self.max { return 1; } 0 }
}
fn main() {
    let c = Counter::new(0, 5);
    let c = c.inc();
    let c = c.inc();
    let c = c.inc();
    println!("{} {} {}", c.get(), c.at_min(), c.at_max());
}

struct Op { code: i32, val: i32 }
fn apply_chain(ops: i32, acc: i32) -> i32 {
    if ops <= 0 { return acc; }
    let op_code = ops % 3;
    let new_acc = match op_code {
        0 => { acc + ops }
        1 => { acc * 2 }
        _ => { acc - 1 }
    };
    apply_chain(ops - 1, new_acc)
}
fn main() { println!("{} {} {}", apply_chain(5, 0), apply_chain(10, 1), apply_chain(15, 0)); }

