fn mod_pow(mut base: i32, mut exp: i32, modulus: i32) -> i32 {
    let mut result = 1;
    base = base % modulus;
    while exp > 0 {
        if exp % 2 == 1 { result = (result * base) % modulus; }
        exp = exp / 2;
        base = (base * base) % modulus;
    }
    result
}
fn main() { println!("{} {} {}", mod_pow(2, 10, 1000), mod_pow(3, 7, 100), mod_pow(5, 13, 97)); }

