fn prime_factor_digit_sum(mut n: i32) -> i32 {
    let mut sum = 0;
    let mut d = 2;
    while d * d <= n {
        while n % d == 0 {
            sum = sum + digit_sum(d);
            n = n / d;
        }
        d = d + 1;
    }
    if n > 1 { sum = sum + digit_sum(n); }
    sum
}
fn is_smith(n: i32) -> i32 {
    if n < 4 { return 0; }
    if digit_sum(n) == prime_factor_digit_sum(n) { return 1; }
    0
}
