}

fn stirling2(n: i32, k: i32) -> i32 {
    if n == 0 && k == 0 { return 1; }
    if n == 0 || k == 0 { return 0; }
    if k > n { return 0; }
    k * stirling2(n - 1, k) + stirling2(n - 1, k - 1)
}
fn main() { println!("{} {} {} {}", stirling2(3, 2), stirling2(4, 2), stirling2(5, 3), stirling2(4, 3)); }

fn bell(n: i32) -> i32 {
    if n == 0 { return 1; }
    let mut sum = 0;
    for k in 0..n {
        sum = sum + choose(n - 1, k) * bell(k);
    }
    sum
}
fn choose(n: i32, k: i32) -> i32 {
    if k > n { return 0; }
    if k == 0 { return 1; }
    let mut result = 1;
    let mut i = 0;
    while i < k {
        result = result * (n - i) / (i + 1);
        i = i + 1;
    }
    result
}
fn main() { println!("{} {} {} {}", bell(0), bell(1), bell(3), bell(5)); }

struct State { id: i32, data: i32 }
fn transition(s: State, input: i32) -> State {
    match s.id {
        0 => {
            if input > 5 { return State { id: 1, data: s.data + input }; }
            return State { id: 0, data: s.data + 1 };
        }
        1 => {
            if input == 0 { return State { id: 2, data: s.data }; }
            return State { id: 1, data: s.data + input };
        }
        _ => {
            return State { id: 0, data: 0 };
        }
    }
}
fn main() {
    let mut s = State { id: 0, data: 0 };
    for i in 0..20 {
        s = transition(s, i % 7);
    }
    println!("{} {}", s.id, s.data);
}

