fn binary_search(target: i64, size: i64) -> i64 {
    let mut lo = 0;
    let mut hi = size - 1;
    let mut steps = 0;
    while lo <= hi {
        let mid = (lo + hi) / 2;
        if mid == target {
            return steps;
        }
        if mid < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
        steps = steps + 1;
    }
    steps
}
fn main() {
