fn sum_divisors(n: i64) -> i64 {
    let mut sum = 1;
    let mut i = 2;
    while i * i <= n {
        if n % i == 0 {
            sum = sum + i;
            if i != n / i {
                sum = sum + n / i;
            }
        }
        i = i + 1;
    }
    sum
}
fn classify(n: i64) -> i64 {
    let s = sum_divisors(n);
    if s > n { return 1; }
    if s == n { return 0; }
    -1
}
