fn sort_digits_desc(mut n: i64) -> i64 {
    let mut d0 = n / 1000;
    let mut d1 = (n / 100) % 10;
    let mut d2 = (n / 10) % 10;
    let mut d3 = n % 10;
    if d0 < d1 { let t = d0; d0 = d1; d1 = t; }
    if d0 < d2 { let t = d0; d0 = d2; d2 = t; }
    if d0 < d3 { let t = d0; d0 = d3; d3 = t; }
    if d1 < d2 { let t = d1; d1 = d2; d2 = t; }
    if d1 < d3 { let t = d1; d1 = d3; d3 = t; }
    if d2 < d3 { let t = d2; d2 = d3; d3 = t; }
    d0 * 1000 + d1 * 100 + d2 * 10 + d3
}
fn kaprekar_steps(mut n: i64) -> i64 {
    let mut steps = 0;
    while n != 6174 {
        let desc = sort_digits_desc(n);
        let asc = sort_digits_desc(n);
        let asc_val = (asc % 10) * 1000 + ((asc / 10) % 10) * 100 + ((asc / 100) % 10) * 10 + asc / 1000;
        n = desc - asc_val;
        steps = steps + 1;
        if steps > 10 { break; }
    }
    steps
}
