fn mobius(n: i64) -> i64 {
    if n == 1 { return 1; }
    let mut factors = 0;
    let mut tmp = n;
    let mut p = 2;
    while p * p <= tmp {
        if tmp % p == 0 {
            factors = factors + 1;
            tmp = tmp / p;
            if tmp % p == 0 { return 0; }
        }
        p = p + 1;
    }
    if tmp > 1 { factors = factors + 1; }
    if factors % 2 == 0 { return 1; }
    -1
}
