fn perm_digit_sum(n: i64) -> i64 {
    let d = digit_count(n);
    let ds = digit_sum(n);
    let f = factorial(d - 1);
    let rep = 111111111 % (1000000000 / ipow(10, 9 - d));
    ds * f * rep
}
