        let digit_sum = x % 10 + y % 10 + carry;
        if digit_sum >= 10 {
            carry = 1;
            carries = carries + 1;
        } else {
            carry = 0;
        }
        x = x / 10;
        y = y / 10;
    }
    carries
}
