fn ternary_search(lo: i64, hi: i64, steps: i64) -> i64 {
    let mut l = lo;
    let mut h = hi;
    let mut i = 0;
    while i < steps {
        let m1 = l + (h - l) / 3;
        let m2 = h - (h - l) / 3;
        if f(m1) < f(m2) {
            l = m1 + 1;
        } else {
            h = m2 - 1;
        }
        i = i + 1;
    }
