        },
        2 => match ch {
            0 => 2,
            1 => 3,
            _ => -1,
        },
        3 => 3,
        _ => -1,
    }
}
fn run_nfa(i0: i64, i1: i64, i2: i64, i3: i64, i4: i64) -> i64 {
    let mut s = 0;
    s = nfa_step(s, i0);
    if s < 0 { return 0; }
    s = nfa_step(s, i1);
    if s < 0 { return 0; }
    s = nfa_step(s, i2);
    if s < 0 { return 0; }
    s = nfa_step(s, i3);
    if s < 0 { return 0; }
    s = nfa_step(s, i4);
    if s == 3 { return 1; }
    0
}
fn main() {
