fn edit_dist(s_len: i64, t_len: i64) -> i64 {
    if s_len == 0 { return t_len; }
    if t_len == 0 { return s_len; }
    let cost = if (s_len + t_len) % 3 == 0 { 0 } else { 1 };
    min3(
        edit_dist(s_len - 1, t_len) + 1,
        edit_dist(s_len, t_len - 1) + 1,
        edit_dist(s_len - 1, t_len - 1) + cost
    )
}
