    if c > d { let t = c; c = d; d = t; }
    if a > c { let t = a; a = c; c = t; }
    if b > d { let t = b; b = d; d = t; }
    if b > c { let t = b; b = c; c = t; }
    let merge1 = a + b;
    let mut x = merge1;
    let mut y = c;
    let mut z = d;
    if x > y { let t = x; x = y; y = t; }
    if y > z { let t = y; y = z; z = t; }
    if x > y { let t = x; x = y; y = t; }
    let merge2 = x + y;
    let total = merge1 + merge2 + merge2 + z;
    total
}
