fn fenwick_update(pos: i64, val: i64, n: i64) -> i64 {
    let mut i = pos;
    let mut updates = 0;
    while i <= n {
        updates = updates + 1;
        i = i + lowbit(i);
    }
    updates
}
fn fenwick_query(pos: i64) -> i64 {
    let mut i = pos;
    let mut ops = 0;
    while i > 0 {
        ops = ops + 1;
        i = i - lowbit(i);
    }
    ops
}
