fn dispatch(code: i64, x: i64, y: i64) -> i64 {
    match code {
        0 => x + y,
        1 => x * y,
        2 => x - y,
        3 => if x > y { x } else { y },
        4 => if x < y { x } else { y },
        5 => x * x + y * y,
        6 => (x + y) * (x - y),
        7 => x * y * (x + y),
        8 => x % (y + 1),
        _ => x ^ y,
    }
}
