fn isqrt(n: i64) -> i64 {
    let mut lo = 0;
    let mut hi = n;
    while lo <= hi {
        let mid = (lo + hi) / 2;
        if mid * mid <= n {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    hi
}
