fn knapsack(cap: i64, w0: i64, v0: i64, w1: i64, v1: i64, w2: i64, v2: i64, w3: i64, v3: i64) -> i64 {
    let mut best = 0;
    let mut s0 = 0;
    while s0 <= 1 {
        let mut s1 = 0;
        while s1 <= 1 {
            let mut s2 = 0;
            while s2 <= 1 {
                let mut s3 = 0;
                while s3 <= 1 {
                    let weight = s0 * w0 + s1 * w1 + s2 * w2 + s3 * w3;
                    let value = s0 * v0 + s1 * v1 + s2 * v2 + s3 * v3;
                    if weight <= cap {
                        best = max2(best, value);
                    }
                    s3 = s3 + 1;
                }
                s2 = s2 + 1;
            }
            s1 = s1 + 1;
        }
        s0 = s0 + 1;
    }
    best
}
