fn is_digit(c: i64) -> i64 { if c >= 48 { if c <= 57 { return 1; } } 0 }
fn is_alpha(c: i64) -> i64 { if c >= 65 { if c <= 90 { return 1; } } if c >= 97 { if c <= 122 { return 1; } } 0 }
fn tokenize_char(state: i64, ch: i64) -> i64 {
    match state {
        0 => {
            if is_digit(ch) == 1 { return 1; }
            if is_alpha(ch) == 1 { return 2; }
            0
        },
        1 => {
            if is_digit(ch) == 1 { return 1; }
            0
        },
        2 => {
            if is_alpha(ch) == 1 { return 2; }
            if is_digit(ch) == 1 { return 2; }
            0
        },
        _ => 0,
    }
}
fn main() {
    let mut state = 0;
    let mut tokens = 0;
    let input0 = 65;
    let input1 = 66;
    let input2 = 32;
    let input3 = 49;
    let input4 = 50;
    state = tokenize_char(state, input0);
    state = tokenize_char(state, input1);
    let new_state = tokenize_char(state, input2);
    if new_state == 0 { tokens = tokens + 1; }
    state = new_state;
    state = tokenize_char(state, input3);
    state = tokenize_char(state, input4);
    if state != 0 { tokens = tokens + 1; }
    println!("{}", tokens);
}

