fn pow_mod(mut base: i64, mut exp: i64, n: i64) -> i64 {
    let mut result = 1;
    base = base % n;
    while exp > 0 {
        if exp % 2 == 1 {
            result = mul_mod(result, base, n);
        }
        exp = exp / 2;
        base = mul_mod(base, base, n);
    }
    result
}
fn order_of(a: i64, n: i64) -> i64 {
    let mut pow = a % n;
    let mut ord = 1;
    while pow != 1 && ord < n {
        pow = mul_mod(pow, a, n);
        ord = ord + 1;
    }
    if pow == 1 { ord } else { 0 }
}
