    let rem0 = f0 + f1 + f2 + f3 - s1;
    let s2 = min2(min2(if f0 != s1 { f0 } else { 99999 }, if f1 != s1 { f1 } else { 99999 }),
                  min2(if f2 != s1 { f2 } else { 99999 }, if f3 != s1 { f3 } else { 99999 }));
    let merged1 = s1 + s2;
    let r1 = rem0 - s2;
    let s3 = min2(merged1, r1);
    let s4 = max2(merged1, r1);
    let merged2 = s3 + s4;
    merged1 + merged2
}
