    if i0 == j0 { sum = sum + v0 * w0; }
    if i0 == j1 { sum = sum + v0 * w1; }
    if i0 == j2 { sum = sum + v0 * w2; }
    if i1 == j0 { sum = sum + v1 * w0; }
    if i1 == j1 { sum = sum + v1 * w1; }
    if i1 == j2 { sum = sum + v1 * w2; }
    if i2 == j0 { sum = sum + v2 * w0; }
    if i2 == j1 { sum = sum + v2 * w1; }
    if i2 == j2 { sum = sum + v2 * w2; }
    sum
}
