fn hash1(x: i64, size: i64) -> i64 { x % size }
fn hash2(x: i64, size: i64) -> i64 { (x * 7 + 3) % size }
fn hash3(x: i64, size: i64) -> i64 { (x * 13 + 17) % size }
fn set_bit(filter: i64, pos: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..pos { bit = bit * 2; }
    let check = filter / bit % 2;
    if check == 0 { filter + bit } else { filter }
}
fn check_bit(filter: i64, pos: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..pos { bit = bit * 2; }
    filter / bit % 2
}
fn insert(filter: i64, x: i64, size: i64) -> i64 {
    let f1 = set_bit(filter, hash1(x, size));
    let f2 = set_bit(f1, hash2(x, size));
    set_bit(f2, hash3(x, size))
}
fn query(filter: i64, x: i64, size: i64) -> i64 {
    let b1 = check_bit(filter, hash1(x, size));
    let b2 = check_bit(filter, hash2(x, size));
    let b3 = check_bit(filter, hash3(x, size));
    if b1 == 1 && b2 == 1 && b3 == 1 { 1 } else { 0 }
}
