    f = insert(f, 17, size);
    println!("{}", query(f, 42, size));
    println!("{}", query(f, 17, size));
    println!("{}", query(f, 99, size));
}

fn ring_write(buf: i64, pos: i64, val: i64, size: i64) -> i64 {
    let mut power = 1;
    for _i in 0..pos { power = power * 100; }
    let mask = buf / (power * 100) * (power * 100) + buf % power;
    mask + val * power
}
fn ring_read(buf: i64, pos: i64) -> i64 {
    let mut power = 1;
    for _i in 0..pos { power = power * 100; }
    (buf / power) % 100
}
