fn add_digits(a_lo: i64, a_hi: i64, b_lo: i64, b_hi: i64) -> i64 {
    let lo_sum = a_lo + b_lo;
    let carry = lo_sum / 10000;
    let lo_result = lo_sum % 10000;
    let hi_result = a_hi + b_hi + carry;
    hi_result * 10000 + lo_result
}
fn mul_by_2(lo: i64, hi: i64) -> i64 {
    add_digits(lo, hi, lo, hi)
}
