fn nfa_char(state: i64, input: i64, expected: i64) -> i64 {
    if input == expected { state + 1 } else { 0 }
}
fn nfa_star(state: i64, input: i64, expected: i64) -> i64 {
    if input == expected { state } else { state + 1 }
}
fn match_pattern(a: i64, b: i64, c: i64, p0: i64, p1: i64, p2: i64) -> i64 {
    let s1 = nfa_char(0, a, p0);
    if s1 == 0 { return 0; }
    let s2 = nfa_star(s1, b, p1);
    let s3 = nfa_char(s2, c, p2);
    if s3 > 0 { 1 } else { 0 }
}
