fn lerp(a: i64, b: i64, t: i64, scale: i64) -> i64 {
    a + (b - a) * t / scale
}
fn bezier2(p0: i64, p1: i64, p2: i64, t: i64, scale: i64) -> i64 {
    let a = lerp(p0, p1, t, scale);
    let b = lerp(p1, p2, t, scale);
    lerp(a, b, t, scale)
}
fn bezier3(p0: i64, p1: i64, p2: i64, p3: i64, t: i64, scale: i64) -> i64 {
    let a = lerp(p0, p1, t, scale);
    let b = lerp(p1, p2, t, scale);
    let c = lerp(p2, p3, t, scale);
    let d = lerp(a, b, t, scale);
    let e = lerp(b, c, t, scale);
    lerp(d, e, t, scale)
}
