fn classify_char(c: i64) -> i64 {
    if c >= 48 && c <= 57 { 1 }
    else if c >= 65 && c <= 90 { 2 }
    else if c >= 97 && c <= 122 { 2 }
    else if c == 32 || c == 9 { 3 }
    else if c == 40 || c == 41 { 4 }
    else if c == 43 || c == 45 || c == 42 || c == 47 { 5 }
    else { 0 }
}
fn token_name(t: i64) -> i64 { t }
fn lex_stream(a: i64, b: i64, c: i64, d: i64, e: i64) -> i64 {
    classify_char(a) * 10000 + classify_char(b) * 1000 +
    classify_char(c) * 100 + classify_char(d) * 10 + classify_char(e)
}
