}

fn eval_literal(val: i64) -> i64 { val }
fn eval_unary(op: i64, val: i64) -> i64 {
    match op {
        0 => 0 - val,
        1 => if val == 0 { 1 } else { 0 },
        _ => val,
    }
}
fn eval_binary(op: i64, left: i64, right: i64) -> i64 {
    match op {
        0 => left + right,
        1 => left - right,
        2 => left * right,
        3 => if right != 0 { left / right } else { 0 },
        4 => if right != 0 { left % right } else { 0 },
        _ => 0,
    }
}
fn eval_node(ntype: i64, op: i64, val: i64, left: i64, right: i64) -> i64 {
    match ntype {
        0 => eval_literal(val),
        1 => eval_unary(op, val),
        2 => eval_binary(op, left, right),
        _ => 0,
    }
}
