}

fn alloc_reg(used: i64, prefer: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..prefer { bit = bit * 2; }
    if used / bit % 2 == 0 { prefer }
    else {
        let mut r = 0;
        let mut u = used;
        while u % 2 == 1 {
            u = u / 2;
            r = r + 1;
        }
        r
    }
}
fn set_used(used: i64, reg: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..reg { bit = bit * 2; }
    if used / bit % 2 == 0 { used + bit } else { used }
}
