    let r2 = alloc_reg(used, 1);
    used = set_used(used, r2);
    println!("{} {} {}", r0, r1, r2);
    println!("{}", used);
}

fn has_edge(adj: i64, from: i64, to: i64) -> i64 {
    let bit_pos = from * 4 + to;
    let mut bit = 1;
    for _i in 0..bit_pos { bit = bit * 2; }
    adj / bit % 2
}
fn in_degree(adj: i64, node: i64, n: i64) -> i64 {
    let mut deg = 0;
    for from in 0..n {
        deg = deg + has_edge(adj, from, node);
    }
    deg
}
