fn gf_mul(a: i64, b: i64, mod_poly: i64) -> i64 {
    let mut result = 0;
    let mut aa = a;
    let mut bb = b;
    for _i in 0..8 {
        if bb % 2 == 1 {
            let mut xor = 0;
            let mut ra = result;
            let mut ab = aa;
            for _j in 0..8 {
                let rb = ra % 2;
                let ab2 = ab % 2;
                if rb != ab2 { xor = xor + 1; }
                ra = ra / 2;
                ab = ab / 2;
                xor = xor * 2;
            }
            result = xor / 2;
        }
        bb = bb / 2;
        aa = aa * 2;
        if aa >= 256 { aa = aa - 256; }
    }
    result % 256
}
fn syndrome(d0: i64, d1: i64, d2: i64) -> i64 {
