fn skip_search(keys: i64, target: i64) -> i64 {
    let k0 = keys % 100;
    let k1 = (keys / 100) % 100;
    let k2 = (keys / 10000) % 100;
    let k3 = (keys / 1000000) % 100;
    if target == k0 { 0 }
    else if target == k1 { 1 }
    else if target == k2 { 2 }
    else if target == k3 { 3 }
    else { -1 }
}
fn skip_level(hash: i64) -> i64 {
    let mut h = hash;
    let mut level = 1;
    while h % 2 == 0 && level < 4 {
        h = h / 2;
        level = level + 1;
    }
    level
}
