fn fitness(gene: i64, target: i64) -> i64 {
    let mut g = gene;
    let mut t = target;
    let mut score = 0;
    for _i in 0..8 {
        if g % 2 == t % 2 { score = score + 1; }
        g = g / 2;
        t = t / 2;
    }
    score
}
fn crossover(parent1: i64, parent2: i64, point: i64) -> i64 {
    let mut mask = 1;
    for _i in 0..point { mask = mask * 2; }
    mask = mask - 1;
    let lo = parent1 % (mask + 1);
    let hi = parent2 / (mask + 1) * (mask + 1);
    lo + hi
}
fn mutate(gene: i64, bit: i64) -> i64 {
    let mut mask = 1;
    for _i in 0..bit { mask = mask * 2; }
    if gene / mask % 2 == 0 { gene + mask } else { gene - mask }
}
