    println!("{}", fitness(170, target));
    println!("{}", fitness(85, target));
    println!("{}", fitness(255, target));
    println!("{}", crossover(170, 85, 4));
    println!("{}", mutate(170, 0));
}

fn vm_exec(opcode: i64, a: i64, b: i64, acc: i64) -> i64 {
    match opcode {
        1 => a,
        2 => acc + a,
        3 => acc - a,
        4 => acc * a,
        5 => if a != 0 { acc / a } else { 0 },
        6 => if acc == 0 { a } else { acc },
        7 => if acc != 0 { a } else { acc },
        8 => acc % a,
        9 => if acc < a { 1 } else { 0 },
        10 => if acc == a { 1 } else { 0 },
        _ => acc,
    }
}
fn run_program(o0: i64, a0: i64, o1: i64, a1: i64, o2: i64, a2: i64, o3: i64, a3: i64) -> i64 {
    let s0 = vm_exec(o0, a0, 0, 0);
    let s1 = vm_exec(o1, a1, 0, s0);
    let s2 = vm_exec(o2, a2, 0, s1);
    vm_exec(o3, a3, 0, s2)
}
fn main() {
    println!("{}", run_program(1, 10, 2, 5, 4, 3, 3, 1));
