}

fn split_hi(n: i64, base: i64) -> i64 { n / base }
fn split_lo(n: i64, base: i64) -> i64 { n % base }
fn karatsuba(x: i64, y: i64, base: i64) -> i64 {
    if x < base && y < base { return x * y; }
    let xh = split_hi(x, base);
    let xl = split_lo(x, base);
    let yh = split_hi(y, base);
    let yl = split_lo(y, base);
    let z0 = xl * yl;
    let z2 = xh * yh;
    let z1 = (xl + xh) * (yl + yh) - z0 - z2;
    z2 * base * base + z1 * base + z0
}
fn main() {
    println!("{}", karatsuba(12, 34, 10));
    println!("{}", karatsuba(56, 78, 10));
    println!("{}", karatsuba(99, 99, 10));
    println!("{}", karatsuba(100, 200, 100));
}

fn haar_approx(a: i64, b: i64) -> i64 { (a + b) / 2 }
fn haar_detail(a: i64, b: i64) -> i64 { (a - b) / 2 }
fn haar_4(a: i64, b: i64, c: i64, d: i64) -> i64 {
    let a1 = haar_approx(a, b);
    let d1 = haar_detail(a, b);
    let a2 = haar_approx(c, d);
    let d2 = haar_detail(c, d);
    let a_final = haar_approx(a1, a2);
    let d_final = haar_detail(a1, a2);
    a_final * 1000000 + d_final * 10000 + d1 * 100 + d2
}
fn main() {
    println!("{}", haar_4(4, 6, 10, 12));
    println!("{}", haar_4(1, 1, 1, 1));
    println!("{}", haar_4(100, 0, 100, 0));
}

fn digit_at(n: i64, pos: i64) -> i64 {
    let mut div = 1;
    for _i in 0..pos { div = div * 10; }
    (n / div) % 10
}
