fn constrain(lo: i64, hi: i64, must_gt: i64, must_lt: i64) -> i64 {
    let new_lo = if must_gt > lo { must_gt } else { lo };
    let new_hi = if must_lt < hi { must_lt } else { hi };
    if new_lo > new_hi { -1 }
    else { (new_hi - new_lo + 1) }
}
fn intersect(a_lo: i64, a_hi: i64, b_lo: i64, b_hi: i64) -> i64 {
    let lo = if a_lo > b_lo { a_lo } else { b_lo };
    let hi = if a_hi < b_hi { a_hi } else { b_hi };
    if lo > hi { 0 }
    else { hi - lo + 1 }
}
