fn unify(t1: i64, t2: i64) -> i64 {
    if t1 == t2 { t1 }
    else if t1 == 0 { t2 }
    else if t2 == 0 { t1 }
    else { -1 }
}
fn type_of_binop(op: i64, t_left: i64, t_right: i64) -> i64 {
    match op {
        0 => { let u = unify(t_left, t_right); if u == 1 { 1 } else { -1 } }
        1 => { let u = unify(t_left, t_right); if u == 1 { 1 } else { -1 } }
        2 => { let u = unify(t_left, t_right); if u == 1 || u == 2 { 3 } else { -1 } }
        _ => -1,
    }
}
fn main() {
    println!("{}", unify(1, 1));
    println!("{}", unify(0, 2));
    println!("{}", unify(1, 2));
    println!("{}", type_of_binop(0, 1, 1));
    println!("{}", type_of_binop(0, 1, 2));
    println!("{}", type_of_binop(2, 1, 1));
}

fn parse_digit(c: i64) -> i64 {
    if c >= 48 && c <= 57 { c - 48 } else { -1 }
}
fn parse_alpha(c: i64) -> i64 {
    if c >= 65 && c <= 90 { 1 }
    else if c >= 97 && c <= 122 { 1 }
    else { -1 }
}
fn parse_number(c0: i64, c1: i64, c2: i64) -> i64 {
    let d0 = parse_digit(c0);
    if d0 < 0 { return -1; }
    let d1 = parse_digit(c1);
    if d1 < 0 { return d0; }
    let d2 = parse_digit(c2);
    if d2 < 0 { return d0 * 10 + d1; }
    d0 * 100 + d1 * 10 + d2
}
fn parse_ident_len(c0: i64, c1: i64, c2: i64, c3: i64) -> i64 {
    let mut len = 0;
    if parse_alpha(c0) >= 0 { len = len + 1; } else { return len; }
    if parse_alpha(c1) >= 0 || parse_digit(c1) >= 0 { len = len + 1; } else { return len; }
    if parse_alpha(c2) >= 0 || parse_digit(c2) >= 0 { len = len + 1; } else { return len; }
    if parse_alpha(c3) >= 0 || parse_digit(c3) >= 0 { len = len + 1; } else { return len; }
    len
}
fn main() {
    println!("{}", parse_number(49, 50, 51));
    println!("{}", parse_number(49, 65, 0));
    println!("{}", parse_ident_len(97, 98, 49, 32));
    println!("{}", parse_ident_len(49, 0, 0, 0));
}

fn apply_id(x: i64) -> i64 { x }
fn apply_const(x: i64, _y: i64) -> i64 { x }
fn apply_succ(n: i64) -> i64 { n + 1 }
fn church_num(n: i64, f: i64, x: i64) -> i64 {
    let mut result = x;
    for _i in 0..n {
        result = match f {
            0 => apply_id(result),
            1 => apply_succ(result),
            _ => result,
        };
    }
    result
}
fn church_add(m: i64, n: i64) -> i64 {
    church_num(m, 1, 0) + church_num(n, 1, 0)
}
fn church_mul(m: i64, n: i64) -> i64 {
    church_num(m, 1, 0) * church_num(n, 1, 0)
}
