    println!("{}", church_mul(3, 4));
}

fn abstract_add(a_lo: i64, a_hi: i64, b_lo: i64, b_hi: i64) -> i64 {
    let lo = a_lo + b_lo;
    let hi = a_hi + b_hi;
    lo * 1000 + hi
}
fn abstract_mul(a_lo: i64, a_hi: i64, b_lo: i64, b_hi: i64) -> i64 {
    let p1 = a_lo * b_lo;
    let p2 = a_lo * b_hi;
    let p3 = a_hi * b_lo;
    let p4 = a_hi * b_hi;
    let lo = if p1 < p2 { if p1 < p3 { if p1 < p4 { p1 } else { p4 } } else { if p3 < p4 { p3 } else { p4 } } }
             else { if p2 < p3 { if p2 < p4 { p2 } else { p4 } } else { if p3 < p4 { p3 } else { p4 } } };
    let hi = if p1 > p2 { if p1 > p3 { if p1 > p4 { p1 } else { p4 } } else { if p3 > p4 { p3 } else { p4 } } }
             else { if p2 > p3 { if p2 > p4 { p2 } else { p4 } } else { if p3 > p4 { p3 } else { p4 } } };
    lo * 1000 + hi
}
