fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 { a } else { gcd(b, a % b) }
}
fn mod_inv(a: i64, m: i64) -> i64 {
    let mut result = 1;
    while (result * a) % m != 1 {
        result = result + 1;
        if result > m { return -1; }
    }
    result
}
fn crt2(r1: i64, m1: i64, r2: i64, m2: i64) -> i64 {
    let g = gcd(m1, m2);
    if g != 1 { return -1; }
    let inv = mod_inv(m1, m2);
    if inv < 0 { return -1; }
    let x = r1 + m1 * ((r2 - r1) * inv % m2);
    if x < 0 { x + m1 * m2 } else { x % (m1 * m2) }
}
fn main() {
    println!("{}", crt2(2, 3, 3, 5));
    println!("{}", crt2(1, 3, 2, 7));
    println!("{}", mod_inv(3, 7));
    println!("{}", gcd(12, 18));
}

fn transition(state: i64, rand_val: i64) -> i64 {
    match state {
        0 => if rand_val < 50 { 0 } else { 1 },
        1 => if rand_val < 30 { 0 } else if rand_val < 70 { 1 } else { 2 },
        2 => if rand_val < 40 { 1 } else { 2 },
        _ => 0,
    }
}
fn simulate(start: i64, r0: i64, r1: i64, r2: i64, r3: i64, r4: i64) -> i64 {
    let s1 = transition(start, r0);
    let s2 = transition(s1, r1);
    let s3 = transition(s2, r2);
    let s4 = transition(s3, r3);
    let s5 = transition(s4, r4);
    s5
}
