fn can_stack_alloc(escapes: i64, size: i64, max_stack: i64) -> i64 {
    if escapes == 1 { 0 }
    else if size > max_stack { 0 }
    else { 1 }
}
fn alloc_decision(created_in: i64, used_in: i64, returned: i64, size: i64, max_stack: i64) -> i64 {
    let esc = does_escape(created_in, used_in, returned);
    can_stack_alloc(esc, size, max_stack)
}
