fn is_reachable(root_set: i64, obj: i64) -> i64 {
    let mut rs = root_set;
    let mut bit = 1;
    for _i in 0..obj { bit = bit * 2; }
    rs / bit % 2
}
fn mark_phase(root_set: i64, refs: i64, n: i64) -> i64 {
    let mut marked = root_set;
    for obj in 0..n {
        if is_reachable(marked, obj) == 1 {
            let obj_refs = (refs / (obj * 100 + 1)) % 100;
            let mut bit = 1;
            for _j in 0..obj_refs { bit = bit * 2; }
            marked = marked + bit;
        }
    }
    marked
}
fn sweep_count(marked: i64, n: i64) -> i64 {
    let mut freed = 0;
    for i in 0..n {
        if is_reachable(marked, i) == 0 {
            freed = freed + 1;
        }
    }
    freed
}
fn main() {
    println!("{}", is_reachable(5, 0));
    println!("{}", is_reachable(5, 1));
    println!("{}", is_reachable(5, 2));
    println!("{}", sweep_count(5, 4));
}

fn should_compile(call_count: i64, threshold: i64) -> i64 {
    if call_count >= threshold { 1 } else { 0 }
}
fn tier_select(call_count: i64) -> i64 {
    if call_count < 10 { 0 }
    else if call_count < 100 { 1 }
    else if call_count < 1000 { 2 }
    else { 3 }
}
fn estimated_speedup(tier: i64) -> i64 {
    match tier {
        0 => 1,
        1 => 5,
        2 => 20,
        3 => 50,
        _ => 1,
    }
}
fn compile_benefit(call_count: i64, compile_cost: i64) -> i64 {
    let tier = tier_select(call_count);
    let speedup = estimated_speedup(tier);
    call_count * speedup - compile_cost
}
fn main() {
    for calls in [1, 10, 50, 100, 500, 1000, 5000] {
        let tier = tier_select(calls);
        let benefit = compile_benefit(calls, 100);
        println!("{} {} {}", calls, tier, benefit);
    }
}

