fn ch(e: i64, f: i64, g: i64) -> i64 {
    let mut result = 0;
    let mut ee = e;
    let mut ff = f;
    let mut gg = g;
    for _i in 0..8 {
        let eb = ee % 2;
        let fb = ff % 2;
        let gb = gg % 2;
        let bit = if eb == 1 { fb } else { gb };
        result = result + bit;
        result = result * 2;
        ee = ee / 2;
        ff = ff / 2;
        gg = gg / 2;
    }
    result / 2
}
fn maj(a: i64, b: i64, c: i64) -> i64 {
    let mut result = 0;
    let mut aa = a;
    let mut bb = b;
    let mut cc = c;
    for _i in 0..8 {
        let ab = aa % 2;
        let bbit = bb % 2;
        let cb = cc % 2;
        let bit = if ab + bbit + cb >= 2 { 1 } else { 0 };
        result = result + bit;
        result = result * 2;
        aa = aa / 2;
        bb = bb / 2;
        cc = cc / 2;
    }
    result / 2
}
