fn can_strength_reduce(op: i64, operand: i64) -> i64 {
    if op == 2 && operand == 2 { 1 }
    else if op == 3 && operand == 2 { 1 }
    else if op == 2 && operand == 1 { 1 }
    else if op == 0 && operand == 0 { 1 }
    else { 0 }
}
fn apply_strength_reduce(op: i64, val: i64, operand: i64) -> i64 {
    if op == 2 && operand == 2 { val + val }
    else if op == 3 && operand == 2 { val / 2 }
    else if op == 2 && operand == 1 { val }
    else if op == 0 && operand == 0 { val }
    else { match op { 0 => val + operand, 1 => val - operand, 2 => val * operand, 3 => if operand != 0 { val / operand } else { 0 }, _ => val } }
}
fn peephole_chain(v: i64, o1: i64, a1: i64, o2: i64, a2: i64) -> i64 {
    let r1 = apply_strength_reduce(o1, v, a1);
    apply_strength_reduce(o2, r1, a2)
}
