    println!("{}", can_strength_reduce(2, 2));
    println!("{}", can_strength_reduce(0, 5));
    println!("{}", apply_strength_reduce(2, 7, 2));
    println!("{}", peephole_chain(10, 2, 2, 0, 5));
    println!("{}", peephole_chain(100, 3, 2, 2, 3));
}

fn latency(opcode: i64) -> i64 {
    match opcode {
        0 => 1,
        1 => 1,
        2 => 3,
        3 => 5,
        4 => 20,
        5 => 4,
        _ => 1,
    }
}
fn ready_time(dep_finish: i64, this_start: i64) -> i64 {
    if dep_finish > this_start { dep_finish } else { this_start }
}
fn schedule_2(op0: i64, op1: i64, dep: i64) -> i64 {
    let lat0 = latency(op0);
    let finish0 = lat0;
    let start1 = if dep == 1 { finish0 } else { 0 };
    let finish1 = start1 + latency(op1);
    finish1
}
fn critical_path(op0: i64, op1: i64, op2: i64) -> i64 {
    let l0 = latency(op0);
    let l1 = latency(op1);
    let l2 = latency(op2);
    l0 + l1 + l2
}
fn main() {
    println!("{}", schedule_2(0, 2, 1));
    println!("{}", schedule_2(2, 3, 0));
    println!("{}", critical_path(0, 2, 4));
    for op in 0..6 {
        println!("{} {}", op, latency(op));
    }
}

