fn estimate_pi(n: i64, seed: i64) -> i64 {
    let mut count = 0;
    let mut s = seed;
    let m = 1000;
    for _i in 0..n {
        s = lcg_next(s, 137, 187, m);
        let x = s;
        s = lcg_next(s, 137, 187, m);
        let y = s;
        count = count + inside_circle(x - m / 2, y - m / 2, m / 2);
    }
    count * 400 / n
}
