fn alloc_phys(free_list: i64) -> i64 {
    let mut f = free_list;
    let mut reg = 0;
    while f % 2 == 0 && reg < 8 {
        f = f / 2;
        reg = reg + 1;
    }
    if reg >= 8 { -1 } else { reg }
}
fn mark_used(free_list: i64, reg: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..reg { bit = bit * 2; }
    if free_list / bit % 2 == 1 { free_list - bit } else { free_list }
}
fn mark_free(free_list: i64, reg: i64) -> i64 {
    let mut bit = 1;
    for _i in 0..reg { bit = bit * 2; }
    if free_list / bit % 2 == 0 { free_list + bit } else { free_list }
}
fn count_free(free_list: i64) -> i64 {
    let mut count = 0;
    let mut f = free_list;
    for _i in 0..8 {
        count = count + f % 2;
        f = f / 2;
    }
    count
}
fn main() {
    let mut fl = 255;
    println!("{}", count_free(fl));
    let r0 = alloc_phys(fl);
    fl = mark_used(fl, r0);
    let r1 = alloc_phys(fl);
    fl = mark_used(fl, r1);
    println!("{} {} {}", r0, r1, count_free(fl));
    fl = mark_free(fl, r0);
    println!("{}", count_free(fl));
}

