    for _i in 0..8 {
        let db = d % 2;
        let kb = k % 2;
        if db != kb { result = result + place; }
        d = d / 2;
        k = k / 2;
        place = place * 2;
    }
    result
}
fn lfsr_step(state: i64, tap1: i64, tap2: i64) -> i64 {
