    b1 = b1 % 2;
    let mut b2 = s;
    for _i in 0..tap2 { b2 = b2 / 2; }
    b2 = b2 % 2;
    let new_bit = if b1 != b2 { 1 } else { 0 };
    (s / 2) + new_bit * 128
}
