fn uleb128_encode(mut val: i64) -> i64 {
    let mut result = 0;
    let mut shift = 1;
    let mut bytes = 0;
    while val > 0 {
        let byte = val % 128;
        val = val / 128;
        let encoded = if val > 0 { byte + 128 } else { byte };
        result = result + encoded * shift;
        shift = shift * 256;
        bytes = bytes + 1;
    }
    if bytes == 0 { return 0; }
    result
}
fn uleb128_size(val: i64) -> i64 {
    if val == 0 { return 1; }
    let mut v = val;
    let mut size = 0;
    while v > 0 {
        v = v / 128;
        size = size + 1;
    }
    size
}
