fn gossip_round(infected: i64, total: i64, fanout: i64) -> i64 {
    let uninfected = total - infected;
    let new_infections = infected * fanout * uninfected / (total * total);
    if new_infections > uninfected { uninfected } else { new_infections }
}
fn gossip_converge(total: i64, fanout: i64) -> i64 {
    let mut infected = 1;
    let mut rounds = 0;
    while infected < total && rounds < 100 {
        let new = gossip_round(infected, total, fanout);
        if new == 0 { infected = infected + 1; }
        else { infected = infected + new; }
        if infected > total { infected = total; }
        rounds = rounds + 1;
    }
    rounds
}
