fn vc_increment(clock: i64, node: i64) -> i64 {
    let mut pow = 1;
    for _i in 0..node { pow = pow * 100; }
    clock + pow
}
fn vc_get(clock: i64, node: i64) -> i64 {
    let mut pow = 1;
    for _i in 0..node { pow = pow * 100; }
    (clock / pow) % 100
}
fn vc_merge(a: i64, b: i64, n: i64) -> i64 {
    let mut result = 0;
    let mut pow = 1;
    for i in 0..n {
        let va = vc_get(a, i);
        let vb = vc_get(b, i);
        let mx = if va > vb { va } else { vb };
        result = result + mx * pow;
        pow = pow * 100;
    }
    result
}
fn vc_happens_before(a: i64, b: i64, n: i64) -> i64 {
    let mut all_leq = 1;
    let mut some_lt = 0;
    for i in 0..n {
        let va = vc_get(a, i);
        let vb = vc_get(b, i);
        if va > vb { all_leq = 0; }
        if va < vb { some_lt = 1; }
    }
    if all_leq == 1 && some_lt == 1 { 1 } else { 0 }
}
fn main() {
    let mut c0 = 0;
    let mut c1 = 0;
    c0 = vc_increment(c0, 0);
    c0 = vc_increment(c0, 0);
