fn fnv_hash(x: i64) -> i64 {
    let mut h = 2166136261;
    h = ((h * 16777619) + x) % 1000000007;
    h
}
fn djb2_hash(x: i64) -> i64 {
    let mut h = 5381;
    h = h * 33 + x;
    h % 1000000007
}
fn bloom_add(filter: i64, item: i64, size: i64) -> i64 {
    let h1 = fnv_hash(item) % size;
    let h2 = djb2_hash(item) % size;
    let mut f = filter;
    let mut b1 = 1;
    for _i in 0..h1 { b1 = b1 * 2; }
    if f / b1 % 2 == 0 { f = f + b1; }
    let mut b2 = 1;
    for _i in 0..h2 { b2 = b2 * 2; }
    if f / b2 % 2 == 0 { f = f + b2; }
    f
}
fn bloom_test(filter: i64, item: i64, size: i64) -> i64 {
    let h1 = fnv_hash(item) % size;
    let h2 = djb2_hash(item) % size;
    let mut b1 = 1;
    for _i in 0..h1 { b1 = b1 * 2; }
    let mut b2 = 1;
    for _i in 0..h2 { b2 = b2 * 2; }
    if filter / b1 % 2 == 1 && filter / b2 % 2 == 1 { 1 } else { 0 }
}
fn main() {
    let size = 16;
    let mut f = 0;
    f = bloom_add(f, 42, size);
    f = bloom_add(f, 99, size);
    println!("{}", bloom_test(f, 42, size));
    println!("{}", bloom_test(f, 99, size));
}

