fn xor_pad(key: i64, pad: i64) -> i64 {
    let mut result = 0;
    let mut k = key;
    let mut p = pad;
    let mut place = 1;
    for _i in 0..8 {
        let kb = k % 2;
        let pb = p % 2;
        if kb != pb { result = result + place; }
        k = k / 2;
        p = p / 2;
        place = place * 2;
    }
    result
}
