fn ones_complement_add(a: i64, b: i64) -> i64 {
    let sum = a + b;
    let carry = sum / 65536;
    (sum % 65536) + carry
}
fn checksum(w0: i64, w1: i64, w2: i64, w3: i64) -> i64 {
    let s1 = ones_complement_add(w0, w1);
    let s2 = ones_complement_add(s1, w2);
    let s3 = ones_complement_add(s2, w3);
    65535 - s3
}
fn verify_checksum(w0: i64, w1: i64, w2: i64, w3: i64, cksum: i64) -> i64 {
    let s = ones_complement_add(ones_complement_add(ones_complement_add(ones_complement_add(w0, w1), w2), w3), cksum);
    if s == 65535 { 1 } else { 0 }
}
