fn split_gini(left_pos: i64, left_total: i64, right_pos: i64, right_total: i64) -> i64 {
    let left_gini = if left_total == 0 { 0 }
        else { 1000 - (left_pos * left_pos + (left_total - left_pos) * (left_total - left_pos)) * 1000 / (left_total * left_total) };
    let right_gini = if right_total == 0 { 0 }
        else { 1000 - (right_pos * right_pos + (right_total - right_pos) * (right_total - right_pos)) * 1000 / (right_total * right_total) };
    let total = left_total + right_total;
    (left_gini * left_total + right_gini * right_total) / total
}
