fn dropout_mask(seed: i64, n: i64, keep_prob_pct: i64) -> i64 {
    let mut mask = 0;
    let mut s = seed;
    let mut bit = 1;
    for _i in 0..n {
        s = (s * 1103515245 + 12345) % 1000000;
        let r = s % 100;
        if r < keep_prob_pct { mask = mask + bit; }
        bit = bit * 2;
    }
    mask
}
