fn step_decay(initial_lr: i64, epoch: i64, drop_every: i64, drop_factor: i64, scale: i64) -> i64 {
    let drops = epoch / drop_every;
    let mut lr = initial_lr;
    for _i in 0..drops { lr = lr * drop_factor / scale; }
    lr
}
fn cosine_anneal(initial_lr: i64, epoch: i64, total_epochs: i64) -> i64 {
    initial_lr * (total_epochs - epoch) / total_epochs
}
fn warmup(initial_lr: i64, step: i64, warmup_steps: i64) -> i64 {
    if step >= warmup_steps { initial_lr }
    else { initial_lr * step / warmup_steps }
}
fn main() {
    for e in [0, 10, 20, 30, 40] {
        println!("{} {} {}", step_decay(100, e, 10, 50, 100),
                 cosine_anneal(100, e, 50),
