    let mut scores = [s0, s1, s2, s3];
    for i in 0..4 {
        for j in (i+1)..4 {
            if scores[j] > scores[i] {
                let tmp = scores[i];
                scores[i] = scores[j];
                scores[j] = tmp;
            }
        }
    }
    let mut sum = 0;
    for i in 0..k {
        sum = sum + scores[i as usize];
    }
    sum
}
