        4 => if right != 0 { left % right } else { 0 },
        5 => if left > right { left } else { right },
        6 => if left < right { left } else { right },
        _ => 0,
    }
}
fn eval_expr(op1: i64, a: i64, b: i64, op2: i64, c: i64) -> i64 {
    let r1 = eval_op(op1, a, b);
