fn count_false_shares(n: i64, spacing: i64, line_size: i64) -> i64 {
    let mut count = 0;
    let mut i = 0;
    while i < n {
        let mut j = i + 1;
        while j < n {
            if false_sharing(i * spacing, j * spacing, line_size) == 1 {
                count = count + 1;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    count
}
