fn plru_update(tree: i64, way: i64, ways: i64) -> i64 {
    let bit_pos = way;
    let mut new_tree = tree;
    let mut pos = way;
    let mut level = ways / 2;
    while level >= 1 {
        if pos % 2 == 0 {
            new_tree = new_tree + level;
        }
        pos = pos / 2;
        level = level / 2;
    }
    new_tree % (ways * 2)
}
fn plru_victim(tree: i64, ways: i64) -> i64 {
    let mut pos = 0;
    let mut level = ways / 2;
    while level >= 1 {
        if (tree / level) % 2 == 0 {
            pos = pos * 2;
        } else {
            pos = pos * 2 + 1;
        }
        level = level / 2;
    }
    pos % ways
}
