fn mask_from_prefix(prefix_len: i64) -> i64 {
    let mut mask = 0;
    let mut i = 0;
    while i < prefix_len {
        mask = mask * 2 + 1;
        i = i + 1;
    }
    let mut j = prefix_len;
    while j < 32 {
        mask = mask * 2;
        j = j + 1;
    }
    mask
}
fn network_addr(ip: i64, mask: i64) -> i64 {
    let mut result = 0;
    let mut ip_bits = ip;
    let mut mask_bits = mask;
    let mut pos = 1;
    let mut k = 0;
    while k < 32 {
        let ip_bit = ip_bits % 2;
        let mask_bit = mask_bits % 2;
        if ip_bit == 1 && mask_bit == 1 {
            result = result + pos;
        }
        ip_bits = ip_bits / 2;
        mask_bits = mask_bits / 2;
        pos = pos * 2;
        k = k + 1;
    }
    result
}
