fn simulate_transfer(data_size: i64, window: i64, segment_size: i64) -> i64 {
    let mut sent = 0;
    let mut rounds = 0;
    while sent < data_size {
        let can_send = window_available(window, 0);
        let segments = can_send / segment_size;
        if segments <= 0 {
            return rounds;
        }
        sent = sent + segments * segment_size;
        rounds = rounds + 1;
    }
    rounds
}
