fn leak(bucket: i64, leak_rate: i64) -> i64 {
    let remaining = bucket - leak_rate;
    if remaining < 0 { 0 } else { remaining }
}
fn add_to_bucket(bucket: i64, amount: i64, capacity: i64) -> i64 {
    let new_level = bucket + amount;
    if new_level > capacity { -1 } else { new_level }
}
fn simulate(arrivals: i64, count: i64, capacity: i64, leak_rate: i64) -> i64 {
    let mut bucket = 0;
    let mut drops = 0;
    let mut a = arrivals;
    let mut i = 0;
    while i < count {
        let pkt = a % 100;
        bucket = leak(bucket, leak_rate);
        let result = add_to_bucket(bucket, pkt, capacity);
        if result < 0 {
            drops = drops + 1;
        } else {
            bucket = result;
        }
        a = a / 100;
        i = i + 1;
    }
    drops
}
