fn rotate_right(val: i64, amount: i64, bits: i64) -> i64 {
    let mask = (1 * 65536) - 1;
    let lower = val % mask;
    let mut shifted = lower;
    let mut i = 0;
    while i < amount {
        let bit = shifted % 2;
        shifted = shifted / 2;
        if bit == 1 {
            shifted = shifted + mask / 2;
        }
        i = i + 1;
    }
    shifted
}
fn sha_ch(e: i64, f: i64, g: i64) -> i64 {
    let mut result = 0;
    let mut ee = e;
    let mut ff = f;
    let mut gg = g;
