    let mut i = 0;
    while i < 16 {
        let e_bit = ee % 2;
        let f_bit = ff % 2;
        let g_bit = gg % 2;
        let ch_bit = if e_bit == 1 { f_bit } else { g_bit };
        result = result + ch_bit * pos;
        ee = ee / 2;
        ff = ff / 2;
        gg = gg / 2;
        pos = pos * 2;
        i = i + 1;
    }
    result
}
