fn simple_hash(data: i64, seed: i64) -> i64 {
    let mut h = seed;
    let mut d = data;
    let mut i = 0;
    while i < 8 {
        h = (h * 31 + d % 256) % 1000000;
        d = d / 256;
        i = i + 1;
    }
    h
}
