    let b3 = combined % 64;
    let b2 = (combined / 64) % 64;
    let b1 = (combined / 4096) % 64;
    let b0 = (combined / 262144) % 64;
    b0 * 1000000 + b1 * 10000 + b2 * 100 + b3
}
