    let b0 = encoded / 1000000;
    let b1 = (encoded / 10000) % 100;
    let b2 = (encoded / 100) % 100;
    let b3 = encoded % 100;
    let combined = b0 * 262144 + b1 * 4096 + b2 * 64 + b3;
    combined
}
