fn entropy_estimate(freq: i64, count: i64, total: i64) -> i64 {
    let mut ent = 0;
    let mut f = freq;
    let mut i = 0;
    while i < count {
        let fi = f % 100;
        if fi > 0 {
            let p_scaled = (fi * 100) / total;
            let log_p = log2_approx(100) - log2_approx(p_scaled);
            ent = ent + fi * log_p;
        }
        f = f / 100;
        i = i + 1;
    }
    ent / total
}
