fn combine_two_min(freqs: i64, count: i64) -> i64 {
    let mut min1 = 999999;
    let mut min2 = 999999;
    let mut f = freqs;
    let mut i = 0;
    while i < count {
        let freq = f % 1000;
        if freq < min1 {
            min2 = min1;
            min1 = freq;
        } else if freq < min2 {
            min2 = freq;
        }
        f = f / 1000;
        i = i + 1;
    }
    min1 + min2
}
fn avg_code_length(freqs: i64, count: i64, total: i64) -> i64 {
    let mut total_bits = 0;
    let mut f = freqs;
    let mut depth = 1;
    let mut remaining = count;
    while remaining > 1 {
        let combined = combine_two_min(f, remaining);
        total_bits = total_bits + combined;
        remaining = remaining - 1;
        depth = depth + 1;
    }
    (total_bits * 100) / total
}
