fn bloom_add(filter: i64, val: i64, size: i64) -> i64 {
    let h1 = hash1(val, size);
    let h2 = hash2(val, size);
    let mut f = filter;
    let mut p1 = 1;
    let mut i = 0;
    while i < h1 {
        p1 = p1 * 2;
        i = i + 1;
    }
    f = f + p1;
    let mut p2 = 1;
    i = 0;
    while i < h2 {
        p2 = p2 * 2;
        i = i + 1;
    }
    f = f + p2;
    f
}
fn bloom_check(filter: i64, val: i64, size: i64) -> i64 {
    let h1 = hash1(val, size);
    let h2 = hash2(val, size);
    let mut f1 = filter;
    let mut i = 0;
    while i < h1 {
        f1 = f1 / 2;
        i = i + 1;
    }
    let b1 = f1 % 2;
    let mut f2 = filter;
    i = 0;
    while i < h2 {
        f2 = f2 / 2;
        i = i + 1;
    }
    let b2 = f2 % 2;
    if b1 == 1 && b2 == 1 { 1 } else { 0 }
}
