fn rotl(val: i64, n: i64) -> i64 {
    let mask = 65535;
    let v = val % mask;
    let mut left = v;
    let mut right = v;
    let mut i = 0;
    while i < n {
        left = (left * 2) % mask;
        i = i + 1;
    }
    i = 0;
    while i < (16 - n) {
        right = right / 2;
        i = i + 1;
    }
    (left + right) % mask
}
