fn is_feasible(deadlines: i64, wcets: i64, count: i64) -> i64 {
    let mut utilization = 0;
    let mut d = deadlines;
    let mut w = wcets;
    let mut i = 0;
    while i < count {
        let deadline = d % 100;
        let wcet = w % 100;
        if deadline > 0 {
            utilization = utilization + (wcet * 100) / deadline;
        }
        d = d / 100;
        w = w / 100;
        i = i + 1;
    }
    if utilization <= 100 { 1 } else { 0 }
}
