fn simulate_pi(tasks: i64, count: i64) -> i64 {
    let mut inversions = 0;
    let mut t = tasks;
    let mut i = 0;
    while i < count {
        let blocked = t % 2;
        t = t / 2;
        let running = t % 2;
        t = t / 2;
        let holding = t % 2;
        t = t / 2;
        if has_inversion(blocked, running, holding) == 1 {
            inversions = inversions + 1;
        }
        i = i + 1;
    }
    inversions
}
