fn simulate_rw(ops: i64, count: i64) -> i64 {
    let mut readers = 0;
    let mut writers = 0;
    let mut blocked = 0;
    let mut o = ops;
    let mut i = 0;
    while i < count {
        let op = o % 10;
        if op == 1 {
            if can_read(writers) == 1 { readers = readers + 1; }
            else { blocked = blocked + 1; }
        } else if op == 2 {
            if can_write(readers, writers) == 1 { writers = writers + 1; }
            else { blocked = blocked + 1; }
        } else if op == 3 {
            if readers > 0 { readers = readers - 1; }
        } else if op == 4 {
            if writers > 0 { writers = writers - 1; }
        }
        o = o / 10;
        i = i + 1;
    }
    blocked
}
