fn pipe_write(buf_used: i64, amount: i64, capacity: i64) -> i64 {
    let space = capacity - buf_used;
    if amount <= space { buf_used + amount } else { -1 }
}
fn pipe_read(buf_used: i64, amount: i64) -> i64 {
    if amount <= buf_used { buf_used - amount } else { -1 }
}
fn simulate_pipe(ops: i64, count: i64, capacity: i64) -> i64 {
    let mut buf = 0;
    let mut blocked = 0;
    let mut o = ops;
    let mut i = 0;
    while i < count {
        let op = o % 10;
        let amount = (o / 10) % 10;
        if op % 2 == 1 {
            let result = pipe_write(buf, amount, capacity);
            if result < 0 { blocked = blocked + 1; }
            else { buf = result; }
        } else {
            let result = pipe_read(buf, amount);
            if result < 0 { blocked = blocked + 1; }
            else { buf = result; }
        }
        o = o / 100;
        i = i + 1;
    }
    blocked
}
