fn sig_bit(signum: i64) -> i64 {
    let mut bit = 1;
    let mut i = 0;
    while i < signum {
        bit = bit * 2;
        i = i + 1;
    }
    bit
}
fn sig_add(mask: i64, signum: i64) -> i64 {
    mask + sig_bit(signum)
}
fn sig_del(mask: i64, signum: i64) -> i64 {
    let bit = sig_bit(signum);
    let mut m = mask;
    let check = (m / bit) % 2;
    if check == 1 { m - bit } else { m }
}
fn sig_ismember(mask: i64, signum: i64) -> i64 {
    let bit = sig_bit(signum);
    (mask / bit) % 2
}
fn sig_count(mask: i64, max_sig: i64) -> i64 {
    let mut count = 0;
    let mut m = mask;
    let mut i = 0;
    while i < max_sig {
        count = count + m % 2;
        m = m / 2;
        i = i + 1;
    }
    count
}
fn main() {
    let mut mask = 0;
    mask = sig_add(mask, 2);
    mask = sig_add(mask, 9);
    mask = sig_add(mask, 15);
    println!("mask={} count={}", mask, sig_count(mask, 16));
    println!("has_2={} has_9={} has_3={}", sig_ismember(mask, 2), sig_ismember(mask, 9), sig_ismember(mask, 3));
    mask = sig_del(mask, 9);
    println!("after_del9: has_9={} count={}", sig_ismember(mask, 9), sig_count(mask, 16));
}

