fn region_contains(base: i64, size: i64, addr: i64) -> i64 {
    if addr >= base && addr < base + size { 1 } else { 0 }
}
fn regions_overlap(b1: i64, s1: i64, b2: i64, s2: i64) -> i64 {
    if b1 + s1 <= b2 { 0 }
    else if b2 + s2 <= b1 { 0 }
    else { 1 }
}
fn find_gap(regions: i64, count: i64, size_needed: i64) -> i64 {
    let mut prev_end = 0;
    let mut r = regions;
    let mut i = 0;
    while i < count {
        let base = (r % 1000) * 1000;
        let sz = ((r / 1000) % 100) * 1000;
        if base - prev_end >= size_needed {
            return prev_end;
        }
        prev_end = base + sz;
        r = r / 100000;
        i = i + 1;
    }
    prev_end
}
