    let base_score = (rss_pages * 1000) / total_pages;
    let adjusted = base_score + adj;
    if adjusted < 0 { 0 }
    else if adjusted > 1000 { 1000 }
    else { adjusted }
}
fn oom_victim(scores: i64, count: i64) -> i64 {
    let mut max_score = -1;
    let mut victim = 0;
    let mut s = scores;
    let mut i = 0;
    while i < count {
        let score = s % 1000;
        if score > max_score {
            max_score = score;
            victim = i;
        }
        s = s / 1000;
        i = i + 1;
    }
    victim
}
