    if current == 0 {
        if event == 1 { 1 } else { 0 }
    } else if current == 1 {
        if event == 2 { 2 }
        else if event == 3 { 3 }
        else if event == 4 { 4 }
        else { 1 }
    } else if current == 2 {
        if event == 5 { 1 }
        else { 2 }
    } else if current == 3 {
        if event == 6 { 1 }
        else { 3 }
    } else if current == 4 {
        5
    } else {
        current
    }
}
