fn load_imbalance(load_a: i64, load_b: i64) -> i64 {
    let diff = load_a - load_b;
    if diff < 0 { 0 - diff } else { diff }
}
fn should_balance(imbalance: i64, threshold: i64) -> i64 {
    if imbalance > threshold { 1 } else { 0 }
}
fn tasks_to_migrate(imbalance: i64, task_weight: i64) -> i64 {
    if task_weight == 0 { 0 }
    else { imbalance / (2 * task_weight) }
}
fn balance_domains(loads: i64, count: i64, threshold: i64) -> i64 {
    let mut migrations = 0;
    let mut l = loads;
    let mut i = 0;
    while i < count - 1 {
        let load_i = l % 100;
        let load_next = (l / 100) % 100;
        let imb = load_imbalance(load_i, load_next);
        if should_balance(imb, threshold) == 1 {
            migrations = migrations + tasks_to_migrate(imb, 10);
        }
        l = l / 100;
        i = i + 1;
    }
    migrations
}
