fn btree_search(keys: i64, count: i64, target: i64) -> i64 {
    let mut k = keys;
    let mut i = 0;
    while i < count {
        let key = k % 100;
        if key == target { return i; }
        if target < key { return -(i + 1); }
        k = k / 100;
        i = i + 1;
    }
    -(count + 1)
}
fn btree_height(n: i64, order: i64) -> i64 {
    if n <= 0 { return 0; }
    let mut h = 1;
    let mut capacity = order - 1;
    while capacity < n {
        capacity = capacity * order;
        h = h + 1;
    }
    h
}
