fn hash_join_cost(build_rows: i64, probe_rows: i64, page_size: i64) -> i64 {
    let build_pages = (build_rows + page_size - 1) / page_size;
    let probe_pages = (probe_rows + page_size - 1) / page_size;
    3 * build_pages + probe_pages
}
fn nested_loop_cost(outer_rows: i64, inner_pages: i64) -> i64 {
    outer_rows * inner_pages
}
fn best_join(rows_a: i64, rows_b: i64, page_size: i64) -> i64 {
    let hj = hash_join_cost(rows_a, rows_b, page_size);
    let nl = nested_loop_cost(rows_a, (rows_b + page_size - 1) / page_size);
    if hj < nl { 1 } else { 2 }
}
