}
fn evict_lru(ages: i64, count: i64) -> i64 {
    let mut max_age = 0;
    let mut victim = 0;
    let mut a = ages;
    let mut i = 0;
    while i < count {
        let age = a % 100;
        if age > max_age {
            max_age = age;
            victim = i;
        }
        a = a / 100;
        i = i + 1;
    }
    victim
}
