fn lock_compat(held: i64, requested: i64) -> i64 {
    if held == 0 { 1 }
    else if held == 1 && requested == 1 { 1 }
    else { 0 }
}
fn acquire_lock(locks: i64, txn: i64, mode: i64) -> i64 {
    let held_mode = locks % 10;
    if lock_compat(held_mode, mode) == 1 {
        txn * 10 + mode
    } else {
