    }
}
fn deadlock_detect(waits_for: i64, count: i64) -> i64 {
    let mut visited = 0;
    let mut w = waits_for;
    let mut i = 0;
    while i < count {
        let target = w % 10;
        let mut power = 1;
        let mut j = 0;
        while j < target {
            power = power * 2;
            j = j + 1;
        }
        if (visited / power) % 2 == 1 {
            return 1;
        }
        let mut my_power = 1;
        j = 0;
        while j < i {
            my_power = my_power * 2;
            j = j + 1;
        }
        visited = visited + my_power;
        w = w / 10;
        i = i + 1;
    }
    0
}
