    println!("{}", lock_compat(0, 1));
    println!("{}", lock_compat(1, 1));
    println!("{}", lock_compat(1, 2));
    println!("{}", lock_compat(2, 1));
    println!("{}", acquire_lock(0, 5, 1));
    println!("{}", deadlock_detect(120, 3));
}

