fn gossip_round(infected: i64, total: i64, fanout: i64) -> i64 {
    let healthy = total - infected;
    let new_infections = (infected * fanout * healthy) / (total * total);
    let new_total = infected + new_infections;
    if new_total > total { total } else { new_total }
}
