    let mut completed = 0;
    let mut i = 0;
    while i < count {
        if i == fail_at {
            let mut j = completed - 1;
            while j >= 0 {
                let comp = step_compensate(j);
                j = j - 1;
            }
            return -(completed);
        }
        let result = step_execute(i);
        completed = completed + 1;
        i = i + 1;
    }
    completed
}
