fn is_covered(pattern_bits: i64, total_variants: i64) -> i64 {
    let mut covered = 0;
    let mut p = pattern_bits;
    let mut i = 0;
    while i < total_variants {
        covered = covered + p % 2;
        p = p / 2;
        i = i + 1;
    }
    if covered == total_variants { 1 } else { 0 }
}
fn missing_variants(pattern_bits: i64, total_variants: i64) -> i64 {
    let mut missing = 0;
    let mut p = pattern_bits;
    let mut i = 0;
    while i < total_variants {
        if p % 2 == 0 { missing = missing + 1; }
        p = p / 2;
        i = i + 1;
    }
