}
fn usefulness(pattern: i64, existing: i64) -> i64 {
    let mut p = pattern;
    let mut e = existing;
    let mut i = 0;
    while i < 8 {
        let pb = p % 2;
        let eb = e % 2;
        if pb == 1 && eb == 0 { return 1; }
        p = p / 2;
        e = e / 2;
        i = i + 1;
    }
    0
}
