}
fn combine_effects(a: i64, b: i64) -> i64 {
    let mut result = 0;
    let mut aa = a;
    let mut bb = b;
    let mut pos = 1;
    let mut i = 0;
    while i < 8 {
        let ab = aa % 2;
        let bb_bit = bb % 2;
        let or_bit = if ab == 1 { 1 } else { bb_bit };
        result = result + or_bit * pos;
        aa = aa / 2;
        bb = bb / 2;
        pos = pos * 2;
        i = i + 1;
    }
    result
}
