fn dropout_mask(seed: i64, size: i64, keep_prob: i64) -> i64 {
    let mut mask = 0;
    let mut s = seed;
    let mut pos = 1;
    let mut i = 0;
    while i < size {
        s = (s * 1103515245 + 12345) % 1000000;
        let keep = if (s % 100) < keep_prob { 1 } else { 0 };
        mask = mask + keep * pos;
        pos = pos * 2;
        i = i + 1;
    }
    mask
}
fn apply_dropout(values: i64, mask: i64, count: i64, scale: i64) -> i64 {
    let mut result = 0;
    let mut v = values;
    let mut m = mask;
    let mut pos = 1;
    let mut i = 0;
    while i < count {
        let val = v % 100;
        let keep = m % 2;
        result = result + (val * keep * scale / 100) * pos;
        v = v / 100;
        m = m / 2;
        pos = pos * 100;
        i = i + 1;
    }
    result
}
