fn step_decay(initial_lr: i64, epoch: i64, decay_epochs: i64, factor: i64) -> i64 {
    let mut lr = initial_lr;
    let steps = epoch / decay_epochs;
    let mut i = 0;
    while i < steps {
        lr = (lr * factor) / 100;
        i = i + 1;
    }
    lr
}
fn cosine_anneal(initial_lr: i64, epoch: i64, max_epochs: i64) -> i64 {
    let progress = (epoch * 100) / max_epochs;
    let cos_approx = 100 - progress;
    if cos_approx < 0 { 0 }
    else { (initial_lr * cos_approx) / 100 }
}
fn warmup(target_lr: i64, epoch: i64, warmup_epochs: i64) -> i64 {
    if epoch >= warmup_epochs { target_lr }
    else { (target_lr * epoch) / warmup_epochs }
}
