fn clip_value(grad: i64, max_val: i64) -> i64 {
    if grad > max_val { max_val }
    else if grad < 0 - max_val { 0 - max_val }
    else { grad }
}
fn grad_norm(grads: i64, count: i64) -> i64 {
    let mut sum_sq = 0;
    let mut g = grads;
    let mut i = 0;
    while i < count {
        let grad = (g % 100) - 50;
        sum_sq = sum_sq + grad * grad;
        g = g / 100;
        i = i + 1;
    }
    let mut s = 1;
    while s * s < sum_sq {
        s = s + 1;
    }
    s
}
fn clip_by_norm(grad: i64, norm: i64, max_norm: i64) -> i64 {
    if norm <= max_norm { grad }
    else { (grad * max_norm) / norm }
}
