fn adam_step(m: i64, v: i64, grad: i64, beta1: i64, beta2: i64) -> i64 {
    let new_m = (beta1 * m + (1000 - beta1) * grad) / 1000;
    new_m
}
fn adam_v_step(v: i64, grad: i64, beta2: i64) -> i64 {
    (beta2 * v + (1000 - beta2) * grad * grad / 1000) / 1000
}
fn adam_update(weight: i64, m_hat: i64, v_hat: i64, lr: i64) -> i64 {
    let mut sqrt_v = 1;
    while sqrt_v * sqrt_v < v_hat {
        sqrt_v = sqrt_v + 1;
    }
    weight - (lr * m_hat) / (sqrt_v + 1)
}
