fn manhattan_dist(a: i64, b: i64, dims: i64) -> i64 {
    let mut dist = 0;
    let mut aa = a;
    let mut bb = b;
    let mut i = 0;
    while i < dims {
        let diff = (aa % 100) - (bb % 100);
        let abs_diff = if diff < 0 { 0 - diff } else { diff };
        dist = dist + abs_diff;
        aa = aa / 100;
        bb = bb / 100;
        i = i + 1;
    }
    dist
}
fn majority_vote(labels: i64, count: i64) -> i64 {
    let mut count_0 = 0;
    let mut count_1 = 0;
    let mut l = labels;
    let mut i = 0;
    while i < count {
        if l % 2 == 0 { count_0 = count_0 + 1; }
        else { count_1 = count_1 + 1; }
        l = l / 2;
        i = i + 1;
    }
    if count_1 > count_0 { 1 } else { 0 }
}
