fn gini_impurity(class0: i64, class1: i64) -> i64 {
    let total = class0 + class1;
    if total == 0 { 0 }
    else {
        let p0 = (class0 * 100) / total;
        let p1 = (class1 * 100) / total;
        100 - (p0 * p0 + p1 * p1) / 100
    }
}
fn info_gain(parent_imp: i64, left_imp: i64, right_imp: i64, left_n: i64, right_n: i64) -> i64 {
    let total = left_n + right_n;
    if total == 0 { 0 }
    else {
        let weighted = (left_imp * left_n + right_imp * right_n) / total;
        parent_imp - weighted
    }
}
