}
fn precision(tp: i64, fp: i64) -> i64 {
    let total = tp + fp;
    if total == 0 { 0 }
    else { (tp * 100) / total }
}
fn recall(tp: i64, fn_val: i64) -> i64 {
    let total = tp + fn_val;
    if total == 0 { 0 }
    else { (tp * 100) / total }
}
fn f1_score(prec: i64, rec: i64) -> i64 {
    if prec + rec == 0 { 0 }
    else { (2 * prec * rec) / (prec + rec) }
}
