fn fir_output(input: i64, coeffs: i64, taps: i64) -> i64 {
    let mut sum = 0;
    let mut inp = input;
    let mut c = coeffs;
    let mut i = 0;
    while i < taps {
        let x = inp % 100;
        let h = c % 100 - 50;
        sum = sum + x * h;
        inp = inp / 100;
        c = c / 100;
        i = i + 1;
    }
    sum / 100
}
