fn pid_step(error: i64, integral: i64, prev_error: i64, kp: i64, ki: i64, kd: i64) -> i64 {
    let p_term = kp * error;
    let i_term = ki * integral;
    let d_term = kd * (error - prev_error);
    (p_term + i_term + d_term) / 100
}
