    while i < 8 {
        let error = setpoint - value;
        integral = integral + error;
        let output = pid_step(error, integral, prev_error, kp, ki, kd);
        value = value + output;
        println!("t={} val={} err={} out={}", i, value, error, output);
        prev_error = error;
        i = i + 1;
    }
}

fn dft_bin(signal: i64, count: i64, freq: i64) -> i64 {
    let mut real = 0;
    let mut imag = 0;
    let mut s = signal;
    let mut i = 0;
    while i < count {
        let val = s % 100;
        let angle = (i * freq * 360) / count;
        let cos_approx = if angle % 360 < 90 { 100 - angle % 90 }
            else if angle % 360 < 180 { -(angle % 90) }
            else if angle % 360 < 270 { -(100 - angle % 90) }
            else { angle % 90 };
        real = real + (val * cos_approx) / 100;
        s = s / 100;
        i = i + 1;
    }
    if real < 0 { 0 - real } else { real }
}
fn main() {
