fn payoff(strategy_a: i64, strategy_b: i64, matrix: i64) -> i64 {
    let idx = strategy_a * 2 + strategy_b;
    let mut m = matrix;
    let mut i = 0;
    while i < idx {
        m = m / 100;
        i = i + 1;
    }
    m % 100
}
fn best_response_a(strategy_b: i64, matrix: i64) -> i64 {
    let p0 = payoff(0, strategy_b, matrix);
    let p1 = payoff(1, strategy_b, matrix);
    if p0 >= p1 { 0 } else { 1 }
}
fn best_response_b(strategy_a: i64, matrix: i64) -> i64 {
    let p0 = payoff(strategy_a, 0, matrix);
    let p1 = payoff(strategy_a, 1, matrix);
    if p0 >= p1 { 0 } else { 1 }
}
fn is_nash(sa: i64, sb: i64, matrix: i64) -> i64 {
    if best_response_a(sb, matrix) == sa && best_response_b(sa, matrix) == sb {
        1
    } else {
        0
    }
}
fn main() {
    let matrix = 1050305;
    for sa in 0..2 {
        for sb in 0..2 {
            println!("({},{}) payoff={} nash={}", sa, sb, payoff(sa, sb, matrix), is_nash(sa, sb, matrix));
        }
    }
}

fn minimax(depth: i64, is_max: i64, alpha: i64, beta: i64) -> i64 {
    if depth == 0 {
        return alpha + beta;
    }
    if is_max == 1 {
        let left = minimax(depth - 1, 0, alpha, beta);
        let right = minimax(depth - 1, 0, alpha + 1, beta);
        if left > right { left } else { right }
    } else {
        let left = minimax(depth - 1, 1, alpha, beta);
        let right = minimax(depth - 1, 1, alpha, beta + 1);
        if left < right { left } else { right }
    }
}
fn main() {
    for d in 0..5 {
        println!("depth {} val={}", d, minimax(d, 1, 0, 0));
    }
}

fn nfa_step(states: i64, input: i64, trans: i64) -> i64 {
    let mut new_states = 0;
    let mut s = states;
    let mut i = 0;
    while i < 8 {
        if s % 2 == 1 {
            let transitions = (trans / (i * 100 + input)) % 256;
            new_states = new_states + transitions;
        }
        s = s / 2;
        i = i + 1;
    }
    new_states % 256
}
fn is_accepting(states: i64, accept_mask: i64) -> i64 {
    let mut s = states;
    let mut a = accept_mask;
    let mut i = 0;
    while i < 8 {
        if s % 2 == 1 && a % 2 == 1 { return 1; }
        s = s / 2;
        a = a / 2;
        i = i + 1;
    }
    0
}
