}

fn push(stack: i64, symbol: i64) -> i64 {
    stack * 10 + symbol
}
fn pop(stack: i64) -> i64 {
    stack / 10
}
fn top(stack: i64) -> i64 {
    stack % 10
}
fn match_parens(input: i64, len: i64) -> i64 {
    let mut stack = 0;
    let mut inp = input;
    let mut i = 0;
    while i < len {
        let ch = inp % 10;
        if ch == 1 {
            stack = push(stack, 1);
        } else if ch == 2 {
            if stack == 0 { return 0; }
            if top(stack) != 1 { return 0; }
            stack = pop(stack);
        }
        inp = inp / 10;
        i = i + 1;
    }
    if stack == 0 { 1 } else { 0 }
}
fn main() {
    println!("{}", match_parens(2121, 4));
    println!("{}", match_parens(2211, 4));
    println!("{}", match_parens(221, 3));
    println!("{}", match_parens(211, 3));
}

fn tm_step(state: i64, symbol: i64) -> i64 {
    if state == 0 && symbol == 0 { 110 }
    else if state == 0 && symbol == 1 { 211 }
    else if state == 1 && symbol == 0 { 110 }
    else if state == 1 && symbol == 1 { 200 }
    else { 999 }
}
fn get_write(action: i64) -> i64 {
    action % 10
}
fn get_move(action: i64) -> i64 {
    (action / 10) % 10
}
fn get_next_state(action: i64) -> i64 {
    action / 100
}
fn main() {
    let mut state = 0;
    let mut pos = 5;
    let mut tape = 0;
    let mut steps = 0;
    while state < 2 && steps < 20 {
        let mut power = 1;
        let mut i = 0;
        while i < pos {
            power = power * 2;
            i = i + 1;
        }
        let symbol = (tape / power) % 2;
        let action = tm_step(state, symbol);
        if action == 999 { state = 99; }
        else {
            let write = get_write(action);
            if symbol == 0 && write == 1 { tape = tape + power; }
            else if symbol == 1 && write == 0 { tape = tape - power; }
            let mv = get_move(action);
            if mv == 1 { pos = pos + 1; }
            else { if pos > 0 { pos = pos - 1; } }
            state = get_next_state(action);
        }
        println!("step={} state={} pos={} tape={}", steps, state, pos, tape);
        steps = steps + 1;
    }
}

