        let pb = p % 2;
        if pb == 1 && sb == 0 { return 0; }
        s = s / 2;
        p = p / 2;
        i = i + 1;
    }
    1
}
fn reachable_count(start: i64, trans_mask: i64, steps: i64) -> i64 {
    let mut states = start;
    let mut i = 0;
    while i < steps {
        states = states + trans_mask;
        states = states % 256;
        i = i + 1;
    }
    let mut count = 0;
    let mut s = states;
    let mut j = 0;
    while j < 8 {
        count = count + s % 2;
        s = s / 2;
        j = j + 1;
    }
    count
}
