fn find_max(bids: i64, count: i64) -> i64 {
    let mut max_bid = 0;
    let mut max_idx = 0;
    let mut b = bids;
    let mut i = 0;
    while i < count {
        let bid = b % 1000;
        if bid > max_bid {
            max_bid = bid;
            max_idx = i;
        }
        b = b / 1000;
        i = i + 1;
    }
    max_idx
}
fn second_price(bids: i64, count: i64) -> i64 {
    let winner = find_max(bids, count);
    let mut second = 0;
    let mut b = bids;
    let mut i = 0;
    while i < count {
        let bid = b % 1000;
        if i != winner && bid > second {
            second = bid;
        }
        b = b / 1000;
        i = i + 1;
    }
    second
}
fn main() {
