fn fp_mul(a: i64, b: i64, frac_bits: i64) -> i64 {
    let mut shift = 1;
    let mut i = 0;
    while i < frac_bits {
        shift = shift * 2;
        i = i + 1;
    }
    (a * b) / shift
}
fn fp_div(a: i64, b: i64, frac_bits: i64) -> i64 {
    let mut shift = 1;
    let mut i = 0;
    while i < frac_bits {
        shift = shift * 2;
        i = i + 1;
    }
    if b == 0 { 0 }
    else { (a * shift) / b }
}
