fn unit_propagate(clauses: i64, assignment: i64) -> i64 {
    let mut c = clauses;
    let mut new_assign = assignment;
    let mut i = 0;
    while i < 4 {
        let clause = c % 100;
        let lit = clause % 10;
        let sign = (clause / 10) % 10;
        let mut power = 1;
        let mut j = 0;
        while j < lit {
            power = power * 2;
            j = j + 1;
        }
        let assigned = (new_assign / power) % 2;
        if assigned == 0 && sign == 1 {
            new_assign = new_assign + power;
        }
        c = c / 100;
        i = i + 1;
    }
    new_assign
}
fn count_satisfied(clauses: i64, assignment: i64, count: i64) -> i64 {
    let mut sat = 0;
    let mut c = clauses;
    let mut i = 0;
    while i < count {
        let clause = c % 100;
        let lit = clause % 10;
        let sign = (clause / 10) % 10;
        let mut power = 1;
        let mut j = 0;
        while j < lit {
            power = power * 2;
            j = j + 1;
        }
        let val = (assignment / power) % 2;
        if val == sign { sat = sat + 1; }
        c = c / 100;
        i = i + 1;
    }
    sat
}
fn main() {
    let clauses = 12110311;
    let assign = unit_propagate(clauses, 0);
    println!("assign={}", assign);
    println!("satisfied={}", count_satisfied(clauses, assign, 4));
}

fn bdd_eval(var: i64, low: i64, high: i64, assignment: i64) -> i64 {
    let mut power = 1;
    let mut i = 0;
    while i < var {
        power = power * 2;
        i = i + 1;
    }
    let val = (assignment / power) % 2;
    if val == 0 { low } else { high }
}
fn bdd_and(a: i64, b: i64) -> i64 {
    if a == 1 && b == 1 { 1 } else { 0 }
}
fn bdd_or(a: i64, b: i64) -> i64 {
    if a == 1 { 1 } else if b == 1 { 1 } else { 0 }
}
fn eval_formula(assignment: i64) -> i64 {
    let x0 = assignment % 2;
    let x1 = (assignment / 2) % 2;
    let x2 = (assignment / 4) % 2;
    bdd_or(bdd_and(x0, x1), x2)
}
