    }
    let available = t % 100;
    if available >= required { 1 } else { 0 }
}
fn fire(tokens: i64, from_place: i64, to_place: i64) -> i64 {
    let mut from_power = 1;
    let mut i = 0;
    while i < from_place {
        from_power = from_power * 100;
        i = i + 1;
    }
    let mut to_power = 1;
    i = 0;
    while i < to_place {
        to_power = to_power * 100;
        i = i + 1;
    }
    tokens - from_power + to_power
}
