fn globally(trace: i64, prop: i64, length: i64) -> i64 {
    let mut t = trace;
    let mut i = 0;
    while i < length {
        let state = t % 10;
        if state != prop { return 0; }
        t = t / 10;
        i = i + 1;
    }
    1
}
fn eventually(trace: i64, prop: i64, length: i64) -> i64 {
    let mut t = trace;
    let mut i = 0;
    while i < length {
        let state = t % 10;
        if state == prop { return 1; }
        t = t / 10;
        i = i + 1;
    }
    0
}
fn until_op(trace: i64, p: i64, q: i64, length: i64) -> i64 {
    let mut t = trace;
    let mut i = 0;
    while i < length {
        let state = t % 10;
        if state == q { return 1; }
        if state != p { return 0; }
        t = t / 10;
        i = i + 1;
    }
    0
}
