}
fn simulate_chain(start: i64, trans: i64, steps: i64) -> i64 {
    let mut state = start;
    let mut visit_counts = 0;
    let mut i = 0;
    while i < steps {
        let next = markov_step(state, trans);
        state = next % 3;
        let mut power = 1;
        let mut j = 0;
        while j < state {
            power = power * 1000;
            j = j + 1;
        }
        visit_counts = visit_counts + power;
        i = i + 1;
    }
    visit_counts
}
