}

fn draw_line(x0: i64, y0: i64, x1: i64, y1: i64) -> i64 {
    let mut dx = x1 - x0;
    if dx < 0 { dx = 0 - dx; }
    let mut dy = y1 - y0;
    if dy < 0 { dy = 0 - dy; }
    let sx = if x0 < x1 { 1 } else { 0 - 1 };
    let sy = if y0 < y1 { 1 } else { 0 - 1 };
    let mut err = dx - dy;
    let mut x = x0;
    let mut y = y0;
    let mut steps = 0;
    while x != x1 {
        steps = steps + 1;
        let e2 = 2 * err;
        if e2 > 0 - dy {
            err = err - dy;
            x = x + sx;
        }
        if e2 < dx {
            err = err + dx;
            y = y + sy;
        }
    }
    steps
}
