fn shoelace_triangle(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let area2 = x0 * (y1 - y2) + x1 * (y2 - y0) + x2 * (y0 - y1);
    if area2 < 0 { 0 - area2 } else { area2 }
}
fn main() {
    let a = shoelace_triangle(0, 0, 4, 0, 0, 3);
    println!("{}", a);
    let b = shoelace_triangle(0, 0, 10, 0, 5, 8);
    println!("{}", b);
}

fn cross_product(ox: i64, oy: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    (ax - ox) * (by - oy) - (ay - oy) * (bx - ox)
}
fn point_in_triangle(px: i64, py: i64, x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let d1 = cross_product(px, py, x0, y0, x1, y1);
    let d2 = cross_product(px, py, x1, y1, x2, y2);
    let d3 = cross_product(px, py, x2, y2, x0, y0);
    let has_neg = d1 < 0 || d2 < 0 || d3 < 0;
    let has_pos = d1 > 0 || d2 > 0 || d3 > 0;
    if has_neg && has_pos { 0 } else { 1 }
}
fn main() {
    println!("{}", point_in_triangle(1, 1, 0, 0, 10, 0, 0, 10));
    println!("{}", point_in_triangle(20, 20, 0, 0, 10, 0, 0, 10));
}

fn implies(a: i64, b: i64) -> i64 {
    if a == 0 { 1 } else { b }
}
fn two_sat_check(a: i64, b: i64, c: i64) -> i64 {
    let c1 = implies(a, b);
    let c2 = implies(b, c);
    let c3 = implies(c, a);
    if c1 == 1 && c2 == 1 && c3 == 1 { 1 } else { 0 }
}
fn main() {
    let mut sat = 0;
    for a in 0..2 {
        for b in 0..2 {
            for c in 0..2 {
                sat = sat + two_sat_check(a, b, c);
            }
        }
    }
    println!("{}", sat);
}

fn arc_reduce(d1_lo: i64, d1_hi: i64, d2_lo: i64, d2_hi: i64) -> i64 {
    let mut new_hi = d1_hi;
    if new_hi >= d2_hi {
        new_hi = d2_hi - 1;
    }
    let mut new_lo = d1_lo;
    if new_lo <= d2_lo {
        new_lo = d2_lo + 1;
    }
    if new_lo > new_hi { 0 } else { new_hi - new_lo + 1 }
}
