fn diff_power(coeff: i64, exp: i64) -> i64 {
    coeff * exp
}
fn diff_new_exp(exp: i64) -> i64 {
    if exp > 0 { exp - 1 } else { 0 }
}
fn eval_poly_deriv(x: i64, c3: i64, c2: i64, c1: i64) -> i64 {
    let d3_c = diff_power(c3, 3);
    let d3_e = diff_new_exp(3);
    let d2_c = diff_power(c2, 2);
    let d2_e = diff_new_exp(2);
    let d1_c = diff_power(c1, 1);
    let mut result = 0;
    let mut xp = 1;
    result = result + d1_c * xp;
    let mut i = 0;
    while i < d2_e {
        xp = xp * x;
        i = i + 1;
    }
    result = result + d2_c * xp;
    xp = 1;
    i = 0;
    while i < d3_e {
        xp = xp * x;
        i = i + 1;
    }
    result = result + d3_c * xp;
    result
}
fn main() {
    println!("{}", eval_poly_deriv(2, 1, 1, 1));
    println!("{}", eval_poly_deriv(1, 3, 2, 1));
}

fn gcd(a: i64, b: i64) -> i64 {
    let mut x = a;
    let mut y = b;
    if x < 0 { x = 0 - x; }
    if y < 0 { y = 0 - y; }
    while y != 0 {
        let t = y;
        y = x % y;
        x = t;
    }
    x
}
fn content(a: i64, b: i64, c: i64) -> i64 {
    let g1 = gcd(a, b);
    gcd(g1, c)
}
