}

fn compute_prefix(p0: i64, p1: i64, p2: i64, p3: i64, p4: i64) -> i64 {
    let pat = [p0, p1, p2, p3, p4];
    let mut fail = [0, 0, 0, 0, 0];
    let mut k = 0;
    let mut i = 1;
    while i < 5 {
        while k > 0 && pat[k] != pat[i] {
            k = fail[k - 1] as usize;
        }
        if pat[k] == pat[i] {
            k = k + 1;
        }
        fail[i] = k as i64;
        i = i + 1;
    }
    fail[0] + fail[1] + fail[2] + fail[3] + fail[4]
}
fn main() {
    println!("{}", compute_prefix(1, 2, 1, 2, 1));
    println!("{}", compute_prefix(1, 1, 1, 1, 1));
}

fn min3(a: i64, b: i64, c: i64) -> i64 {
    let m = if a < b { a } else { b };
    if m < c { m } else { c }
}
fn edit_dist(a0: i64, a1: i64, a2: i64, b0: i64, b1: i64, b2: i64) -> i64 {
    let mut prev = [0, 1, 2, 3];
    let mut curr = [0, 0, 0, 0];
    let a = [a0, a1, a2];
    let b = [b0, b1, b2];
    let mut i = 0;
    while i < 3 {
        curr[0] = i + 1;
        let mut j = 0;
        while j < 3 {
            let cost = if a[i] == b[j] { 0 } else { 1 };
            curr[j + 1] = min3(prev[j + 1] + 1, curr[j] + 1, prev[j] + cost);
            j = j + 1;
        }
        let mut k = 0;
        while k < 4 {
            prev[k] = curr[k];
            k = k + 1;
        }
        i = i + 1;
    }
    curr[3]
}
fn main() {
    println!("{}", edit_dist(1, 2, 3, 1, 2, 3));
    println!("{}", edit_dist(1, 2, 3, 4, 5, 6));
    println!("{}", edit_dist(1, 2, 3, 1, 3, 2));
}

fn lis_length(a: i64, b: i64, c: i64, d: i64, e: i64, f: i64) -> i64 {
    let arr = [a, b, c, d, e, f];
    let mut tails = [0, 0, 0, 0, 0, 0];
    let mut size = 0;
    let mut i = 0;
    while i < 6 {
        let mut lo = 0;
        let mut hi = size;
        while lo < hi {
            let mid = (lo + hi) / 2;
            if tails[mid] < arr[i] {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        tails[lo] = arr[i];
        if lo == size {
            size = size + 1;
        }
        i = i + 1;
    }
    size
}
fn main() {
    println!("{}", lis_length(3, 1, 4, 1, 5, 9));
    println!("{}", lis_length(6, 5, 4, 3, 2, 1));
    println!("{}", lis_length(1, 2, 3, 4, 5, 6));
}

fn triangle_area2(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let a = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    if a < 0 { 0 - a } else { a }
}
fn hull_area(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64, x3: i64, y3: i64) -> i64 {
    let a1 = triangle_area2(x0, y0, x1, y1, x2, y2);
    let a2 = triangle_area2(x0, y0, x2, y2, x3, y3);
    a1 + a2
}
