}

fn catalan(n: i64) -> i64 {
    if n <= 1 { return 1; }
    let mut result = 0;
    let mut i = 0;
    while i < n {
        result = result + catalan(i) * catalan(n - 1 - i);
        i = i + 1;
    }
    result
}
fn main() {
    let mut i = 0;
    while i < 8 {
        println!("{}", catalan(i));
        i = i + 1;
    }
}

fn rle_runs(a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64) -> i64 {
    let arr = [a, b, c, d, e, f, g, h];
    let mut runs = 1;
    let mut i = 1;
    while i < 8 {
        if arr[i] != arr[i - 1] {
            runs = runs + 1;
        }
        i = i + 1;
    }
