fn reduce_row(a: i64, b: i64, c: i64) -> i64 {
    let min_val = if a < b { if a < c { a } else { c } } else { if b < c { b } else { c } };
    (a - min_val) + (b - min_val) + (c - min_val)
}
fn reduce_matrix(r0a: i64, r0b: i64, r0c: i64, r1a: i64, r1b: i64, r1c: i64, r2a: i64, r2b: i64, r2c: i64) -> i64 {
    reduce_row(r0a, r0b, r0c) + reduce_row(r1a, r1b, r1c) + reduce_row(r2a, r2b, r2c)
}
