fn count_inversions(a: i64, b: i64, c: i64, d: i64, e: i64) -> i64 {
    let arr = [a, b, c, d, e];
    let mut inv = 0;
    let mut i = 0;
    while i < 5 {
        let mut j = i + 1;
        while j < 5 {
            if arr[i] > arr[j] {
                inv = inv + 1;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    inv
}
