fn spring_sim(x0: i64, v0: i64, k: i64, b: i64, steps: i64) -> i64 {
    let mut x = x0;
    let mut v = v0;
    let dt = 1;
    let mut i = 0;
    while i < steps {
        let a = 0 - k * x - b * v;
        v = v + a * dt;
        x = x + v * dt;
        i = i + 1;
    }
    x
}
fn main() {
    println!("{}", spring_sim(100, 0, 1, 1, 10));
    println!("{}", spring_sim(50, 10, 2, 1, 5));
}

fn projectile_range(vx: i64, vy: i64, drag: i64) -> i64 {
    let mut x = 0;
    let mut y = 0;
    let mut dx = vx;
    let mut dy = vy;
    let g = 10;
    while y >= 0 {
        x = x + dx;
        y = y + dy;
        dy = dy - g;
        dx = dx - dx * drag / 100;
    }
    x
}
fn main() {
