fn energy_pair(x1: i64, y1: i64, m1: i64, x2: i64, y2: i64, m2: i64) -> i64 {
    let dx = x2 - x1;
    let dy = y2 - y1;
    let r2 = dx * dx + dy * dy;
    if r2 == 0 { return 0; }
    0 - m1 * m2 * 100 / r2
}
fn total_energy(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let e01 = energy_pair(x0, y0, 1, x1, y1, 1);
    let e02 = energy_pair(x0, y0, 1, x2, y2, 1);
    let e12 = energy_pair(x1, y1, 1, x2, y2, 1);
    e01 + e02 + e12
}
fn main() {
    println!("{}", total_energy(0, 0, 10, 0, 5, 8));
    println!("{}", total_energy(0, 0, 3, 4, 6, 8));
}

fn wave_amp(freq1: i64, freq2: i64, t: i64) -> i64 {
    let phase1 = freq1 * t % 360;
    let phase2 = freq2 * t % 360;
    let y1 = if phase1 < 90 { phase1 } else if phase1 < 270 { 180 - phase1 } else { phase1 - 360 };
    let y2 = if phase2 < 90 { phase2 } else if phase2 < 270 { 180 - phase2 } else { phase2 - 360 };
    y1 + y2
}
fn main() {
    let mut i = 0;
    while i < 5 {
        println!("{}", wave_amp(30, 45, i));
        i = i + 1;
    }
}

fn pendulum(theta0: i64, omega0: i64, length: i64, steps: i64) -> i64 {
    let mut theta = theta0;
    let mut omega = omega0;
    let g = 10;
    let mut i = 0;
    while i < steps {
        let alpha = 0 - g * theta / length;
        omega = omega + alpha;
        theta = theta + omega;
        i = i + 1;
    }
    theta
}
fn main() {
    println!("{}", pendulum(100, 0, 10, 20));
    println!("{}", pendulum(50, 5, 20, 10));
}

fn heat_step(a: i64, b: i64, c: i64, d: i64, e: i64) -> i64 {
    let k = 1;
    let nb = (a + c) / 2;
    let nc = (b + d) / 2;
    let nd = (c + e) / 2;
    nb + nc + nd
}
fn heat_sim(steps: i64) -> i64 {
    let mut a = 0;
    let mut b = 0;
    let mut c = 100;
    let mut d = 0;
    let mut e = 0;
    let mut i = 0;
    while i < steps {
        let na = (0 + b) / 2;
        let nb = (a + c) / 2;
        let nc = (b + d) / 2;
        let nd = (c + e) / 2;
        let ne = (d + 0) / 2;
        a = na;
        b = nb;
        c = nc;
        d = nd;
        e = ne;
        i = i + 1;
    }
    a + b + c + d + e
}
