fn fir_filter(x0: i64, x1: i64, x2: i64, x3: i64, h0: i64, h1: i64, h2: i64) -> i64 {
    let y0 = x0 * h0;
    let y1 = x1 * h0 + x0 * h1;
    let y2 = x2 * h0 + x1 * h1 + x0 * h2;
    let y3 = x3 * h0 + x2 * h1 + x1 * h2;
    y0 + y1 + y2 + y3
}
fn main() {
