fn adsr(t: i64, attack: i64, decay: i64, sustain: i64, release: i64, total: i64) -> i64 {
    if t < attack {
        100 * t / attack
    } else if t < attack + decay {
        100 - (100 - sustain) * (t - attack) / decay
    } else if t < total - release {
        sustain
    } else if t < total {
        sustain * (total - t) / release
    } else {
        0
    }
}
fn main() {
    let mut t = 0;
    while t <= 100 {
        println!("{}", adsr(t, 10, 20, 60, 30, 100));
        t = t + 10;
    }
}

