fn reservoir_sample(n: i64, k: i64) -> i64 {
    let mut reservoir = [0, 0, 0];
    let mut i = 0;
    while i < k && i < 3 {
        reservoir[i] = i + 1;
        i = i + 1;
    }
    let mut seed = 42;
    while i < n {
        seed = lcg_next(seed);
        let j = seed % (i + 1);
        if j < k && j < 3 {
            reservoir[j] = i + 1;
        }
        i = i + 1;
    }
    reservoir[0] + reservoir[1] + reservoir[2]
}
