    while bit <= 256 {
        let xb = if (x / bit) % 2 == 1 { 1 } else { 0 };
        let nb = if (neg / bit) % 2 == 1 { 1 } else { 0 };
        if xb == 1 && nb == 1 {
            r = bit;
        }
        bit = bit * 2;
    }
    if r == 0 { 1 } else { r }
}
