fn unify(t1: i64, t2: i64) -> i64 {
    if t1 == t2 { return t1; }
    if t1 == 0 { return t2; }
    if t2 == 0 { return t1; }
    if t1 < 100 && t2 < 100 { return 0 - 1; }
    if t1 >= 100 {
        return unify(t1 - 100, t2);
    }
    if t2 >= 100 {
        return unify(t1, t2 - 100);
    }
    0 - 1
}
