fn lru_sim(c0: i64, c1: i64, c2: i64, c3: i64, c4: i64, cap: i64) -> i64 {
    let accesses = [c0, c1, c2, c3, c4];
    let mut cache = [0 - 1, 0 - 1, 0 - 1];
    let mut hits = 0;
    let mut size = 0;
    let mut i = 0;
    while i < 5 {
        let key = accesses[i];
        let mut found = 0;
        let mut j = 0;
        while j < size {
            if cache[j] == key {
                found = 1;
                hits = hits + 1;
                let saved = cache[j];
                let mut k = j;
                while k < size - 1 {
                    cache[k] = cache[k + 1];
                    k = k + 1;
                }
                cache[size - 1] = saved;
            }
            j = j + 1;
        }
        if found == 0 {
            if size < cap && size < 3 {
                cache[size] = key;
                size = size + 1;
            } else {
                let mut k = 0;
                while k < size - 1 {
                    cache[k] = cache[k + 1];
                    k = k + 1;
                }
                cache[size - 1] = key;
            }
        }
        i = i + 1;
    }
    hits
}
