    println!("{}", lru_sim(1, 2, 3, 1, 2, 3));
    println!("{}", lru_sim(1, 1, 1, 1, 1, 2));
    println!("{}", lru_sim(1, 2, 3, 4, 5, 2));
}

fn ring_sim(ops: i64) -> i64 {
    let mut buf = [0, 0, 0, 0];
    let cap = 4;
    let mut head = 0;
    let mut tail = 0;
    let mut count = 0;
    let mut sum = 0;
    let mut i = 1;
    while i <= ops {
        if count < cap {
            buf[tail] = i * 10;
            tail = (tail + 1) % cap;
            count = count + 1;
        }
        if i % 3 == 0 && count > 0 {
            sum = sum + buf[head];
            head = (head + 1) % cap;
            count = count - 1;
        }
        i = i + 1;
    }
    sum
}
