}

fn deque_ops(n: i64) -> i64 {
    let mut arr = [0, 0, 0, 0, 0, 0, 0, 0];
    let mut front = 4;
    let mut back = 3;
    let mut size = 0;
    let mut i = 1;
    while i <= n {
        if i % 2 == 1 {
            front = front - 1;
            arr[front] = i;
            size = size + 1;
        } else {
            back = back + 1;
            arr[back] = i;
            size = size + 1;
        }
        i = i + 1;
    }
    let mut sum = 0;
    let mut j = front;
    while j <= back {
        sum = sum + arr[j];
        j = j + 1;
    }
    sum
}
