fn crc_byte(data: i64, poly: i64) -> i64 {
    let mut crc = data;
    let mut i = 0;
    while i < 8 {
        if crc % 2 == 1 {
            crc = crc / 2;
            let xor_val = poly;
            crc = crc + xor_val - 2 * (crc / (xor_val + 1) * (xor_val + 1) / 2);
        } else {
            crc = crc / 2;
        }
        i = i + 1;
    }
    crc % 256
}
