    let p2 = (d1 + d3 + d4) % 2;
    let p3 = (d2 + d3 + d4) % 2;
    p1 * 64 + d1 * 32 + p2 * 16 + d2 * 8 + d3 * 4 + p3 * 2 + d4
}
fn hamming_syndrome(encoded: i64) -> i64 {
    let b6 = (encoded / 64) % 2;
    let b5 = (encoded / 32) % 2;
    let b4 = (encoded / 16) % 2;
    let b3 = (encoded / 8) % 2;
    let b2 = (encoded / 4) % 2;
    let b1 = (encoded / 2) % 2;
    let b0 = encoded % 2;
    let s0 = (b6 + b5 + b3 + b0) % 2;
    let s1 = (b4 + b5 + b2 + b0) % 2;
    let s2 = (b1 + b3 + b2 + b0) % 2;
    s0 * 4 + s1 * 2 + s2
}
