fn bisection(lo: i64, hi: i64, iters: i64) -> i64 {
    let mut a = lo;
    let mut b = hi;
    let mut i = 0;
    while i < iters {
        let mid = (a + b) / 2;
        let fmid = f(mid);
        if fmid == 0 { return mid; }
        let fa = f(a);
        if (fa > 0 && fmid > 0) || (fa < 0 && fmid < 0) {
            a = mid;
        } else {
            b = mid;
        }
        i = i + 1;
    }
    (a + b) / 2
}
