    x * x + 2 * x + 1
}
fn simpson(a: i64, b: i64, n: i64) -> i64 {
    let h = (b - a) / n;
    let mut sum = f_poly(a) + f_poly(b);
    let mut i = 1;
    while i < n {
        let x = a + i * h;
        if i % 2 == 0 {
            sum = sum + 2 * f_poly(x);
        } else {
            sum = sum + 4 * f_poly(x);
        }
        i = i + 1;
    }
    sum * h / 3
}
fn main() {
    println!("{}", simpson(0, 10, 10));
    println!("{}", simpson(0, 4, 4));
}

