fn objective(x: i64) -> i64 {
    (x - 7) * (x - 7) + 3
}
fn golden_search(a: i64, b: i64, iters: i64) -> i64 {
    let mut lo = a;
    let mut hi = b;
    let mut i = 0;
    while i < iters {
        let d = (hi - lo) * 382 / 1000;
        let x1 = lo + d;
        let x2 = hi - d;
        if objective(x1) < objective(x2) {
            hi = x2;
        } else {
            lo = x1;
        }
        i = i + 1;
    }
    (lo + hi) / 2
}
