fn f_cubic(x: i64) -> i64 {
    x * x * x - 27
}
fn secant(x0: i64, x1: i64, iters: i64) -> i64 {
    let mut a = x0;
    let mut b = x1;
    let mut i = 0;
    while i < iters {
        let fa = f_cubic(a);
        let fb = f_cubic(b);
        let denom = fb - fa;
        if denom == 0 { return b; }
        let c = b - fb * (b - a) / denom;
        a = b;
        b = c;
        i = i + 1;
    }
    b
}
fn main() {
    println!("{}", secant(1, 5, 10));
    println!("{}", secant(2, 4, 8));
}

fn f_square(x: i64) -> i64 {
    x * x
}
fn trapezoid(a: i64, b: i64, n: i64) -> i64 {
    let h = (b - a) / n;
    let mut sum = (f_square(a) + f_square(b)) / 2;
    let mut i = 1;
    while i < n {
        sum = sum + f_square(a + i * h);
        i = i + 1;
    }
    sum * h
}
fn romberg_refine(t1: i64, t2: i64) -> i64 {
    (4 * t2 - t1) / 3
}
