fn segments_intersect(ax: i64, ay: i64, bx: i64, by: i64, cx: i64, cy: i64, dx: i64, dy: i64) -> i64 {
    let d1 = cross2d(bx - ax, by - ay, cx - ax, cy - ay);
    let d2 = cross2d(bx - ax, by - ay, dx - ax, dy - ay);
    let d3 = cross2d(dx - cx, dy - cy, ax - cx, ay - cy);
    let d4 = cross2d(dx - cx, dy - cy, bx - cx, by - cy);
    if ((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0)) {
        1
    } else {
        0
    }
}
