fn side_of_line(px: i64, py: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    let cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax);
    if cross > 0 { 1 } else if cross < 0 { 0 - 1 } else { 0 }
}
fn dist_to_line(px: i64, py: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    let d = (bx - ax) * (py - ay) - (by - ay) * (px - ax);
    if d < 0 { 0 - d } else { d }
}
