fn huffman_lengths(f0: i64, f1: i64, f2: i64, f3: i64) -> i64 {
    let total = f0 + f1 + f2 + f3;
    let mut freqs = [f0, f1, f2, f3];
    let mut lengths = [0, 0, 0, 0];
    let mut steps = 0;
    while steps < 3 {
        let mut min1 = 0;
        let mut min2 = 1;
        if freqs[min2] < freqs[min1] {
            let t = min1;
            min1 = min2;
            min2 = t;
        }
        let mut i = 2;
        while i < 4 {
            if freqs[i] < freqs[min1] {
                min2 = min1;
                min1 = i;
            } else if freqs[i] < freqs[min2] {
                min2 = i;
            }
            i = i + 1;
        }
        lengths[min1] = lengths[min1] + 1;
        lengths[min2] = lengths[min2] + 1;
        freqs[min1] = freqs[min1] + freqs[min2];
        freqs[min2] = total + 1;
        steps = steps + 1;
    }
    lengths[0] + lengths[1] + lengths[2] + lengths[3]
}
fn main() {
    println!("{}", huffman_lengths(10, 10, 10, 10));
    println!("{}", huffman_lengths(50, 25, 15, 10));
}

fn log2_approx(n: i64) -> i64 {
    if n <= 1 { return 0; }
    let mut k = 0;
    let mut v = n;
    while v > 1 {
        v = v / 2;
        k = k + 1;
    }
    k
}
fn entropy_bits(f0: i64, f1: i64, f2: i64, f3: i64) -> i64 {
    let total = f0 + f1 + f2 + f3;
    let lt = log2_approx(total);
    let mut bits = total * lt;
    if f0 > 0 { bits = bits - f0 * log2_approx(f0); }
    if f1 > 0 { bits = bits - f1 * log2_approx(f1); }
    if f2 > 0 { bits = bits - f2 * log2_approx(f2); }
    if f3 > 0 { bits = bits - f3 * log2_approx(f3); }
    bits
}
fn main() {
    println!("{}", entropy_bits(25, 25, 25, 25));
    println!("{}", entropy_bits(100, 0, 0, 0));
    println!("{}", entropy_bits(50, 25, 15, 10));
}

