fn gf_add(a: i64, b: i64) -> i64 {
    let mut result = 0;
    let mut bit = 1;
    let mut i = 0;
    while i < 8 {
        let ab = (a / bit) % 2;
        let bb = (b / bit) % 2;
        if ab != bb {
            result = result + bit;
        }
        bit = bit * 2;
        i = i + 1;
    }
    result
}
fn syndrome(d0: i64, d1: i64, d2: i64, p: i64) -> i64 {
    let s = gf_add(gf_add(d0, d1), gf_add(d2, p));
    s
}
