fn nim_value(a: i64, b: i64, c: i64) -> i64 {
    let mut xor_val = 0;
    let mut bit = 1;
    let mut i = 0;
    while i < 10 {
        let ab = (a / bit) % 2;
        let bb = (b / bit) % 2;
        let cb = (c / bit) % 2;
        let xb = if (ab + bb + cb) % 2 == 1 { 1 } else { 0 };
        xor_val = xor_val + xb * bit;
        bit = bit * 2;
        i = i + 1;
    }
    xor_val
}
fn is_losing(a: i64, b: i64, c: i64) -> i64 {
    if nim_value(a, b, c) == 0 { 1 } else { 0 }
}
