    if row0_min >= row1_min { 0 } else { 1 }
}
fn minimax_value(a00: i64, a01: i64, a10: i64, a11: i64) -> i64 {
    let row0_min = if a00 < a01 { a00 } else { a01 };
    let row1_min = if a10 < a11 { a10 } else { a11 };
    let maximin = if row0_min > row1_min { row0_min } else { row1_min };
    let col0_max = if a00 > a10 { a00 } else { a10 };
    let col1_max = if a01 > a11 { a01 } else { a11 };
    let minimax = if col0_max < col1_max { col0_max } else { col1_max };
    maximin * 100 + minimax
}
