    let dy = y2 - y1;
    dx * dx + dy * dy
}
fn tsp_nn(n: i64) -> i64 {
    let xs = [0, 3, 6, 1, 5];
    let ys = [0, 4, 1, 7, 5];
    let mut visited = [1, 0, 0, 0, 0];
    let mut cur = 0;
    let mut total = 0;
    let mut step = 1;
    while step < n && step < 5 {
        let mut best = 0 - 1;
        let mut best_d = 999999;
        let mut j = 0;
        while j < n && j < 5 {
            if visited[j] == 0 {
                let d = dist(xs[cur], ys[cur], xs[j], ys[j]);
                if d < best_d {
                    best_d = d;
                    best = j;
                }
            }
            j = j + 1;
        }
        visited[best] = 1;
        total = total + best_d;
        cur = best;
        step = step + 1;
    }
    total = total + dist(xs[cur], ys[cur], xs[0], ys[0]);
    total
}
fn main() {
    println!("{}", tsp_nn(4));
    println!("{}", tsp_nn(5));
}

fn schedule_spt(p0: i64, p1: i64, p2: i64, p3: i64) -> i64 {
    let mut jobs = [p0, p1, p2, p3];
    let mut i = 0;
    while i < 4 {
        let mut j = i + 1;
        while j < 4 {
            if jobs[j] < jobs[i] {
                let t = jobs[i];
                jobs[i] = jobs[j];
                jobs[j] = t;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    let mut time = 0;
    let mut total = 0;
    i = 0;
    while i < 4 {
        time = time + jobs[i];
        total = total + time;
        i = i + 1;
    }
    total
}
fn main() {
    println!("{}", schedule_spt(4, 2, 8, 1));
    println!("{}", schedule_spt(3, 3, 3, 3));
    println!("{}", schedule_spt(10, 1, 5, 2));
}

