    let edges = [[e00, e01, e02], [e10, e11, e12], [e20, e21, e22]];
    let mut matched_r = [0, 0, 0];
    let mut count = 0;
    let mut i = 0;
    while i < 3 {
        let mut j = 0;
        while j < 3 {
            if edges[i][j] == 1 && matched_r[j] == 0 {
                matched_r[j] = 1;
                count = count + 1;
                j = 3;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    count
}
