fn max_intervals(s0: i64, e0: i64, s1: i64, e1: i64, s2: i64, e2: i64, s3: i64, e3: i64) -> i64 {
    let starts = [s0, s1, s2, s3];
    let ends = [e0, e1, e2, e3];
    let mut order = [0, 1, 2, 3];
    let mut i = 0;
    while i < 4 {
        let mut j = i + 1;
        while j < 4 {
            if ends[order[j]] < ends[order[i]] {
                let t = order[i];
                order[i] = order[j];
                order[j] = t;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    let mut count = 1;
    let mut last_end = ends[order[0]];
    i = 1;
    while i < 4 {
        if starts[order[i]] >= last_end {
            count = count + 1;
            last_end = ends[order[i]];
        }
        i = i + 1;
    }
    count
}
fn main() {
    println!("{}", max_intervals(1, 3, 2, 5, 4, 7, 6, 9));
