fn weighted_activity(w0: i64, w1: i64, w2: i64, w3: i64, e0: i64, e1: i64, e2: i64, e3: i64) -> i64 {
    let weights = [w0, w1, w2, w3];
    let ends = [e0, e1, e2, e3];
    let mut order = [0, 1, 2, 3];
    let mut i = 0;
    while i < 4 {
        let mut j = i + 1;
        while j < 4 {
            if ends[order[j]] < ends[order[i]] {
                let t = order[i];
                order[i] = order[j];
                order[j] = t;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    let mut best = weights[order[0]];
    i = 1;
    while i < 4 {
        let w = weights[order[i]];
        if w > best { best = w; }
        i = i + 1;
    }
    best
}
