fn vickrey_price(b0: i64, b1: i64, b2: i64, b3: i64) -> i64 {
    let bids = [b0, b1, b2, b3];
    let mut max_bid = 0;
    let mut second = 0;
    let mut winner = 0;
    let mut i = 0;
    while i < 4 {
        if bids[i] > max_bid {
            second = max_bid;
            max_bid = bids[i];
            winner = i;
        } else if bids[i] > second {
            second = bids[i];
        }
        i = i + 1;
    }
    winner * 100 + second
}
