fn pagerank_step(r0: i64, r1: i64, r2: i64, adj: i64) -> i64 {
    let d = 85;
    let n = 3;
    let base = (100 - d) * 100 / n;
    let incoming = match adj {
        0 => r1 * d / (2 * 100) + r2 * d / (1 * 100),
        1 => r0 * d / (1 * 100),
        2 => r0 * d / (1 * 100) + r1 * d / (2 * 100),
        _ => 0,
    };
    base + incoming
}
