        4 => 0,
        3 => 1,
        2 => 1,
        1 => 1,
        0 => 0,
        _ => 0,
    }
}
fn evolve(cells: i64, steps: i64) -> i64 {
    let mut c = [0, 0, 0, 0, 0, 0, 0, 1];
    let mut i = 0;
    while i < steps {
        let mut next = [0, 0, 0, 0, 0, 0, 0, 0];
        let mut j = 1;
        while j < 7 {
            next[j] = rule110(c[j - 1], c[j], c[j + 1]);
            j = j + 1;
        }
        let mut k = 0;
        while k < 8 {
            c[k] = next[k];
            k = k + 1;
        }
        i = i + 1;
    }
    let mut sum = 0;
    let mut j = 0;
    while j < 8 {
        sum = sum + c[j];
        j = j + 1;
    }
    sum
}
