fn knapsack_greedy(w0: i64, v0: i64, w1: i64, v1: i64, w2: i64, v2: i64, cap: i64) -> i64 {
    let weights = [w0, w1, w2];
    let values = [v0, v1, v2];
    let mut ratios = [v0 * 100 / w0, v1 * 100 / w1, v2 * 100 / w2];
    let mut order = [0, 1, 2];
    if ratios[order[1]] > ratios[order[0]] {
        let t = order[0]; order[0] = order[1]; order[1] = t;
    }
    if ratios[order[2]] > ratios[order[0]] {
        let t = order[0]; order[0] = order[2]; order[2] = t;
    }
    if ratios[order[2]] > ratios[order[1]] {
        let t = order[1]; order[1] = order[2]; order[2] = t;
    }
    let mut remaining = cap;
    let mut total = 0;
    let mut i = 0;
    while i < 3 {
        let idx = order[i];
        if weights[idx] <= remaining {
            total = total + values[idx];
            remaining = remaining - weights[idx];
        }
        i = i + 1;
    }
    total
}
fn main() {
    println!("{}", knapsack_greedy(2, 3, 3, 4, 4, 5, 6));
    println!("{}", knapsack_greedy(5, 10, 3, 7, 2, 4, 7));
}

