fn max_rev(length: i64) -> i64 {
    if length <= 0 { return 0; }
    let price = match length {
        1 => 1,
        2 => 5,
        3 => 8,
        4 => 9,
        5 => 10,
        6 => 17,
        _ => length * 2,
    };
    let mut best = price;
    let mut i = 1;
    while i < length {
        let candidate = max_rev(i) + max_rev(length - i);
        if candidate > best {
            best = candidate;
        }
        i = i + 1;
    }
    best
}
