    let mut counts = [0, 0, 0, 0, 0];
    let mut i = 0;
    while i < 5 {
        let v = votes[i];
        if v >= 0 && v < 5 {
            counts[v] = counts[v] + 1;
        }
        i = i + 1;
    }
    let mut winner = 0;
    let mut max_c = counts[0];
    i = 1;
    while i < 5 {
        if counts[i] > max_c {
            max_c = counts[i];
            winner = i;
        }
        i = i + 1;
    }
    winner * 10 + max_c
}
