fn dominates(a: i64, b: i64) -> i64 {
    if a == 0 { return 1; }
    if a == b { return 1; }
    let parent = match b {
        1 => 0,
        2 => 0,
        3 => 1,
        4 => 1,
        5 => 2,
        _ => 0 - 1,
    };
    if parent == a { return 1; }
    if parent < 0 { return 0; }
    dominates(a, parent)
}
fn dom_frontier_size(node: i64) -> i64 {
    let mut count = 0;
    let mut i = 0;
    while i < 6 {
        if dominates(node, i) == 0 {
            let pred = match i {
                2 => 1,
                3 => 2,
                _ => 0 - 1,
            };
            if pred >= 0 && dominates(node, pred) == 1 {
                count = count + 1;
            }
        }
        i = i + 1;
    }
    count
}
