    let l0 = schedule_latency(o0);
    let l1 = schedule_latency(o1);
    let l2 = schedule_latency(o2);
    let path1 = l0 + l2;
    let path2 = l1 + l2;
    if path1 > path2 { path1 } else { path2 }
}
