fn pid_step(setpoint: i64, actual: i64, integral: i64, prev_error: i64, kp: i64, ki: i64, kd: i64) -> i64 {
    let error = setpoint - actual;
    let new_integral = integral + error;
    let derivative = error - prev_error;
    let output = kp * error / 10 + ki * new_integral / 100 + kd * derivative / 10;
    output
}
fn pid_sim(setpoint: i64, steps: i64) -> i64 {
    let mut actual = 0;
    let mut integral = 0;
    let mut prev_error = setpoint;
    let kp = 5;
    let ki = 1;
    let kd = 2;
    let mut i = 0;
    while i < steps {
        let output = pid_step(setpoint, actual, integral, prev_error, kp, ki, kd);
        prev_error = setpoint - actual;
        integral = integral + prev_error;
        actual = actual + output / 10;
        i = i + 1;
    }
    actual
}
