    let r01 = a * f + b * h;
    let r10 = c * e + d * g;
    let r11 = c * f + d * h;
    r00 * 1000 + r01 * 100 + r10 * 10 + r11
}
fn mat_pow(a: i64, b: i64, c: i64, d: i64, n: i64) -> i64 {
    if n == 1 { return a * 1000 + b * 100 + c * 10 + d; }
    let mut ra = a;
    let mut rb = b;
    let mut rc = c;
    let mut rd = d;
    let mut i = 1;
    while i < n {
        let na = ra * a + rb * c;
        let nb = ra * b + rb * d;
        let nc = rc * a + rd * c;
        let nd = rc * b + rd * d;
        ra = na;
        rb = nb;
        rc = nc;
        rd = nd;
        i = i + 1;
    }
    ra * 1000 + rb * 100 + rc * 10 + rd
}
