fn bezier_quad(p0: i64, p1: i64, p2: i64, t_num: i64, t_den: i64) -> i64 {
    let t = t_num;
    let ot = t_den - t;
    let result = ot * ot * p0 + 2 * ot * t * p1 + t * t * p2;
    result / (t_den * t_den)
}
fn bezier_length_approx(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
