    let dx1 = mx - x0;
    let dy1 = my - y0;
    let dx2 = x2 - mx;
    let dy2 = y2 - my;
    let l1_sq = dx1 * dx1 + dy1 * dy1;
    let l2_sq = dx2 * dx2 + dy2 * dy2;
    l1_sq + l2_sq
}
