fn mobius(n: i64) -> i64 {
    if n == 1 { return 1; }
    let mut factors = 0;
    let mut d = 2;
    let mut rem = n;
    while d * d <= rem {
        if rem % d == 0 {
            factors = factors + 1;
            rem = rem / d;
            if rem % d == 0 { return 0; }
        }
        d = d + 1;
    }
    if rem > 1 { factors = factors + 1; }
    if factors % 2 == 0 { 1 } else { 0 - 1 }
}
