}

fn jacobi(a: i64, n: i64) -> i64 {
    if n <= 0 || n % 2 == 0 { return 0; }
    let mut aa = a % n;
    if aa < 0 { aa = aa + n; }
    let mut nn = n;
    let mut result = 1;
    while aa != 0 {
        while aa % 2 == 0 {
            aa = aa / 2;
            let r = nn % 8;
            if r == 3 || r == 5 {
                result = 0 - result;
            }
        }
        let t = aa;
        aa = nn;
        nn = t;
        if aa % 4 == 3 && nn % 4 == 3 {
            result = 0 - result;
        }
        aa = aa % nn;
    }
    if nn == 1 { result } else { 0 }
}
fn main() {
    println!("{}", jacobi(2, 7));
    println!("{}", jacobi(5, 11));
    println!("{}", jacobi(3, 15));
}

fn mod_pow(base: i64, exp: i64, modulus: i64) -> i64 {
    let mut result = 1;
    let mut b = base % modulus;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = result * b % modulus;
        }
        e = e / 2;
        b = b * b % modulus;
    }
    result
}
