}

fn tcp_window(win_size: i64, sent: i64, acked: i64) -> i64 {
    let in_flight = sent - acked;
    let available = win_size - in_flight;
    if available > 0 { available } else { 0 }
}
fn tcp_cwnd_update(cwnd: i64, ssthresh: i64, acked: i64) -> i64 {
    if cwnd < ssthresh {
        cwnd + acked
    } else {
        cwnd + acked * acked / cwnd
    }
}
fn main() {
