    println!("{}", tcp_cwnd_update(10, 32, 1));
    println!("{}", tcp_cwnd_update(40, 32, 1));
}

fn ones_complement_add(a: i64, b: i64) -> i64 {
    let sum = a + b;
    let carry = sum / 65536;
    (sum % 65536) + carry
}
fn ip_checksum(w0: i64, w1: i64, w2: i64, w3: i64, w4: i64) -> i64 {
    let mut sum = 0;
    sum = ones_complement_add(sum, w0);
    sum = ones_complement_add(sum, w1);
    sum = ones_complement_add(sum, w2);
    sum = ones_complement_add(sum, w3);
    sum = ones_complement_add(sum, w4);
    65535 - sum
}
