fn djb2_hash(c0: i64, c1: i64, c2: i64, c3: i64, c4: i64) -> i64 {
    let mut hash = 5381;
    let chars = [c0, c1, c2, c3, c4];
    let mut i = 0;
    while i < 5 {
        if chars[i] == 0 { i = 5; }
        else {
            hash = hash * 33 + chars[i];
            hash = hash % 1000000;
        }
        i = i + 1;
    }
    hash
}
fn main() {
