fn btree_search(key: i64, k0: i64, k1: i64, k2: i64) -> i64 {
    if key < k0 { return 0; }
    if key == k0 { return 1; }
    if key < k1 { return 2; }
    if key == k1 { return 3; }
    if key < k2 { return 4; }
    if key == k2 { return 5; }
    6
}
fn btree_height(n: i64, order: i64) -> i64 {
    let mut height = 1;
    let mut capacity = order - 1;
    while capacity < n {
        height = height + 1;
        capacity = capacity * order;
    }
    height
}
