fn hash_join_cost(r_size: i64, s_size: i64, mem: i64) -> i64 {
    let partitions = (r_size + mem - 1) / mem;
    let read_cost = r_size + s_size;
    let write_cost = r_size;
    let probe_cost = s_size;
    read_cost + write_cost + probe_cost
}
fn nested_loop_cost(r_size: i64, s_size: i64) -> i64 {
    r_size * s_size
}
fn best_join(r: i64, s: i64, mem: i64) -> i64 {
    let hj = hash_join_cost(r, s, mem);
    let nl = nested_loop_cost(r, s);
    if hj < nl { hj } else { nl }
}
