fn selectivity_range(min_val: i64, max_val: i64, lo: i64, hi: i64) -> i64 {
    if hi <= min_val || lo >= max_val { return 0; }
    let effective_lo = if lo > min_val { lo } else { min_val };
    let effective_hi = if hi < max_val { hi } else { max_val };
    (effective_hi - effective_lo) * 1000 / (max_val - min_val)
}
