}
fn train_step(x0: i64, x1: i64, target: i64, w0: i64, w1: i64, bias: i64) -> i64 {
    let pred = perceptron(x0, x1, w0, w1, bias);
    let error = target - pred;
    let new_w0 = w0 + error * x0;
    let new_w1 = w1 + error * x1;
    let new_bias = bias + error;
    new_w0 * 100 + new_w1 * 10 + new_bias
}
