    let ady = if dy < 0 { 0 - dy } else { dy };
    adx + ady
}
fn knn_1(qx: i64, qy: i64, x0: i64, y0: i64, l0: i64, x1: i64, y1: i64, l1: i64, x2: i64, y2: i64, l2: i64) -> i64 {
    let d0 = manhattan_dist(qx, qy, x0, y0);
    let d1 = manhattan_dist(qx, qy, x1, y1);
    let d2 = manhattan_dist(qx, qy, x2, y2);
    if d0 <= d1 && d0 <= d2 { l0 }
    else if d1 <= d0 && d1 <= d2 { l1 }
    else { l2 }
}
