fn variance(a: i64, b: i64, c: i64, d: i64, e: i64) -> i64 {
    let m = mean(a, b, c, d, e);
    let v = (a - m) * (a - m) + (b - m) * (b - m) + (c - m) * (c - m)
          + (d - m) * (d - m) + (e - m) * (e - m);
    v / 5
}
