fn linear_reg(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let n = 3;
    let sum_x = x0 + x1 + x2;
    let sum_y = y0 + y1 + y2;
    let sum_xy = x0 * y0 + x1 * y1 + x2 * y2;
    let sum_xx = x0 * x0 + x1 * x1 + x2 * x2;
    let denom = n * sum_xx - sum_x * sum_x;
    if denom == 0 { return 0; }
    let slope = (n * sum_xy - sum_x * sum_y) * 100 / denom;
    let intercept = (sum_y * sum_xx - sum_x * sum_xy) * 100 / denom;
    slope * 1000 + intercept
}
