    println!("{}", linear_reg(1, 2, 2, 4, 3, 6));
    println!("{}", linear_reg(1, 1, 2, 3, 3, 2));
}

fn correlation(x0: i64, y0: i64, x1: i64, y1: i64, x2: i64, y2: i64, x3: i64, y3: i64) -> i64 {
    let n = 4;
    let sx = x0 + x1 + x2 + x3;
    let sy = y0 + y1 + y2 + y3;
    let sxy = x0 * y0 + x1 * y1 + x2 * y2 + x3 * y3;
    let sxx = x0 * x0 + x1 * x1 + x2 * x2 + x3 * x3;
    let syy = y0 * y0 + y1 * y1 + y2 * y2 + y3 * y3;
    let num = n * sxy - sx * sy;
    let den_x = n * sxx - sx * sx;
    let den_y = n * syy - sy * sy;
    if den_x == 0 || den_y == 0 { return 0; }
    num * 1000 / (den_x + den_y)
}
fn main() {
