fn histogram(v0: i64, v1: i64, v2: i64, v3: i64, v4: i64, v5: i64, min_val: i64, bin_width: i64) -> i64 {
    let vals = [v0, v1, v2, v3, v4, v5];
    let mut bins = [0, 0, 0, 0, 0];
    let mut i = 0;
    while i < 6 {
        let b = bin_index(vals[i], min_val, bin_width);
        if b >= 0 && b < 5 {
            bins[b] = bins[b] + 1;
        }
        i = i + 1;
    }
    bins[0] * 10000 + bins[1] * 1000 + bins[2] * 100 + bins[3] * 10 + bins[4]
}
