fn normalize_batch(v0: i64, v1: i64, v2: i64, v3: i64) -> i64 {
    let mean = (v0 + v1 + v2 + v3) / 4;
    let var = ((v0 - mean) * (v0 - mean) + (v1 - mean) * (v1 - mean)
             + (v2 - mean) * (v2 - mean) + (v3 - mean) * (v3 - mean)) / 4;
    let mut std = 1;
    while std * std < var { std = std + 1; }
    z_score(v0, mean, std) + z_score(v1, mean, std) + z_score(v2, mean, std) + z_score(v3, mean, std)
}
