fn bell(n: i64) -> i64 {
    if n <= 1 { return 1; }
    let mut tri = [0, 0, 0, 0, 0, 0, 0, 0];
    tri[0] = 1;
    let mut i = 1;
    while i <= n && i < 8 {
        let mut row = [0, 0, 0, 0, 0, 0, 0, 0];
        row[0] = tri[i - 1];
        let mut j = 1;
        while j <= i {
            row[j] = row[j - 1] + tri[j - 1];
            j = j + 1;
        }
        let mut k = 0;
        while k <= i {
            tri[k] = row[k];
            k = k + 1;
        }
        i = i + 1;
    }
    tri[0]
}
