    println!("{}", bell(5));
}

fn ext_gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        return a * 10000 + 1 * 100 + 0;
    }
    let result = ext_gcd(b, a % b);
    let g = result / 10000;
    let x = (result / 100) % 100;
    let y = result % 100;
    let new_x = y;
    let new_y = x - (a / b) * y;
    g * 10000 + new_x * 100 + (if new_y < 0 { new_y + 100 } else { new_y })
}
fn mod_inverse(a: i64, m: i64) -> i64 {
    let result = ext_gcd(a, m);
    let x = (result / 100) % 100;
    (x % m + m) % m
}
