fn mod_pow(base: i64, exp: i64, modulus: i64) -> i64 {
    let mut result = 1;
    let mut b = base % modulus;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = result * b % modulus;
        }
        e = e / 2;
        b = b * b % modulus;
    }
    result
}
fn miller_witness(n: i64, a: i64) -> i64 {
    let mut d = n - 1;
    let mut r = 0;
    while d % 2 == 0 {
        d = d / 2;
        r = r + 1;
    }
    let mut x = mod_pow(a, d, n);
    if x == 1 || x == n - 1 { return 0; }
    let mut i = 0;
    while i < r - 1 {
        x = x * x % n;
        if x == n - 1 { return 0; }
        i = i + 1;
    }
    1
}
