fn gcd(a: i64, b: i64) -> i64 {
    let mut x = a;
    let mut y = b;
    if x < 0 { x = 0 - x; }
    if y < 0 { y = 0 - y; }
    while y != 0 {
        let t = y;
        y = x % y;
        x = t;
    }
    x
}
fn pollard_rho(n: i64, max_iter: i64) -> i64 {
    let mut x = 2;
    let mut y = 2;
    let mut d = 1;
    let c = 1;
    let mut i = 0;
    while d == 1 && i < max_iter {
        x = pollard_f(x, c, n);
        y = pollard_f(pollard_f(y, c, n), c, n);
        let diff = x - y;
        d = gcd(if diff < 0 { 0 - diff } else { diff }, n);
        i = i + 1;
    }
    if d == n { 0 - 1 } else { d }
}
fn main() {
    println!("{}", pollard_rho(91, 50));
    println!("{}", pollard_rho(77, 50));
}

fn mod_pow(base: i64, exp: i64, modulus: i64) -> i64 {
    let mut result = 1;
    let mut b = base % modulus;
    let mut e = exp;
    while e > 0 {
        if e % 2 == 1 {
            result = result * b % modulus;
        }
        e = e / 2;
        b = b * b % modulus;
    }
    result
}
fn discrete_log_brute(g: i64, h: i64, p: i64) -> i64 {
    let mut x = 0;
    let mut power = 1;
    while x < p {
        if power == h { return x; }
        power = power * g % p;
        x = x + 1;
    }
    0 - 1
}
