fn topo_order(e01: i64, e02: i64, e12: i64, e13: i64, e23: i64) -> i64 {
    let mut in_deg = [0, 0, 0, 0];
    if e01 == 1 { in_deg[1] = in_deg[1] + 1; }
    if e02 == 1 { in_deg[2] = in_deg[2] + 1; }
    if e12 == 1 { in_deg[2] = in_deg[2] + 1; }
    if e13 == 1 { in_deg[3] = in_deg[3] + 1; }
    if e23 == 1 { in_deg[3] = in_deg[3] + 1; }
    let mut result = 0;
    let mut processed = [0, 0, 0, 0];
    let mut step = 0;
    while step < 4 {
        let mut found = 0 - 1;
        let mut i = 0;
        while i < 4 {
            if processed[i] == 0 && in_deg[i] == 0 {
                found = i;
                i = 4;
            }
            i = i + 1;
        }
        if found < 0 { return 0 - 1; }
        result = result * 10 + found;
        processed[found] = 1;
        if found == 0 {
            if e01 == 1 { in_deg[1] = in_deg[1] - 1; }
            if e02 == 1 { in_deg[2] = in_deg[2] - 1; }
        }
        if found == 1 {
            if e12 == 1 { in_deg[2] = in_deg[2] - 1; }
            if e13 == 1 { in_deg[3] = in_deg[3] - 1; }
        }
        if found == 2 {
            if e23 == 1 { in_deg[3] = in_deg[3] - 1; }
        }
        step = step + 1;
    }
    result
}
