    let mut total = 0;
    let mut edges = 0;
    while edges < 3 {
        let mut best = 999;
        let mut best_to = 0;
        if in_mst[0] == 1 && in_mst[1] == 0 && w01 < best { best = w01; best_to = 1; }
        if in_mst[0] == 1 && in_mst[2] == 0 && w02 < best { best = w02; best_to = 2; }
        if in_mst[0] == 1 && in_mst[3] == 0 && w03 < best { best = w03; best_to = 3; }
        if in_mst[1] == 1 && in_mst[2] == 0 && w12 < best { best = w12; best_to = 2; }
        if in_mst[1] == 1 && in_mst[3] == 0 && w13 < best { best = w13; best_to = 3; }
        if in_mst[2] == 1 && in_mst[3] == 0 && w23 < best { best = w23; best_to = 3; }
        if in_mst[1] == 1 && in_mst[0] == 0 && w01 < best { best = w01; best_to = 0; }
        if in_mst[2] == 1 && in_mst[0] == 0 && w02 < best { best = w02; best_to = 0; }
        if in_mst[2] == 1 && in_mst[1] == 0 && w12 < best { best = w12; best_to = 1; }
