fn manhattan(x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    let dx = x2 - x1;
    let dy = y2 - y1;
    (if dx < 0 { 0 - dx } else { dx }) + (if dy < 0 { 0 - dy } else { dy })
}
fn a_star_f(g: i64, x: i64, y: i64, gx: i64, gy: i64) -> i64 {
    g + manhattan(x, y, gx, gy)
}
fn best_next(x: i64, y: i64, g: i64, gx: i64, gy: i64) -> i64 {
    let f_up = a_star_f(g + 1, x, y - 1, gx, gy);
    let f_down = a_star_f(g + 1, x, y + 1, gx, gy);
    let f_left = a_star_f(g + 1, x - 1, y, gx, gy);
    let f_right = a_star_f(g + 1, x + 1, y, gx, gy);
    let mut best = f_up;
    if f_down < best { best = f_down; }
    if f_left < best { best = f_left; }
    if f_right < best { best = f_right; }
    best
}
