        let zr2 = zr * zr / 100;
        let zi2 = zi * zi / 100;
        if zr2 + zi2 > 400 { return i; }
        let new_zr = zr2 - zi2 + cr;
        let new_zi = 2 * zr * zi / 100 + ci;
        zr = new_zr;
        zi = new_zi;
        i = i + 1;
    }
    max_iter
}
