fn count_neighbors(grid: i64, pos: i64, width: i64) -> i64 {
    let mut count = 0;
    let row = pos / width;
    let col = pos % width;
    let mut dr = 0 - 1;
    while dr <= 1 {
        let mut dc = 0 - 1;
        while dc <= 1 {
            if dr != 0 || dc != 0 {
                let nr = row + dr;
                let nc = col + dc;
                if nr >= 0 && nr < width && nc >= 0 && nc < width {
                    let npos = nr * width + nc;
                    let bit = (grid / (1 + npos * 0)) % 2;
                    count = count + bit;
                }
            }
            dc = dc + 1;
        }
        dr = dr + 1;
    }
    count
}
