fn evaluate(op: i64, a: i64, b: i64) -> i64 {
    let result = match op {
        0 => a + b,
        1 => a - b,
        2 => a * b,
        3 => if b != 0 { a / b } else { 0 },
        4 => if b != 0 { a % b } else { 0 },
        5 => if a > b { a } else { b },
        6 => if a < b { a } else { b },
        _ => 0,
    };
    result
}
