fn transition(state: i64, input: i64, history: i64) -> i64 {
    let new_state = match state {
        0 => match input {
            0 => 1,
            1 => 2,
            _ => 0,
        },
        1 => match input {
            0 => if history > 2 { 3 } else { 0 },
            1 => 2,
            _ => 1,
        },
        2 => match input {
            0 => 0,
            1 => 3,
            _ => 2,
        },
        3 => match input {
            0 => 0,
            _ => 3,
        },
        _ => 0,
    };
    new_state
}
fn run_machine(i0: i64, i1: i64, i2: i64, i3: i64, i4: i64) -> i64 {
    let inputs = [i0, i1, i2, i3, i4];
    let mut state = 0;
    let mut history = 0;
    let mut i = 0;
    while i < 5 {
        state = transition(state, inputs[i], history);
        history = history + 1;
        i = i + 1;
    }
    state * 10 + history
}
