fn mat2_trace_pow(a: i64, b: i64, c: i64, d: i64, n: i64) -> i64 {
    let mut ra = a;
    let mut rb = b;
    let mut rc = c;
    let mut rd = d;
    let mut i = 1;
    while i < n {
        let na = ra * a + rb * c;
        let nb = ra * b + rb * d;
        let nc = rc * a + rd * c;
        let nd = rc * b + rd * d;
        ra = na % 1000;
        rb = nb % 1000;
        rc = nc % 1000;
        rd = nd % 1000;
        i = i + 1;
    }
    (ra + rd) % 1000
}
