fn lucas(n: i64) -> i64 {
    if n == 0 { return 2; }
    if n == 1 { return 1; }
    let mut a = 2;
    let mut b = 1;
    let mut i = 2;
    while i <= n {
        let c = a + b;
        a = b;
        b = c;
        i = i + 1;
    }
    b
}
fn fib_lucas_identity(n: i64) -> i64 {
    let l = lucas(n);
    let mut fa = 0;
    let mut fb = 1;
    let mut i = 2;
    while i <= n {
        let c = fa + fb;
        fa = fb;
        fb = c;
        i = i + 1;
    }
    let f = if n <= 1 { n } else { fb };
    l * l - 5 * f * f
}
