fn sort_digits_asc(n: i64) -> i64 {
    let mut d = [n / 1000, (n / 100) % 10, (n / 10) % 10, n % 10];
    let mut i = 0;
    while i < 4 {
        let mut j = i + 1;
        while j < 4 {
            if d[j] < d[i] {
                let t = d[i]; d[i] = d[j]; d[j] = t;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    d[0] * 1000 + d[1] * 100 + d[2] * 10 + d[3]
}
fn sort_digits_desc(n: i64) -> i64 {
    let mut d = [n / 1000, (n / 100) % 10, (n / 10) % 10, n % 10];
    let mut i = 0;
    while i < 4 {
        let mut j = i + 1;
        while j < 4 {
            if d[j] > d[i] {
                let t = d[i]; d[i] = d[j]; d[j] = t;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    d[0] * 1000 + d[1] * 100 + d[2] * 10 + d[3]
}
fn kaprekar_steps(n: i64) -> i64 {
    let mut x = n;
    let mut steps = 0;
    while x != 6174 && steps < 10 {
        let desc = sort_digits_desc(x);
        let asc = sort_digits_asc(x);
        x = desc - asc;
        if x == 0 { return 0 - 1; }
        steps = steps + 1;
    }
    steps
}
