fn to_gray(n: i64) -> i64 {
    let mut result = 0;
    let mut bit = 1;
    let mut i = 0;
    while i < 10 {
        let nb = (n / bit) % 2;
        let nb1 = (n / (bit * 2)) % 2;
        let gb = if nb != nb1 { 1 } else { 0 };
        result = result + gb * bit;
        bit = bit * 2;
        i = i + 1;
    }
    result
}
fn from_gray(g: i64) -> i64 {
    let mut n = 0;
    let mut mask = 512;
    while mask > 0 {
        let gb = (g / mask) % 2;
        let nb = (n / (mask * 2)) % 2;
        let bit = if gb != nb { 1 } else { 0 };
        n = n + bit * mask;
        mask = mask / 2;
    }
    n
}
fn main() {
    let mut i = 0;
    while i < 8 {
        let g = to_gray(i);
        println!("{}", g);
        i = i + 1;
    }
    println!("{}", from_gray(to_gray(42)));
}

fn roman_value(n: i64) -> i64 {
    let mut rem = n;
    let mut count = 0;
    while rem >= 1000 { rem = rem - 1000; count = count + 1; }
    while rem >= 900 { rem = rem - 900; count = count + 2; }
    while rem >= 500 { rem = rem - 500; count = count + 1; }
    while rem >= 400 { rem = rem - 400; count = count + 2; }
    while rem >= 100 { rem = rem - 100; count = count + 1; }
    while rem >= 90 { rem = rem - 90; count = count + 2; }
    while rem >= 50 { rem = rem - 50; count = count + 1; }
    while rem >= 40 { rem = rem - 40; count = count + 2; }
    while rem >= 10 { rem = rem - 10; count = count + 1; }
    while rem >= 9 { rem = rem - 9; count = count + 2; }
    while rem >= 5 { rem = rem - 5; count = count + 1; }
    while rem >= 4 { rem = rem - 4; count = count + 2; }
    while rem >= 1 { rem = rem - 1; count = count + 1; }
    count
}
