fn to_base(n: i64, base: i64) -> i64 {
    if n == 0 { return 0; }
    let mut result = 0;
    let mut place = 1;
    let mut x = n;
    while x > 0 {
        let digit = x % base;
        result = result + digit * place;
        place = place * 10;
        x = x / base;
    }
    result
}
fn from_base(n: i64, base: i64) -> i64 {
    let mut result = 0;
    let mut x = n;
    let mut place = 1;
    while x > 0 {
        let digit = x % 10;
        result = result + digit * place;
        place = place * base;
        x = x / 10;
    }
    result
}
fn main() {
    println!("{}", to_base(42, 2));
    println!("{}", to_base(255, 16));
    println!("{}", from_base(101010, 2));
    println!("{}", to_base(100, 8));
}

fn day_of_week(year: i64, month: i64, day: i64) -> i64 {
    let mut y = year;
    let mut m = month;
    if m < 3 {
        m = m + 12;
        y = y - 1;
    }
    let k = y % 100;
    let j = y / 100;
    let h = (day + (13 * (m + 1)) / 5 + k + k / 4 + j / 4 - 2 * j) % 7;
    let result = ((h + 6) % 7) + 1;
    result
}
fn main() {
    println!("{}", day_of_week(2024, 1, 1));
    println!("{}", day_of_week(2000, 3, 15));
    println!("{}", day_of_week(1970, 1, 1));
}

fn luhn_check(d0: i64, d1: i64, d2: i64, d3: i64, d4: i64, d5: i64, d6: i64, d7: i64) -> i64 {
    let digits = [d0, d1, d2, d3, d4, d5, d6, d7];
    let mut sum = 0;
    let mut i = 0;
    while i < 8 {
        let mut d = digits[i];
        if i % 2 == 0 {
            d = d * 2;
            if d > 9 { d = d - 9; }
        }
        sum = sum + d;
        i = i + 1;
    }
    if sum % 10 == 0 { 1 } else { 0 }
}
fn main() {
    println!("{}", luhn_check(7, 9, 9, 2, 7, 3, 9, 8));
    println!("{}", luhn_check(1, 2, 3, 4, 5, 6, 7, 8));
}

fn isbn10_check(d0: i64, d1: i64, d2: i64, d3: i64, d4: i64, d5: i64, d6: i64, d7: i64, d8: i64) -> i64 {
    let digits = [d0, d1, d2, d3, d4, d5, d6, d7, d8];
    let mut sum = 0;
    let mut i = 0;
    while i < 9 {
        sum = sum + digits[i] * (10 - i);
        i = i + 1;
    }
    let check = (11 - sum % 11) % 11;
    check
}
fn main() {
