}

fn sparse_dot(idx0: i64, val0: i64, idx1: i64, val1: i64, idx2: i64, val2: i64,
              bidx0: i64, bval0: i64, bidx1: i64, bval1: i64, bidx2: i64, bval2: i64) -> i64 {
    let a_idx = [idx0, idx1, idx2];
    let a_val = [val0, val1, val2];
    let b_idx = [bidx0, bidx1, bidx2];
    let b_val = [bval0, bval1, bval2];
    let mut dot = 0;
    let mut i = 0;
    while i < 3 {
        let mut j = 0;
        while j < 3 {
            if a_idx[i] == b_idx[j] {
                dot = dot + a_val[i] * b_val[j];
            }
            j = j + 1;
        }
        i = i + 1;
    }
    dot
}
