}

fn complex_mul_re(a_re: i64, a_im: i64, b_re: i64, b_im: i64) -> i64 {
    a_re * b_re - a_im * b_im
}
fn complex_mul_im(a_re: i64, a_im: i64, b_re: i64, b_im: i64) -> i64 {
    a_re * b_im + a_im * b_re
}
fn complex_mag_sq(re: i64, im: i64) -> i64 {
    re * re + im * im
}
fn complex_pow_re(re: i64, im: i64, n: i64) -> i64 {
    let mut r = 1;
    let mut i = 0;
    let mut pr = re;
    let mut pi = im;
    if n == 0 { return 1; }
    let mut rr = re;
    let mut ri = im;
    let mut k = 1;
    while k < n {
        let nr = complex_mul_re(rr, ri, re, im);
        let ni = complex_mul_im(rr, ri, re, im);
        rr = nr;
        ri = ni;
        k = k + 1;
    }
    rr
}
fn main() {
    println!("{}", complex_mul_re(3, 4, 1, 2));
    println!("{}", complex_mul_im(3, 4, 1, 2));
