    println!("{}", complex_pow_re(1, 1, 4));
}

fn gcd(a: i64, b: i64) -> i64 {
    let mut x = if a < 0 { 0 - a } else { a };
    let mut y = if b < 0 { 0 - b } else { b };
    while y != 0 {
        let t = y;
        y = x % y;
        x = t;
    }
    x
}
fn rat_add(n1: i64, d1: i64, n2: i64, d2: i64) -> i64 {
    let num = n1 * d2 + n2 * d1;
    let den = d1 * d2;
    let g = gcd(num, den);
    let rn = num / g;
    let rd = den / g;
    rn * 1000 + rd
}
fn rat_mul(n1: i64, d1: i64, n2: i64, d2: i64) -> i64 {
    let num = n1 * n2;
    let den = d1 * d2;
    let g = gcd(num, den);
    (num / g) * 1000 + (den / g)
}
