fn cauchy_bound(a3: i64, a2: i64, a1: i64, a0: i64) -> i64 {
    if a3 == 0 { return 0; }
    let r2 = if a2 < 0 { 0 - a2 } else { a2 };
    let r1 = if a1 < 0 { 0 - a1 } else { a1 };
    let r0 = if a0 < 0 { 0 - a0 } else { a0 };
    let abs_a3 = if a3 < 0 { 0 - a3 } else { a3 };
    let max_ratio = r2 / abs_a3;
    let mr1 = r1 / abs_a3;
    let mr0 = r0 / abs_a3;
    let mut bound = max_ratio;
    if mr1 > bound { bound = mr1; }
    if mr0 > bound { bound = mr0; }
    1 + bound
}
fn descartes_sign_changes(a3: i64, a2: i64, a1: i64, a0: i64) -> i64 {
    let coeffs = [a3, a2, a1, a0];
    let mut changes = 0;
    let mut prev_sign = if coeffs[0] > 0 { 1 } else { 0 - 1 };
    let mut i = 1;
    while i < 4 {
        if coeffs[i] != 0 {
            let sign = if coeffs[i] > 0 { 1 } else { 0 - 1 };
            if sign != prev_sign { changes = changes + 1; }
            prev_sign = sign;
        }
        i = i + 1;
    }
    changes
}
