fn is_primitive_root(g: i64, p: i64) -> i64 {
    let mut i = 1;
    while i < p - 1 {
        if pow_mod(g, i, p) == 1 { return 0; }
        i = i + 1;
    }
    1
}
fn find_primitive_root(p: i64) -> i64 {
    let mut g = 2;
    while g < p {
        if is_primitive_root(g, p) == 1 { return g; }
        g = g + 1;
    }
    0 - 1
}
