fn mat_mul_mod(a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, m: i64) -> i64 {
    let r00 = (a * e + b * g) % m;
    let r01 = (a * f + b * h) % m;
    let r10 = (c * e + d * g) % m;
    let r11 = (c * f + d * h) % m;
    r00 * 1000000 + r01 * 10000 + r10 * 100 + r11
}
fn fib_mod(n: i64, m: i64) -> i64 {
    if n <= 1 { return n; }
    let mut ra = 1;
    let mut rb = 1;
    let mut rc = 1;
    let mut rd = 0;
    let mut ba = 1;
    let mut bb = 1;
    let mut bc = 1;
    let mut bd = 0;
    let mut e = n - 1;
    while e > 0 {
        if e % 2 == 1 {
            let na = (ra * ba + rb * bc) % m;
            let nb = (ra * bb + rb * bd) % m;
            let nc = (rc * ba + rd * bc) % m;
            let nd = (rc * bb + rd * bd) % m;
            ra = na; rb = nb; rc = nc; rd = nd;
        }
        let na = (ba * ba + bb * bc) % m;
        let nb = (ba * bb + bb * bd) % m;
        let nc = (bc * ba + bd * bc) % m;
        let nd = (bc * bb + bd * bd) % m;
        ba = na; bb = nb; bc = nc; bd = nd;
        e = e / 2;
    }
    rb
}
fn main() {
    println!("{}", fib_mod(10, 1000));
    println!("{}", fib_mod(20, 1000));
    println!("{}", fib_mod(50, 1000000));
}

fn tribonacci(n: i64) -> i64 {
