    if n == 1 { return 0; }
    if n == 2 { return 1; }
    let mut a = 0;
    let mut b = 0;
    let mut c = 1;
    let mut i = 3;
    while i <= n {
        let d = a + b + c;
        a = b;
        b = c;
        c = d;
        i = i + 1;
    }
    c
}
