fn isqrt(n: i64) -> i64 {
    if n <= 1 { return n; }
    let mut x = n;
    let mut y = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}
fn juggler_length(n: i64) -> i64 {
    let mut x = n;
    let mut steps = 0;
    while x != 1 && steps < 100 {
        if x % 2 == 0 {
            x = isqrt(x);
        } else {
            let s = isqrt(x);
            x = s * s * s / (x * x / (s * s));
            if x <= 0 { x = 1; }
        }
        steps = steps + 1;
    }
    steps
}
