fn persistence(n: i64) -> i64 {
    let mut x = n;
    let mut steps = 0;
    while x >= 10 {
        let mut product = 1;
        while x > 0 {
            product = product * (x % 10);
            x = x / 10;
        }
        x = product;
        steps = steps + 1;
    }
    steps
}
