fn mod_sqrt_simple(a: i64, p: i64) -> i64 {
    if p % 4 == 3 {
        return pow_mod(a, (p + 1) / 4, p);
    }
    let mut r = 2;
    while r < p {
        if r * r % p == a % p { return r; }
        r = r + 1;
    }
    0 - 1
}
