fn catmull_rom(p0: i64, p1: i64, p2: i64, p3: i64, t_num: i64, t_den: i64) -> i64 {
    let t = t_num;
    let t2 = t * t;
    let t3 = t2 * t;
    let td = t_den;
    let td2 = td * td;
    let td3 = td2 * td;
    let a = (0 - p0 + 3 * p1 - 3 * p2 + p3) * t3 / td3;
    let b = (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 / td2;
    let c = (0 - p0 + p2) * t / td;
    let d = 2 * p1;
    (a + b + c + d) / 2
}
fn main() {
