fn rle_count(data: i64) -> i64 {
    let mut n = data;
    let mut runs = 0;
    let mut prev = -1;
    while n > 0 {
        let digit = n % 10;
        if digit != prev {
            runs += 1;
            prev = digit;
        }
        n /= 10;
    }
    runs
}
