fn caesar_shift(value: i64, shift: i64) -> i64 {
    let mut result = 0;
    let mut n = value;
    let mut place = 1;
    while n > 0 {
        let digit = n % 10;
        let shifted = (digit + shift) % 10;
        result += shifted * place;
        place *= 10;
        n /= 10;
    }
    result
}
