fn hamming_sum(n: i64) -> i64 {
    let mut total = 0;
    let mut i = 1;
    while i <= n {
        let mut bits = 0;
        let mut x = i;
        while x > 0 {
            bits += x & 1;
            x >>= 1;
        }
        total += bits;
        i += 1;
    }
    total
}
fn main() {
    let result = hamming_sum(15);
    println!("{}", result);
}

fn digital_root(mut n: i64) -> i64 {
    while n >= 10 {
        let mut s = 0;
        while n > 0 {
            s += n % 10;
            n /= 10;
        }
        n = s;
    }
    n
}
fn dr_sum(limit: i64) -> i64 {
    let mut total = 0;
    let mut i = 1;
    while i <= limit {
        total += digital_root(i);
        i += 1;
    }
    total
}
