fn sort_digits_asc(mut n: i64) -> i64 {
    let mut i = 0;
    while i < 4 {
        let mut j = 0;
        while j < 3 {
            let d1 = (n / pow10(j)) % 10;
            let d2 = (n / pow10(j + 1)) % 10;
            if d1 > d2 {
                n = n - d1 * pow10(j) - d2 * pow10(j + 1) + d2 * pow10(j) + d1 * pow10(j + 1);
            }
            j += 1;
        }
        i += 1;
    }
    n
}
fn pow10(e: i64) -> i64 {
    let mut r = 1;
    let mut i = 0;
    while i < e {
        r *= 10;
        i += 1;
    }
