}
fn kaprekar_steps(mut n: i64) -> i64 {
    let mut steps = 0;
    while n != 6174 && steps < 10 {
        let asc = sort_digits_asc(n);
        let mut desc = 0;
        let mut i = 0;
        while i < 4 {
            let d = (asc / pow10(i)) % 10;
            desc = desc + d * pow10(3 - i);
            i += 1;
        }
        n = desc - asc;
        if n == 0 { return -1; }
        steps += 1;
    }
    steps
}
