    let mut high = n - 1;
    let mut steps = 0;
    while low <= high {
        let mid = (low + high) / 2;
        steps += 1;
        if mid == target {
            return steps;
        } else if mid < target {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
