fn interpolation_steps(n: i64) -> i64 {
    let mut steps = 0;
    let mut low = 0;
    let mut high = n - 1;
    let target = n * 3 / 4;
    while low <= high && target >= low && target <= high {
        if high == low {
            if low == target { steps += 1; }
            return steps;
        }
        let pos = low + (target - low) * (high - low) / (high - low + 1);
        steps += 1;
        if pos == target {
            return steps;
        } else if pos < target {
            low = pos + 1;
        } else {
            high = pos - 1;
        }
    }
    steps
}
