fn count_palindromes(n: i64) -> i64 {
    let mut count = 0;
    let mut x = n;
    let mut digits = 0;
    while x > 0 {
        digits += 1;
        x /= 10;
    }
    count += digits;
    let mut len = 2;
    while len <= digits {
        let mut start = 0;
        while start + len <= digits {
            let mut extracted = 0;
            let mut i = 0;
            while i < len {
                let pos = digits - start - i - 1;
                let mut tmp = n;
                let mut j = 0;
                while j < pos {
                    tmp /= 10;
                    j += 1;
                }
                let d = tmp % 10;
                let mut power = 1;
                let mut k = 0;
                while k < i {
                    power *= 10;
                    k += 1;
                }
                extracted += d * power;
                i += 1;
            }
            let mut reversed = 0;
            let mut e = extracted;
            while e > 0 {
                reversed = reversed * 10 + e % 10;
                e /= 10;
            }
            if extracted == reversed && extracted > 0 {
                count += 1;
            }
            start += 1;
        }
        len += 1;
    }
    count
}
