        tortoise = (tortoise * tortoise + 1) % modulus;
        hare = (hare * hare + 1) % modulus;
        hare = (hare * hare + 1) % modulus;
    }
    let mut mu = 0;
    tortoise = start;
    while tortoise != hare {
        tortoise = (tortoise * tortoise + 1) % modulus;
        hare = (hare * hare + 1) % modulus;
