fn carmichael(n: i64) -> i64 {
    let mut result = 1;
    let mut i = 1;
    while i <= n {
        if gcd(i, n) == 1 {
            let mut order = 1;
            let mut power = i % n;
            while power != 1 && order <= n {
                power = (power * i) % n;
                order += 1;
            }
            result = lcm(result, order);
        }
        i += 1;
    }
    result
}
