        let xi = (i * 7 + 3) % 20;
        let yi = (i * 11 + 5) % 20;
        let mut on_hull = 1;
        let mut j = 0;
        while j < n {
            if j == i { j += 1; continue; }
            let xj = (j * 7 + 3) % 20;
            let yj = (j * 11 + 5) % 20;
            let mut k = j + 1;
            while k < n {
                if k == i { k += 1; continue; }
                let xk = (k * 7 + 3) % 20;
                let yk = (k * 11 + 5) % 20;
                let cp = cross_product(xj, yj, xk, yk, xi, yi);
                if cp < -10 {
                    on_hull = 0;
                }
                k += 1;
            }
            j += 1;
        }
        hull_count += on_hull;
        i += 1;
    }
    hull_count
}
