fn rule30_step(state: i64) -> i64 {
    let mut new_state = 0;
    let mut bit = 0;
    while bit < 16 {
        let left = (state >> (bit + 1)) & 1;
        let center = (state >> bit) & 1;
        let right = if bit > 0 { (state >> (bit - 1)) & 1 } else { 0 };
        let pattern = left * 4 + center * 2 + right;
        let rule30 = 30;
        let new_bit = (rule30 >> pattern) & 1;
        new_state = new_state | (new_bit << bit);
        bit += 1;
    }
    new_state
}
fn evolve(initial: i64, steps: i64) -> i64 {
    let mut state = initial;
    let mut i = 0;
    while i < steps {
