    let mut i = 0;
    while i < count {
        state = state ^ ((state << 13) & 0x7FFFFFFF);
        state = state ^ ((state >> 17) & 0x7FFFFFFF);
        state = state ^ ((state << 5) & 0x7FFFFFFF);
        state = state & 0x7FFFFFFF;
        sum += state % 100;
        i += 1;
    }
    sum
}
