}

fn lcg_period(a: i64, c: i64, m: i64, seed: i64) -> i64 {
    let mut tortoise = (a * seed + c) % m;
    let mut hare = (a * ((a * seed + c) % m) + c) % m;
    while tortoise != hare {
        tortoise = (a * tortoise + c) % m;
        hare = (a * ((a * hare + c) % m) + c) % m;
    }
    let mut period = 1;
    hare = (a * tortoise + c) % m;
    while tortoise != hare {
        hare = (a * hare + c) % m;
        period += 1;
    }
    period
}
