fn feistel_round(left: i64, right: i64, key: i64) -> i64 {
    let f = ((right * key) ^ (right >> 3)) & 0xFFFF;
    let new_left = right;
    let new_right = left ^ f;
    new_left * 65536 + (new_right & 0xFFFF)
}
fn feistel_encrypt(data: i64, rounds: i64) -> i64 {
    let mut left = (data >> 16) & 0xFFFF;
    let mut right = data & 0xFFFF;
    let mut i = 0;
    while i < rounds {
        let key = (i + 1) * 12345;
        let result = feistel_round(left, right, key);
        left = result / 65536;
        right = result % 65536;
        i += 1;
    }
    left * 65536 + right
}
