    while n > 0 {
        let d = n % 10;
        let kd = k % 10;
        let encrypted = (d + kd) % 10;
        result += encrypted * place;
        place *= 10;
        n /= 10;
        k /= 10;
        if k == 0 { k = key; }
    }
    result
}
