fn bloom_bits(n: i64, filter_size: i64) -> i64 {
    let mut bits_set = 0;
    let mut filter = 0;
    let mut i = 0;
    while i < n {
        let h1 = (i * 2654435761) & 0x7FFFFFFF;
        let h2 = (i * 2246822519) & 0x7FFFFFFF;
        let b1 = h1 % filter_size;
        let b2 = h2 % filter_size;
        let mask1 = 1 << (b1 % 30);
        let mask2 = 1 << (b2 % 30);
        let before = filter;
        filter = filter | mask1 | mask2;
        if filter != before {
            bits_set += 1;
        }
        i += 1;
    }
    bits_set
}
