fn calkin_wilf_sum(n: i64) -> i64 {
    let mut num = 1;
    let mut den = 1;
    let mut sum = 0;
    let mut i = 0;
    while i < n {
        sum += num + den;
        if num <= den {
            den = den - num;
            if den == 0 {
                num = 1;
                den = num + 1;
            }
        } else {
            num = num - den;
        }
        let new_num = den;
        let new_den = 2 * (den / num) * num + num - den;
        let abs_den = if new_den < 0 { -new_den } else { new_den };
        if abs_den > 0 {
            num = new_num;
            den = abs_den;
        } else {
            num += 1;
            den = 1;
        }
        i += 1;
    }
    sum
}
