fn life_1d(initial: i64, steps: i64) -> i64 {
    let mut state = initial;
    let mut i = 0;
    while i < steps {
        let mut new_state = 0;
        let mut bit = 1;
        while bit < 15 {
            let left = (state >> (bit + 1)) & 1;
            let center = (state >> bit) & 1;
            let right = (state >> (bit - 1)) & 1;
            let neighbors = left + right;
            let alive = if center == 1 {
                if neighbors == 1 { 1 } else { 0 }
            } else {
                if neighbors == 1 { 1 } else { 0 }
            };
            new_state = new_state | (alive << bit);
            bit += 1;
        }
        state = new_state;
        i += 1;
    }
    let mut popcount = 0;
    let mut s = state;
    while s > 0 {
        popcount += s & 1;
        s >>= 1;
    }
    popcount
}
