fn hill_climb(start: i64, limit: i64) -> i64 {
    let mut x = start;
    let mut improved = 1;
    while improved == 1 {
        improved = 0;
        let current = -(x * x) + 20 * x;
        let left = -((x - 1) * (x - 1)) + 20 * (x - 1);
        let right = -((x + 1) * (x + 1)) + 20 * (x + 1);
        if left > current && x > 0 {
            x -= 1;
            improved = 1;
        } else if right > current && x < limit {
            x += 1;
            improved = 1;
        }
    }
    -(x * x) + 20 * x
}
