        let m1 = lo + (hi - lo) / 3;
        let m2 = hi - (hi - lo) / 3;
        let f1 = -(m1 * m1) + 100 * m1;
        let f2 = -(m2 * m2) + 100 * m2;
        if f1 < f2 {
            lo = m1 + 1;
        } else {
            hi = m2 - 1;
        }
        i += 1;
    }
    let mid = (lo + hi) / 2;
