fn fractional_knapsack(n: i64, capacity: i64) -> i64 {
    let mut total_value = 0;
    let mut remaining = capacity;
    let mut best_ratio = 0;
    let mut i = 0;
    while i < n && remaining > 0 {
        let weight = i + 1;
        let value = (i + 1) * (n - i);
        let ratio = value * 100 / weight;
        if ratio > best_ratio || i == 0 {
            let take = if weight <= remaining { weight } else { remaining };
            total_value += value * take / weight;
            remaining -= take;
            best_ratio = ratio;
        }
        i += 1;
    }
    total_value
}
