fn set_cover_iters(universe: i64, n_sets: i64) -> i64 {
    let mut covered = 0;
    let mut iters = 0;
    while covered < universe && iters < n_sets {
        let mut best_new = 0;
        let mut s = 0;
        while s < n_sets {
            let mut new_covered = 0;
            let mut elem = 0;
            while elem < universe {
                let in_set = (elem + s) % 3 == 0;
                let already = elem < covered;
                if in_set && !already {
                    new_covered += 1;
                }
                elem += 1;
            }
            if new_covered > best_new {
                best_new = new_covered;
            }
            s += 1;
        }
        covered += best_new;
        iters += 1;
    }
    iters
}
