        let b = ((i + 1) * 13 + 5) % 10;
        let pair = a * 10 + b;
        let mut is_new = 1;
        let mut j = 0;
        while j < i {
            let pa = (j * 13 + 5) % 10;
            let pb = ((j + 1) * 13 + 5) % 10;
            if pa * 10 + pb == pair {
                is_new = 0;
            }
            j += 1;
        }
        unique_pairs += is_new;
        total_pairs += 1;
        i += 1;
    }
