fn reservoir_sum(n: i64, k: i64) -> i64 {
    let mut sum = 0;
    let mut i = 0;
    while i < k && i < n {
        sum += (i * 31 + 7) % 100;
        i += 1;
    }
    while i < n {
        let val = (i * 31 + 7) % 100;
        let seed = (i * 2654435761) & 0x7FFFFFFF;
        if seed % (i + 1) < k {
            let replace_idx = seed % k;
            let old_val = ((replace_idx) * 31 + 7) % 100;
            sum = sum - old_val + val;
        }
        i += 1;
    }
    sum
}
