    println!("{}", result);
}

fn minimax(depth: i64, is_max: i64, node: i64) -> i64 {
    if depth == 0 {
        return (node * 37 + 13) % 100;
    }
    let left = minimax(depth - 1, 1 - is_max, node * 2);
    let right = minimax(depth - 1, 1 - is_max, node * 2 + 1);
    if is_max == 1 {
        if left > right { left } else { right }
    } else {
        if left < right { left } else { right }
    }
}
