    println!("{}", result);
}

fn alpha_beta(depth: i64, alpha: i64, beta: i64, is_max: i64, node: i64) -> i64 {
    if depth == 0 {
        return (node * 37 + 13) % 100;
    }
    if is_max == 1 {
        let mut a = alpha;
        let val_l = alpha_beta(depth - 1, a, beta, 0, node * 2);
        if val_l > a { a = val_l; }
        if a >= beta { return a; }
        let val_r = alpha_beta(depth - 1, a, beta, 0, node * 2 + 1);
        if val_r > a { a = val_r; }
        a
    } else {
        let mut b = beta;
        let val_l = alpha_beta(depth - 1, alpha, b, 1, node * 2);
        if val_l < b { b = val_l; }
        if alpha >= b { return b; }
        let val_r = alpha_beta(depth - 1, alpha, b, 1, node * 2 + 1);
        if val_r < b { b = val_r; }
        b
    }
}
