fn deque_sim(n: i64) -> i64 {
    let mut front = 0;
    let mut back = 0;
    let mut size = 0;
    let mut ops = 0;
    let mut i = 0;
    while i < n {
        let op = i % 4;
        if op == 0 {
            front += i;
            size += 1;
        } else if op == 1 {
            back += i;
            size += 1;
        } else if op == 2 && size > 0 {
            front -= front / size;
            size -= 1;
        } else if size > 0 {
            back -= back / size;
            size -= 1;
        }
        ops += 1;
        i += 1;
    }
    front + back
}
