fn stack_eval(program: i64) -> i64 {
    let mut stack_top = 0;
    let mut stack_next = 0;
    let mut n = program;
    while n > 0 {
        let op = n % 10;
        n /= 10;
        if op < 5 {
            stack_next = stack_top;
            stack_top = op * 3 + 1;
        } else if op == 5 {
            stack_top = stack_top + stack_next;
            stack_next = 0;
        } else if op == 6 {
            stack_top = stack_top * stack_next;
            stack_next = 0;
        } else {
            stack_top = stack_top - stack_next;
            stack_next = 0;
        }
    }
    stack_top
}
