fn secant_root(x0: i64, x1: i64, target: i64) -> i64 {
    let mut prev = x0;
    let mut curr = x1;
    let mut i = 0;
    while i < 20 {
        let f_prev = prev * prev - target;
        let f_curr = curr * curr - target;
        if f_curr == f_prev { return curr; }
        let next = curr - f_curr * (curr - prev) / (f_curr - f_prev);
        prev = curr;
        curr = next;
        if f_curr == 0 { return curr; }
        i += 1;
    }
    curr
}
