fn round_robin(n: i64, quantum: i64) -> i64 {
    let mut total_wait = 0;
    let mut current_time = 0;
    let mut remaining_total = 0;
    let mut i = 0;
    while i < n {
        remaining_total += (i + 1) * 3;
        i += 1;
    }
    let mut rounds = 0;
    while remaining_total > 0 && rounds < 100 {
        i = 0;
        while i < n {
            let burst = (i + 1) * 3;
            let remaining = burst - (rounds * quantum);
            if remaining > 0 {
                let run = if remaining < quantum { remaining } else { quantum };
                current_time += run;
                remaining_total -= run;
            }
            i += 1;
        }
        rounds += 1;
    }
    current_time
}
