        let mut min_idx = -1;
        let mut i = 0;
        while i < n {
            let burst = ((i * 7 + 3) % 10) + 1;
            let already_done = (done >> i) & 1;
            if already_done == 0 && burst < min_burst {
                min_burst = burst;
                min_idx = i;
            }
            i += 1;
        }
        if min_idx >= 0 {
            total_wait += current_time;
            current_time += min_burst;
            done = done | (1 << min_idx);
        }
    }
    total_wait
}
