        let set = addr % sets;
        let tag = addr / sets;
        let cached = (set * ways + tag) % (sets * ways);
        let is_hit = cached < ways && (tag * 31 + set) % 5 < 3;
        if !is_hit {
            misses += 1;
        }
        i += 1;
    }
    misses
}
