        let mut min_dist = 10000;
        let mut nearest = -1;
        let mut i = 0;
        while i < n {
            if (visited >> i) & 1 == 0 {
                let pos = (i * 37 + 11) % 200;
                let dist = current - pos;
                let abs_dist = if dist < 0 { -dist } else { dist };
                if abs_dist < min_dist {
                    min_dist = abs_dist;
                    nearest = i;
                }
            }
            i += 1;
        }
        if nearest >= 0 {
            total += min_dist;
            current = (nearest * 37 + 11) % 200;
            visited = visited | (1 << nearest);
        }
        count += 1;
    }
    total
}
