fn circuit_breaker(n: i64, threshold: i64, timeout: i64) -> i64 {
    let mut trips = 0;
    let mut failures = 0;
    let mut state = 0;
    let mut cooldown = 0;
    let mut i = 0;
    while i < n {
        let is_failure = (i * 17 + 3) % 5 == 0;
        if state == 0 {
            if is_failure {
                failures += 1;
                if failures >= threshold {
                    state = 1;
                    cooldown = timeout;
                    trips += 1;
                }
            } else {
                failures = 0;
            }
        } else {
            cooldown -= 1;
            if cooldown <= 0 {
                state = 0;
                failures = 0;
            }
        }
        i += 1;
    }
    trips
}
