    let mut g = 0;
    while g < groups {
        let size = if g < n % groups { per_group + 1 } else { per_group };
        let mut i = 0;
        while i < size {
            result = result * remaining / (i + 1);
            remaining -= 1;
            i += 1;
        }
        g += 1;
    }
    result
}
