}

fn surjection(n: i64, k: i64) -> i64 {
    let mut total = 0;
    let mut i = 0;
    while i <= k {
        let sign = if (k - i) % 2 == 0 { 1 } else { -1 };
        let mut binom = 1;
        let mut j = 0;
        while j < i {
            binom = binom * (k - j) / (j + 1);
            j += 1;
        }
        let mut power = 1;
        let mut p = 0;
        while p < n {
            power *= k - i;
            p += 1;
        }
        total += sign * binom * power;
        i += 1;
    }
    total
}
fn main() {
    let result = surjection(4, 3);
    println!("{}", result);
}

fn gcd(mut a: i64, mut b: i64) -> i64 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}
fn euler_totient(mut n: i64) -> i64 {
    let mut result = n;
    let mut p = 2;
    while p * p <= n {
        if n % p == 0 {
            while n % p == 0 { n /= p; }
            result -= result / p;
        }
        p += 1;
    }
    if n > 1 { result -= result / n; }
    result
}
fn necklace_count(n: i64, k: i64) -> i64 {
    let mut total = 0;
    let mut d = 1;
    while d <= n {
        if n % d == 0 {
            let mut power = 1;
            let mut i = 0;
            while i < d {
                power *= k;
                i += 1;
            }
            total += euler_totient(n / d) * power;
        }
        d += 1;
    }
    total / n
}
