fn necklace(n: i64, k: i64) -> i64 {
    let mut total = 0;
    let mut d = 1;
    while d <= n {
        if n % d == 0 {
            let mut power = 1;
            let mut i = 0;
            while i < d { power *= k; i += 1; }
            let phi = d;
            total += phi * power;
        }
        d += 1;
    }
    total / n
}
fn bracelet(n: i64, k: i64) -> i64 {
    let neck = necklace(n, k);
    let mut flip_fixed = 0;
    if n % 2 == 0 {
        let half = n / 2;
        let mut p1 = 1;
        let mut i = 0;
        while i < half { p1 *= k; i += 1; }
        let mut p2 = 1;
        i = 0;
        while i < half + 1 { p2 *= k; i += 1; }
        flip_fixed = (p1 + p2) / 2;
    } else {
        let half = (n + 1) / 2;
        let mut p = 1;
        let mut i = 0;
        while i < half { p *= k; i += 1; }
        flip_fixed = p;
    }
    (neck + flip_fixed) / 2
}
