fn bell(n: i64) -> i64 {
    if n == 0 { return 1; }
    let mut prev = 1;
    let mut row_start = 1;
    let mut i = 1;
    while i <= n {
        row_start = prev;
        let mut current = row_start;
        let mut j = 1;
        while j < i {
            current = current + prev;
            prev = current;
            j += 1;
        }
        prev = current;
        i += 1;
    }
    prev
}
