    println!("{}", result);
}

fn cycle_count(n: i64) -> i64 {
    let mut cycles = 0;
    let mut visited = 0;
    let mut i = 0;
    while i < n {
        if (visited >> i) & 1 == 0 {
            cycles += 1;
            let mut current = i;
            while (visited >> current) & 1 == 0 {
                visited = visited | (1 << current);
                current = (current * 3 + 1) % n;
            }
        }
        i += 1;
    }
    cycles
}
