fn hook_product(n: i64) -> i64 {
    let mut product = 1;
    let mut i = 0;
    while i < n {
        let mut j = 0;
        while j < n - i {
            let hook = (n - i - 1) + (n - i - j - 1) + 1;
            product *= hook;
            j += 1;
        }
        i += 1;
    }
    product
}
