fn max_run(mut n: i64) -> i64 {
    let mut max_len = 0;
    let mut current = 0;
    let mut prev_bit = -1;
    while n > 0 {
        let bit = n & 1;
        if bit == prev_bit {
            current += 1;
        } else {
            current = 1;
            prev_bit = bit;
        }
        if current > max_len {
            max_len = current;
        }
        n >>= 1;
    }
    max_len
}
