        let mut rank = 0;
        let mut j = 1;
        while j <= i && j <= 10 {
            let prev = ((i - j) * 13 + 3) % 10;
            if prev == symbol {
                rank = j;
                j = i + 1;
            }
            j += 1;
        }
        if rank == 0 { rank = symbol; }
        total += rank;
        i += 1;
    }
    total
}
