fn dfa_accepts(n: i64) -> i64 {
    let mut accepted = 0;
    let mut input = 0;
    while input < n {
        let mut state = 0;
        let mut bits = input;
        let mut len = 0;
        while bits > 0 || len == 0 {
            let bit = bits & 1;
            state = match state {
                0 => if bit == 0 { 1 } else { 2 },
                1 => if bit == 0 { 0 } else { 2 },
                2 => if bit == 0 { 2 } else { 0 },
                _ => 0,
            };
            bits >>= 1;
            len += 1;
            if len > 4 { break; }
        }
        if state == 0 { accepted += 1; }
        input += 1;
    }
    accepted
}
fn main() {
    let result = dfa_accepts(32);
    println!("{}", result);
}

fn nfa_states(input: i64) -> i64 {
    let mut states = 1;
    let mut bits = input;
    let mut i = 0;
    while i < 8 && bits > 0 {
        let bit = bits & 1;
        if bit == 0 {
            states = states * 2;
            if states > 8 { states = 8; }
        } else {
            states = (states + 1) / 2;
            if states < 1 { states = 1; }
        }
        bits >>= 1;
        i += 1;
    }
    states
}
fn total_nfa_states(n: i64) -> i64 {
