fn pda_stack(input: i64) -> i64 {
    let mut depth = 0;
    let mut max_depth = 0;
    let mut bits = input;
    let mut i = 0;
    while i < 10 {
        let bit = bits & 1;
        if bit == 0 {
            depth += 1;
        } else {
            if depth > 0 { depth -= 1; }
        }
        if depth > max_depth { max_depth = depth; }
        bits >>= 1;
        i += 1;
    }
    max_depth
}
fn total_pda_depth(n: i64) -> i64 {
