fn lcp_sum(n: i64) -> i64 {
    let mut total = 0;
    let mut i = 0;
    while i < n {
        let mut j = i + 1;
        while j < n {
            let mut common = 0;
            let mut a = i;
            let mut b = j;
            while a < n && b < n {
                let da = (a * 13 + 5) % 10;
                let db = (b * 13 + 5) % 10;
                if da == db {
                    common += 1;
                    a += 1;
                    b += 1;
                } else {
                    break;
                }
            }
            total += common;
            j += 1;
        }
        i += 1;
    }
    total
}
