                let insert = prev + 1;
                let delete = curr + 1;
                let replace = prev_diag + cost;
                curr = insert;
                if delete < curr { curr = delete; }
                if replace < curr { curr = replace; }
            }
            prev_diag = prev;
            prev = curr;
            j += 1;
        }
        total += curr;
        i += 1;
    }
    total
}
