    println!("{}", result);
}

fn wildcard_match(n: i64, pattern: i64) -> i64 {
    let p0 = pattern % 10;
    let p1 = (pattern / 10) % 10;
    let p2 = (pattern / 100) % 10;
    let d0 = n % 10;
    let d1 = (n / 10) % 10;
    let d2 = (n / 100) % 10;
    let m0 = p0 == 0 || p0 == d0;
    let m1 = p1 == 0 || p1 == d1;
    let m2 = p2 == 0 || p2 == d2;
    if m0 && m1 && m2 { 1 } else { 0 }
}
