fn longest_repeat(n: i64) -> i64 {
    let mut max_len = 0;
    let mut i = 0;
    while i < n {
        let mut j = i + 1;
        while j < n {
            let mut len = 0;
            let mut a = i;
            let mut b = j;
            while a < n && b < n {
                let da = (a * 17 + 7) % 10;
                let db = (b * 17 + 7) % 10;
                if da == db {
                    len += 1;
                    a += 1;
                    b += 1;
                } else {
                    break;
                }
            }
            if len > max_len { max_len = len; }
            j += 1;
        }
        i += 1;
    }
    max_len
}
