}

fn rk_collisions(n: i64, window: i64) -> i64 {
    let mut collisions = 0;
    let modulus = 997;
    let mut i = 0;
    while i < n - window {
        let mut hash_i = 0;
        let mut k = 0;
        while k < window {
            hash_i = (hash_i * 31 + ((i + k) * 17 + 5) % 26) % modulus;
            k += 1;
        }
        let mut j = i + 1;
        while j < n - window {
            let mut hash_j = 0;
            k = 0;
            while k < window {
                hash_j = (hash_j * 31 + ((j + k) * 17 + 5) % 26) % modulus;
                k += 1;
            }
            if hash_i == hash_j { collisions += 1; }
            j += 1;
        }
        i += 1;
    }
    collisions
}
