        let pattern_char = (i * 7 + 3) % 10;
        if text_char != pattern_char {
            let mut shift = 1;
            let mut j = i;
            while j > 0 {
                j -= 1;
                if (j * 7 + 3) % 10 == text_char {
                    shift = i - j;
                    j = 0;
                }
            }
            total_shifts += shift;
        }
        i += 1;
    }
    total_shifts
}
