fn manacher_sum(n: i64) -> i64 {
    let mut total = 0;
    let mut i = 0;
    while i < n {
        let mut radius = 0;
        while i - radius > 0 && i + radius < n - 1 {
            let left = ((i - radius - 1) * 17 + 5) % 10;
            let right = ((i + radius + 1) * 17 + 5) % 10;
            if left == right {
                radius += 1;
            } else {
                break;
            }
        }
        total += radius;
        i += 1;
    }
    total
}
