fn max_nesting(n: i64) -> i64 {
    let mut global_max = 0;
    let mut seq = 0;
    while seq < n {
        let mut depth = 0;
        let mut max_depth = 0;
        let mut bits = seq;
        let mut i = 0;
        while i < 8 {
            if bits & 1 == 0 {
                depth += 1;
            } else {
                if depth > 0 { depth -= 1; }
            }
            if depth > max_depth { max_depth = depth; }
            bits >>= 1;
            i += 1;
        }
        if max_depth > global_max { global_max = max_depth; }
        seq += 1;
    }
    global_max
}
