        let mut area = 0;
        let mut bits = path;
        let mut i = 0;
        while i < 8 {
            if bits & 1 == 0 {
                height += 1;
            } else {
                if height > 0 { height -= 1; }
            }
            area += height;
            bits >>= 1;
            i += 1;
        }
        total_area += area;
        path += 1;
    }
    total_area
}
