fn tm_steps(input: i64) -> i64 {
    let mut state = 0;
    let mut head = 0;
    let mut tape = input;
    let mut steps = 0;
    while state != 3 && steps < 100 {
        let bit = (tape >> head) & 1;
        if state == 0 {
            if bit == 0 { tape = tape | (1 << head); head += 1; state = 1; }
            else { state = 3; }
        } else if state == 1 {
            if bit == 0 { head += 1; state = 0; }
            else { tape = tape ^ (1 << head); head += 1; state = 2; }
        } else {
            if bit == 0 { state = 3; }
            else { head += 1; state = 0; }
        }
        steps += 1;
    }
    steps
}
