fn majority(data: [i64; 9]) -> i64 {
    let mut candidate = data[0];
    let mut count = 1;
    let mut i = 1;
    while i < 9 {
        if count == 0 {
            candidate = data[i];
            count = 1;
        } else if data[i] == candidate {
            count = count + 1;
        } else {
            count = count - 1;
        }
        i = i + 1;
    }
    let mut verify = 0;
    let mut j = 0;
    while j < 9 {
        if data[j] == candidate {
            verify = verify + 1;
        }
        j = j + 1;
    }
    if verify > 4 {
        return candidate;
    }
    -1
}

