        if bin == 0 { bins[0] = bins[0] + 1; }
        else if bin == 1 { bins[1] = bins[1] + 1; }
        else if bin == 2 { bins[2] = bins[2] + 1; }
        else if bin == 3 { bins[3] = bins[3] + 1; }
        else { bins[4] = bins[4] + 1; }
        i = i + 1;
    }
    let mut peak = 0;
    let mut peak_val = bins[0];
    let mut j = 1;
    while j < 5 {
        if bins[j] > peak_val {
            peak_val = bins[j];
            peak = j;
        }
        j = j + 1;
    }
    peak
}

