fn period(data: [i64; 12]) -> i64 {
    let mut p = 1;
    while p <= 6 {
        let mut matches = 1;
        let mut i = 0;
        while i < 12 {
            if data[i] != data[i % p] {
                matches = 0;
            }
            i = i + 1;
        }
        if matches == 1 {
            return p;
        }
        p = p + 1;
    }
    12
}

