fn edit_dist(a: [i64; 6], b: [i64; 7]) -> i64 {
    let mut prev = [0, 1, 2, 3, 4, 5, 6, 7];
    let mut i = 1;
    while i <= 6 {
        let mut curr = [0, 0, 0, 0, 0, 0, 0, 0];
        curr[0] = i;
        let mut j = 1;
        while j <= 7 {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            let del = prev[j] + 1;
            let ins = curr[j - 1] + 1;
            let sub = prev[j - 1] + cost;
            let mut min_val = del;
            if ins < min_val { min_val = ins; }
            if sub < min_val { min_val = sub; }
            curr[j] = min_val;
            j = j + 1;
        }
        prev = curr;
        i = i + 1;
    }
    prev[7]
}

fn main() {
    let a = [107, 105, 116, 116, 101, 110];
    let b = [115, 105, 116, 116, 105, 110, 103];
    println!("{}", edit_dist(a, b));
}

