fn mtf_cost(data: [i64; 9], alphabet_size: i64) -> i64 {
    let mut total_rank = 0;
    let mut i = 0;
    while i < 9 {
        let val = data[i];
        let mut rank = 0;
        let mut sym = 0;
        while sym < alphabet_size {
            if sym != val {
                let mut last_seen = -1;
                let mut k = 0;
                while k < i {
                    if data[k] == sym {
                        last_seen = k;
                    }
                    k = k + 1;
                }
                let mut val_last = -1;
                let mut k2 = 0;
                while k2 < i {
                    if data[k2] == val {
                        val_last = k2;
                    }
                    k2 = k2 + 1;
                }
                if last_seen > val_last {
                    rank = rank + 1;
                } else if last_seen == -1 && sym < val {
                    rank = rank + 1;
                }
            }
            sym = sym + 1;
        }
        total_rank = total_rank + rank;
        i = i + 1;
    }
    total_rank
}

