    println!("{}", mtf_cost(data, 5));
}

fn nash_eq(a00: i64, a01: i64, a10: i64, a11: i64) -> i64 {
    let p1_r0_best = if a00 >= a01 { 0 } else { 1 };
    let p1_r1_best = if a10 >= a11 { 0 } else { 1 };
    let p2_c0_best = if a00 >= a10 { 0 } else { 1 };
    let p2_c1_best = if a01 >= a11 { 0 } else { 1 };
    if p1_r0_best == 0 && p2_c0_best == 0 {
        return a00;
    }
    if p1_r0_best == 1 && p2_c1_best == 0 {
        return a01;
    }
    if p1_r1_best == 0 && p2_c0_best == 1 {
        return a10;
    }
    if p1_r1_best == 1 && p2_c1_best == 1 {
        return a11;
    }
    (a00 + a01 + a10 + a11) / 4
}

