fn shapley_value(player: i64) -> i64 {
    let mut total = 0;
    let mut perm = 0;
    while perm < 6 {
        let mut before_mask = 0;
        let mut after_mask = 0;
        let orders = [
            [0, 1, 2], [0, 2, 1], [1, 0, 2],
            [1, 2, 0], [2, 0, 1], [2, 1, 0],
        ];
        let mut pos = 0;
        while pos < 3 {
            if orders[perm][pos] == player {
                after_mask = before_mask + (1 << player);
                break;
            }
            before_mask = before_mask + (1 << orders[perm][pos]);
            pos = pos + 1;
        }
        total = total + coalition_value(after_mask) - coalition_value(before_mask);
        perm = perm + 1;
    }
    total / 6
}

