fn bundle_value(items: i64, values: [i64; 4], synergy: [i64; 6]) -> i64 {
    let mut val = 0;
    let mut i = 0;
    while i < 4 {
        if (items >> i) & 1 == 1 {
            val = val + values[i];
        }
        i = i + 1;
    }
    let mut syn_idx = 0;
    let mut a = 0;
    while a < 4 {
        let mut b = a + 1;
        while b < 4 {
            if (items >> a) & 1 == 1 && (items >> b) & 1 == 1 {
                val = val + synergy[syn_idx];
            }
            syn_idx = syn_idx + 1;
            b = b + 1;
        }
        a = a + 1;
    }
    val
}

