fn compute_regret(payoffs: [[i64; 4]; 3]) -> i64 {
    let mut min_max_regret = 999999;
    let mut best_action = 0;
    let mut a = 0;
    while a < 3 {
        let mut max_regret = 0;
        let mut s = 0;
        while s < 4 {
            let mut best_in_state = payoffs[0][s];
            let mut k = 1;
            while k < 3 {
                if payoffs[k][s] > best_in_state {
                    best_in_state = payoffs[k][s];
                }
                k = k + 1;
            }
            let regret = best_in_state - payoffs[a][s];
            if regret > max_regret {
                max_regret = regret;
            }
            s = s + 1;
        }
        if max_regret < min_max_regret {
            min_max_regret = max_regret;
            best_action = a;
        }
        a = a + 1;
    }
    best_action
}

fn main() {
    let payoffs = [[10, 5, 8, 3], [6, 9, 4, 7], [7, 7, 7, 7]];
    println!("{}", compute_regret(payoffs));
}

