    while i < 4 {
        if i != agent {
            others_value = others_value + values[i] * allocation[i];
        }
        i = i + 1;
    }
    let mut others_opt = 0;
    let mut j = 0;
    while j < 4 {
        if j != agent {
            others_opt = others_opt + values[j];
        }
        j = j + 1;
    }
    others_opt - others_value
}

