    let mut v = 0;
    while v < 5 {
        let mut c = 0;
        while c < 4 {
            scores[c] = scores[c] + (3 - rankings[v][c]);
            c = c + 1;
        }
        v = v + 1;
    }
    let mut winner = 0;
    let mut best = scores[0];
    let mut i = 1;
    while i < 4 {
        if scores[i] > best {
            best = scores[i];
            winner = i;
        }
        i = i + 1;
    }
    winner
}

