        if bids[i] > max_bid {
            max_bid = bids[i];
            winner = i;
        }
        i = i + 1;
    }
    let profit = 100 - max_bid;
    winner * 1000 + profit
}

fn main() {
    let bids = [15, 42, 33, 28, 50, 19];
    let result = all_pay_winner(bids);
    println!("{}", result / 1000);
    println!("{}", result % 1000);
}

fn topsis_rank(scores: [[i64; 3]; 4], weights: [i64; 3]) -> i64 {
    let mut best_alt = 0;
    let mut best_score = 0;
    let mut a = 0;
    while a < 4 {
        let mut weighted_sum = 0;
        let mut j = 0;
        while j < 3 {
            weighted_sum = weighted_sum + scores[a][j] * weights[j];
            j = j + 1;
        }
        if weighted_sum > best_score {
            best_score = weighted_sum;
            best_alt = a;
        }
        a = a + 1;
    }
    best_alt
}

