fn lcs(a: [i64; 6], b: [i64; 7]) -> i64 {
    let mut prev = [0, 0, 0, 0, 0, 0, 0, 0];
    let mut i = 1;
    while i <= 6 {
        let mut curr = [0, 0, 0, 0, 0, 0, 0, 0];
        let mut j = 1;
        while j <= 7 {
            if a[i - 1] == b[j - 1] {
                curr[j] = prev[j - 1] + 1;
            } else {
                if prev[j] > curr[j - 1] {
                    curr[j] = prev[j];
                } else {
                    curr[j] = curr[j - 1];
                }
            }
            j = j + 1;
        }
        prev = curr;
        i = i + 1;
    }
    prev[7]
}

