fn rod_cut(prices: [i64; 8]) -> i64 {
    let mut dp = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    let mut i = 1;
    while i <= 8 {
        let mut max_val = 0;
        let mut j = 0;
        while j < i {
            let val = prices[j] + dp[i - j - 1];
            if val > max_val {
                max_val = val;
            }
            j = j + 1;
        }
        dp[i] = max_val;
        i = i + 1;
    }
    dp[8]
}

