    let edges = [[0, 1, 6], [0, 2, 7], [1, 2, 8], [1, 3, 5], [1, 4, -4], [2, 3, -3], [3, 4, 9]];
    println!("{}", bellman_ford(edges, 5, 0));
}

fn floyd_warshall(graph: [[i64; 4]; 4]) -> i64 {
    let mut dist = graph;
    let mut k = 0;
    while k < 4 {
        let mut i = 0;
        while i < 4 {
            let mut j = 0;
            while j < 4 {
                if dist[i][k] + dist[k][j] < dist[i][j] {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
                j = j + 1;
            }
            i = i + 1;
        }
        k = k + 1;
    }
    let mut sum = 0;
    let mut i = 0;
    while i < 4 {
        let mut j = 0;
        while j < 4 {
            sum = sum + dist[i][j];
            j = j + 1;
        }
        i = i + 1;
    }
    sum
}

