fn crc_check(data: [i64; 8], len: i64) -> i64 {
    let poly = 79764919;
    let mut crc = 0;
    let mut i = 0;
    while i < len {
        crc = crc ^ (data[i] * 256);
        let mut bit = 0;
        while bit < 8 {
            if crc % 2 == 1 {
                crc = (crc / 2) ^ poly;
            } else {
                crc = crc / 2;
            }
            bit = bit + 1;
        }
        i = i + 1;
    }
    if crc < 0 {
        crc = 0 - crc;
    }
    crc % 1000000000
}

