fn is_witness(a: i64, n: i64) -> i64 {
    let mut d = n - 1;
    let mut r = 0;
    while d % 2 == 0 {
        d = d / 2;
        r = r + 1;
    }
    let mut x = mod_pow(a, d, n);
    if x == 1 {
        return 0;
    }
    if x == n - 1 {
        return 0;
    }
    let mut i = 0;
    while i < r - 1 {
        x = x * x % n;
        if x == n - 1 {
            return 0;
        }
        i = i + 1;
    }
    1
}

