fn ext_gcd(a: i64, b: i64) -> [i64; 3] {
    let mut old_r = a;
    let mut r = b;
    let mut old_s = 1;
    let mut s = 0;
    let mut old_t = 0;
    let mut t = 1;
    while r > 0 {
        let q = old_r / r;
        let tmp_r = r;
        r = old_r - q * r;
        old_r = tmp_r;
        let tmp_s = s;
        s = old_s - q * s;
        old_s = tmp_s;
        let tmp_t = t;
        t = old_t - q * t;
        old_t = tmp_t;
    }
    [old_r, old_s, old_t]
}

