fn sha_compress(state: [i64; 4], block: [i64; 4]) -> [i64; 4] {
    let mut a = state[0];
    let mut b = state[1];
    let mut c = state[2];
    let mut d = state[3];
    let mut i = 0;
    while i < 4 {
        let f = (b ^ c ^ d) + a + block[i] + (i * 1103515245 + 12345);
        let tmp = d;
        d = c;
        c = b;
        b = (b + f) % 1000000007;
        a = tmp;
        i = i + 1;
    }
    if a < 0 { a = 0 - a; }
    if b < 0 { b = 0 - b; }
    if c < 0 { c = 0 - c; }
    if d < 0 { d = 0 - d; }
    [a % 1000000007, b % 1000000007, c % 1000000007, d % 1000000007]
}

