fn hmac_like(key: i64, data: [i64; 4], len: i64) -> i64 {
    let ipad = 54;
    let opad = 92;
    let mut inner = [0, 0, 0, 0, 0, 0, 0, 0];
    inner[0] = key ^ ipad;
    let mut i = 0;
    while i < len {
        inner[i + 1] = data[i];
        i = i + 1;
    }
    let inner_hash = simple_hash(inner, len + 1);
    let mut outer = [0, 0, 0, 0, 0, 0, 0, 0];
    outer[0] = key ^ opad;
    outer[1] = inner_hash;
    simple_hash(outer, 2)
}

