}

fn power_iter(mat: [i64; 4], steps: i64) -> i64 {
    let mut v = [1000, 0];
    let mut i = 0;
    while i < steps {
        v = mat_mul_2x2(mat, v);
        let norm = if v[0] > v[1] { v[0] } else { v[1] };
        if norm > 0 {
            v[0] = v[0] * 1000 / norm;
            v[1] = v[1] * 1000 / norm;
        }
        i = i + 1;
    }
    let w = mat_mul_2x2(mat, v);
    if v[0] > 0 {
        w[0] * 1000 / v[0]
    } else {
        w[1] * 1000 / v[1]
    }
}

