fn gs_solve(a00: i64, a01: i64, a10: i64, a11: i64, b0: i64, b1: i64, iters: i64) -> [i64; 2] {
    let mut x0 = 0;
    let mut x1 = 0;
    let mut i = 0;
    while i < iters {
        x0 = (b0 * 1000 - a01 * x1) / a00;
        x1 = (b1 * 1000 - a10 * x0) / a11;
        i = i + 1;
    }
    [x0, x1]
}

