fn poly_eval(x: i64) -> i64 {
    x * x / 1000 * x / 1000 - 6 * x * x / 1000 + 11 * x - 6000
}

fn bracket_root(lo: i64, hi: i64) -> i64 {
    let mut a = lo;
    let mut b = hi;
    let mut i = 0;
    while i < 50 {
        let mid = (a + b) / 2;
        let fa = poly_eval(a);
        let fm = poly_eval(mid);
        if fa > 0 && fm > 0 {
            a = mid;
        } else if fa < 0 && fm < 0 {
            a = mid;
        } else {
            b = mid;
        }
        i = i + 1;
    }
    (a + b) / 2
}

