    println!("{}", root);
}

fn f_val(x: i64) -> i64 {
    x * x / 1000 * x / 1000
}

fn deriv5(x: i64, h: i64) -> i64 {
    let fm2 = f_val(x - 2 * h);
    let fm1 = f_val(x - h);
    let fp1 = f_val(x + h);
    let fp2 = f_val(x + 2 * h);
    (fm2 - 8 * fm1 + 8 * fp1 - fp2) / (12 * h / 1000)
}

