fn wave_step(u_cur: [i64; 6], u_prev: [i64; 6], c2: i64) -> [i64; 6] {
    let w0 = u_cur[0];
    let w1 = 2 * u_cur[1] - u_prev[1] + c2 * (u_cur[0] - 2 * u_cur[1] + u_cur[2]) / 1000;
    let w2 = 2 * u_cur[2] - u_prev[2] + c2 * (u_cur[1] - 2 * u_cur[2] + u_cur[3]) / 1000;
    let w3 = 2 * u_cur[3] - u_prev[3] + c2 * (u_cur[2] - 2 * u_cur[3] + u_cur[4]) / 1000;
    let w4 = 2 * u_cur[4] - u_prev[4] + c2 * (u_cur[3] - 2 * u_cur[4] + u_cur[5]) / 1000;
    let w5 = u_cur[5];
    [w0, w1, w2, w3, w4, w5]
}

