fn nfa_next(state_set: i64, sym: i64) -> i64 {
    let result: i64 = 0;
    let has_s0: i64 = state_set % 2;
    let has_s1: i64 = (state_set / 2) % 2;
    let r: i64 = result;
    let r: i64 = if has_s0 == 1 {
        if sym == 0 { r + 1 + 2 } else { r + 2 }
    } else { r };
    let r: i64 = if has_s1 == 1 {
        if sym == 1 { r + 1 } else { r }
    } else { r };
    let r: i64 = if r > 3 { r - (r / 4) * 4 } else { r };
    r
}

