fn apply_op(op: i64, left: i64, right: i64) -> i64 {
    match op {
        1 => left + right,
        2 => left - right,
        3 => left * right,
        4 => if right != 0 { left / right } else { 0 },
        _ => 0,
    }
}

fn eval_expr(a: i64, op1: i64, b: i64, op2: i64, c: i64) -> i64 {
