fn xor_bit(a: i64, b: i64) -> i64 {
    if a == b { return 0; }
    1
}

fn crc_step(reg: i64, poly: i64, nbits: i64) -> i64 {
    let mut r = reg;
    let mut i = nbits - 1;
    while i >= 0 {
        let top_bit = r / 1000;
        if top_bit == 1 {
            let mut j = nbits - 1;
            let mut new_r = 0;
            let mut pr = r;
            let mut pp = poly;
            while j >= 0 {
                let rb = pr % 10;
                let pb = pp % 10;
                let xb = xor_bit(rb, pb);
                let mut mult = 1;
                let mut k = 0;
                while k < j {
                    mult = mult * 10;
                    k = k + 1;
                }
                new_r = new_r + xb * mult;
                pr = pr / 10;
                pp = pp / 10;
                j = j - 1;
            }
            r = new_r;
        }
        r = (r % 1000) * 10;
        i = i - 1;
    }
    r / 10
}

