fn hamming_weight(n: i64) -> i64 {
    let mut x = n;
    let mut count = 0;
    while x > 0 {
        count = count + x % 2;
        x = x / 2;
    }
    count
}

fn min_weight_nonzero(gen: i64, nbits: i64) -> i64 {
    let mut min_w = nbits + 1;
    let mut msg = 1;
    let limit = 1;
    let mut lim = 1;
    let mut k = 0;
    while k < nbits {
        lim = lim * 2;
        k = k + 1;
    }
    while msg < lim {
        let cw = msg * gen;
        let w = hamming_weight(cw);
        if w < min_w {
            min_w = w;
        }
        msg = msg + 1;
    }
    min_w
}

fn main() {
    println!("weight of 0: {}", hamming_weight(0));
    println!("weight of 7: {}", hamming_weight(7));
    println!("weight of 255: {}", hamming_weight(255));
    println!("min dist: {}", min_weight_nonzero(11, 4));
}

fn lagrange_basis(xs: [i64; 4], j: i64, eval_x: i64) -> i64 {
    let mut numer = 1;
    let mut denom = 1;
    let mut i = 0;
    while i < 4 {
        if i == j {
            i = i + 1;
        } else {
            numer = numer * (eval_x - xs[i]);
            denom = denom * (xs[j] - xs[i]);
            i = i + 1;
        }
    }
    if denom == 0 {
        return 0;
    }
    numer / denom
}

fn interpolate(xs: [i64; 4], ys: [i64; 4], eval_x: i64) -> i64 {
    let mut result = 0;
    let mut j = 0;
    while j < 4 {
        result = result + ys[j] * lagrange_basis(xs, j, eval_x);
        j = j + 1;
    }
    result
}

