fn min_sum_check(llr: [i64; 5], exclude: i64) -> i64 {
    let mut min_abs = 999999;
    let mut sign_prod = 1;
    let mut i = 0;
    while i < 5 {
        if i == exclude {
            i = i + 1;
        } else {
            let a = abs_val(llr[i]);
            if a < min_abs {
                min_abs = a;
            }
            sign_prod = sign_prod * sign_val(llr[i]);
            i = i + 1;
        }
    }
    sign_prod * min_abs
}

