fn find_min(freq: [i64; 8], used: [i64; 8], n: i64) -> i64 {
    let mut min_idx = -1;
    let mut min_val = 999999;
    let mut i = 0;
    while i < n {
        if used[i] == 0 && freq[i] < min_val && freq[i] > 0 {
            min_val = freq[i];
            min_idx = i;
        }
        i = i + 1;
    }
    min_idx
}

fn main() {
    let freq: [i64; 8] = [5, 9, 12, 13, 16, 45, 0, 0];
    let mut wf: [i64; 8] = [5, 9, 12, 13, 16, 45, 0, 0];
    let mut used: [i64; 8] = [0, 0, 0, 0, 0, 0, 1, 1];
    let mut next_slot = 6;
    let mut steps = 0;
    while steps < 5 {
        let m1 = find_min(wf, used, 8);
        if m1 < 0 { steps = 5; }
        else {
            used[m1] = 1;
            let m2 = find_min(wf, used, 8);
            if m2 < 0 { steps = 5; }
            else {
                used[m2] = 1;
                if next_slot < 8 {
                    wf[next_slot] = wf[m1] + wf[m2];
                    used[next_slot] = 0;
                    println!("merge {} + {} = {}", wf[m1], wf[m2], wf[next_slot]);
                    next_slot = next_slot + 1;
                }
                steps = steps + 1;
            }
        }
    }
}

fn encode_symbol(lo: i64, hi: i64, sym_lo: i64, sym_hi: i64, total: i64) -> i64 {
    let range = hi - lo;
    let new_lo = lo + range * sym_lo / total;
    let new_hi = lo + range * sym_hi / total;
    new_lo * 10000 + new_hi
}

fn main() {
