    let mut cur_lo = lo;
    let mut cur_hi = hi;
    let mut i = 0;
    while i < 3 {
        let result = encode_symbol(cur_lo, cur_hi, cum_lo[i], cum_hi[i], total);
        cur_lo = result / 10000;
        cur_hi = result % 10000;
        println!("sym {}: [{}, {})", symbols[i], cur_lo, cur_hi);
        i = i + 1;
    }
}

fn approx_log2(x: i64) -> i64 {
    if x <= 1 { return 0; }
    let mut val = x;
    let mut result = 0;
