}

fn entropy_scaled(freq: [i64; 6], total: i64) -> i64 {
    let mut h = 0;
    let mut i = 0;
    while i < 6 {
        if freq[i] > 0 {
            let log_total = approx_log2(total);
            let log_freq = approx_log2(freq[i]);
            h = h + freq[i] * (log_total - log_freq);
        }
        i = i + 1;
    }
    h
}

