fn mutual_info(joint: [i64; 4], margin_x: [i64; 2], margin_y: [i64; 2], total: i64) -> i64 {
    let mut mi = 0;
    let mut i = 0;
    while i < 2 {
        let mut j = 0;
        while j < 2 {
            let idx = i * 2 + j;
            let pxy = joint[idx];
            if pxy > 0 {
                let log_pxy = approx_log2(pxy * total);
                let log_marg = approx_log2(margin_x[i] * margin_y[j]);
                mi = mi + pxy * (log_pxy - log_marg);
            }
            j = j + 1;
        }
        i = i + 1;
    }
    mi
}

