}

fn power_of_2(exp: i64) -> i64 {
    let mut result = 1;
    let mut i = 0;
    while i < exp {
        result = result * 2;
        i = i + 1;
    }
    result
}

fn kraft_sum(lengths: [i64; 6], n: i64, max_len: i64) -> i64 {
    let denom = power_of_2(max_len);
    let mut sum = 0;
    let mut i = 0;
    while i < n {
        sum = sum + denom / power_of_2(lengths[i]);
        i = i + 1;
    }
    sum * 1000 / denom
}

