fn binary_entropy(p_scaled: i64, scale: i64) -> i64 {
    if p_scaled <= 0 { return 0; }
    let q_scaled = scale - p_scaled;
    if q_scaled <= 0 { return 0; }
    let log_inv_p = approx_log2(scale * 100 / p_scaled);
    let log_inv_q = approx_log2(scale * 100 / q_scaled);
    (p_scaled * log_inv_p + q_scaled * log_inv_q) / scale
}

fn channel_capacity(p_scaled: i64, scale: i64) -> i64 {
    let h = binary_entropy(p_scaled, scale);
    let log_scale = approx_log2(100);
    log_scale - h
}

