fn get_bit(seq: i64, pos: i64) -> i64 {
    let mut s = seq;
    let mut i = 0;
    while i < pos {
        s = s / 2;
        i = i + 1;
    }
    s % 2
}

fn lz_complexity(seq: i64, length: i64) -> i64 {
    let mut count = 1;
    let mut i = 1;
    let mut new_start = 1;
    while i < length {
        let mut found = 0;
        let sub_len = i - new_start + 1;
        let mut start = 0;
        while start < new_start {
            let mut match_len = 0;
            let mut k = 0;
            while k < sub_len && start + k < i {
                if get_bit(seq, start + k) == get_bit(seq, new_start + k) {
                    match_len = match_len + 1;
                } else {
                    k = sub_len;
                }
                k = k + 1;
            }
            if match_len == sub_len {
                found = 1;
                start = new_start;
            }
            start = start + 1;
        }
        if found == 0 {
            count = count + 1;
            new_start = i + 1;
        }
        i = i + 1;
    }
    count
}

fn main() {
    println!("all zeros: {}", lz_complexity(0, 8));
    println!("alternating: {}", lz_complexity(170, 8));
    println!("random-ish: {}", lz_complexity(173, 8));
    println!("all ones: {}", lz_complexity(255, 8));
}

