fn sign_cross(px: i64, py: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    let v: i64 = (px - bx) * (ay - by) - (ax - bx) * (py - by);
    if v < 0 { return -1; }
    if v > 0 { return 1; }
    return 0;
}
fn point_in_tri(px: i64, py: i64, ax: i64, ay: i64, bx: i64, by: i64, cx: i64, cy: i64) -> i64 {
    let d1: i64 = sign_cross(px, py, ax, ay, bx, by);
    let d2: i64 = sign_cross(px, py, bx, by, cx, cy);
    let d3: i64 = sign_cross(px, py, cx, cy, ax, ay);
    let has_neg: i64 = if d1 < 0 { 1 } else if d2 < 0 { 1 } else if d3 < 0 { 1 } else { 0 };
    let has_pos: i64 = if d1 > 0 { 1 } else if d2 > 0 { 1 } else if d3 > 0 { 1 } else { 0 };
    if has_neg == 1 {
        if has_pos == 1 { return 0; }
    }
    return 1;
}
