fn on_seg(px: i64, py: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    let min_x: i64 = if ax < bx { ax } else { bx };
    let max_x: i64 = if ax > bx { ax } else { bx };
    let min_y: i64 = if ay < by { ay } else { by };
    let max_y: i64 = if ay > by { ay } else { by };
    if px >= min_x {
        if px <= max_x {
            if py >= min_y {
                if py <= max_y { return 1; }
            }
        }
    }
    return 0;
}
fn seg_intersect(ax: i64, ay: i64, bx: i64, by: i64, cx: i64, cy: i64, dx: i64, dy: i64) -> i64 {
    let o1: i64 = orient3(ax, ay, bx, by, cx, cy);
    let o2: i64 = orient3(ax, ay, bx, by, dx, dy);
    let o3: i64 = orient3(cx, cy, dx, dy, ax, ay);
    let o4: i64 = orient3(cx, cy, dx, dy, bx, by);
    if o1 != o2 {
        if o3 != o4 { return 1; }
    }
    if o1 == 0 { return on_seg(cx, cy, ax, ay, bx, by); }
    return 0;
}
