    let apx: i64 = px - ax;
    let apy: i64 = py - ay;
    let t_num: i64 = dot_prod(apx, apy, abx, aby);
    let t_den: i64 = dot_prod(abx, aby, abx, aby);
    if t_num <= 0 { return 0; }
    if t_num >= t_den { return 2; }
    return 1;
}
