fn incircle_det3(ax: i64, ay: i64, bx: i64, by: i64, cx: i64, cy: i64, dx: i64, dy: i64) -> i64 {
    let adx: i64 = ax - dx;
    let ady: i64 = ay - dy;
    let bdx: i64 = bx - dx;
    let bdy: i64 = by - dy;
    let cdx: i64 = cx - dx;
    let cdy: i64 = cy - dy;
    let ad_sq: i64 = adx * adx + ady * ady;
    let bd_sq: i64 = bdx * bdx + bdy * bdy;
    let cd_sq: i64 = cdx * cdx + cdy * cdy;
    let det: i64 = adx * (bdy * cd_sq - cdy * bd_sq) - ady * (bdx * cd_sq - cdx * bd_sq) + ad_sq * (bdx * cdy - cdx * bdy);
    if det > 0 { return 1; }
    if det < 0 { return -1; }
    return 0;
}
