fn polar_cmp(ox: i64, oy: i64, ax: i64, ay: i64, bx: i64, by: i64) -> i64 {
    let cross: i64 = (ax - ox) * (by - oy) - (ay - oy) * (bx - ox);
    if cross > 0 { return -1; }
    if cross < 0 { return 1; }
    let da: i64 = (ax - ox) * (ax - ox) + (ay - oy) * (ay - oy);
    let db: i64 = (bx - ox) * (bx - ox) + (by - oy) * (by - oy);
    if da < db { return -1; }
    if da > db { return 1; }
    return 0;
}
