fn round_robin_next(current: i64, num_procs: i64) -> i64 {
    let next: i64 = current + 1;
    if next >= num_procs { return 0; }
    return next;
}
fn simulate_rr(bursts: [i64; 5], quantum: i64) -> i64 {
    let mut remaining: [i64; 5] = [bursts[0], bursts[1], bursts[2], bursts[3], bursts[4]];
    let mut time: i64 = 0;
    let mut done: i64 = 0;
    let n: i64 = 5;
    let mut cur: i64 = 0;
    while done < n {
        if remaining[cur] > 0 {
            if remaining[cur] <= quantum {
                time = time + remaining[cur];
                remaining[cur] = 0;
                done = done + 1;
            } else {
                time = time + quantum;
                remaining[cur] = remaining[cur] - quantum;
            }
        }
        cur = round_robin_next(cur, n);
    }
    return time;
}
fn main() {
    let bursts: [i64; 5] = [10, 4, 6, 8, 2];
    let total: i64 = simulate_rr(bursts, 3);
    println!("total_time={}", total);
}

