    let mut best_time: i64 = 999999;
    if d0 == 0 && b0 < best_time { best = 0; best_time = b0; }
    if d1 == 0 && b1 < best_time { best = 1; best_time = b1; }
    if d2 == 0 && b2 < best_time { best = 2; best_time = b2; }
    if d3 == 0 && b3 < best_time { best = 3; best_time = b3; }
    return best;
}
