fn first_fit(bins: [i64; 6], num_bins: i64, item: i64, capacity: i64) -> i64 {
    let mut i: i64 = 0;
    while i < num_bins {
        if bins[i] + item <= capacity {
            return i;
        }
        i = i + 1;
    }
    return num_bins;
}
fn main() {
