    let items: [i64; 6] = [7, 3, 5, 4, 2, 6];
    let mut bins: [i64; 6] = [0, 0, 0, 0, 0, 0];
    let mut num_bins: i64 = 0;
    let mut i: i64 = 0;
    while i < 6 {
        let b: i64 = first_fit(bins, num_bins, items[i], cap);
        if b >= num_bins {
            num_bins = num_bins + 1;
        }
        bins[b] = bins[b] + items[i];
        println!("item {} -> bin {} (load={})", items[i], b, bins[b]);
        i = i + 1;
    }
    println!("bins_used={}", num_bins);
}

fn best_fit(bins: [i64; 6], num_bins: i64, item: i64, capacity: i64) -> i64 {
    let mut best: i64 = -1;
    let mut best_space: i64 = 999999;
    let mut i: i64 = 0;
    while i < num_bins {
        let space: i64 = capacity - bins[i];
        if space >= item && space < best_space {
            best = i;
            best_space = space;
        }
        i = i + 1;
    }
    if best < 0 { return num_bins; }
    return best;
}
fn main() {
    let cap: i64 = 10;
    let items: [i64; 5] = [4, 8, 3, 5, 7];
    let mut bins: [i64; 6] = [0, 0, 0, 0, 0, 0];
    let mut num_bins: i64 = 0;
    let mut i: i64 = 0;
    while i < 5 {
        let b: i64 = best_fit(bins, num_bins, items[i], cap);
        if b >= num_bins {
            num_bins = num_bins + 1;
        }
        bins[b] = bins[b] + items[i];
        println!("item {} -> bin {}", items[i], b);
        i = i + 1;
    }
    println!("bins_used={}", num_bins);
}

fn value_ratio(value: i64, weight: i64) -> i64 {
    return (value * 1000) / weight;
}
fn knapsack_greedy(vals: [i64; 4], wts: [i64; 4], capacity: i64) -> i64 {
    let mut total_val: i64 = 0;
    let mut remain: i64 = capacity;
    let mut used: [i64; 4] = [0, 0, 0, 0];
    let mut step: i64 = 0;
    while step < 4 && remain > 0 {
        let mut best: i64 = -1;
        let mut best_ratio: i64 = -1;
        let mut j: i64 = 0;
        while j < 4 {
            if used[j] == 0 {
                let r: i64 = value_ratio(vals[j], wts[j]);
                if r > best_ratio {
                    best = j;
                    best_ratio = r;
                }
            }
            j = j + 1;
        }
        if best < 0 { return total_val; }
        used[best] = 1;
        if wts[best] <= remain {
            total_val = total_val + vals[best];
            remain = remain - wts[best];
        } else {
            total_val = total_val + (vals[best] * remain) / wts[best];
            remain = 0;
        }
        step = step + 1;
    }
    return total_val;
}
fn main() {
    let vals: [i64; 4] = [60, 100, 120, 80];
    let wts: [i64; 4] = [10, 20, 30, 15];
    let result: i64 = knapsack_greedy(vals, wts, 50);
    println!("knapsack_value={}", result);
}

