fn min_val(a: i64, b: i64) -> i64 {
    if a < b { return a; }
    return b;
}
fn nw_corner_cost(supply: [i64; 3], demand: [i64; 3], costs: [i64; 9]) -> i64 {
    let mut s: [i64; 3] = [supply[0], supply[1], supply[2]];
    let mut d: [i64; 3] = [demand[0], demand[1], demand[2]];
    let mut total: i64 = 0;
    let mut i: i64 = 0;
    let mut j: i64 = 0;
    while i < 3 && j < 3 {
        let alloc: i64 = min_val(s[i], d[j]);
        total = total + alloc * costs[i * 3 + j];
        s[i] = s[i] - alloc;
        d[j] = d[j] - alloc;
        if s[i] == 0 { i = i + 1; }
        if j < 3 && d[j] == 0 { j = j + 1; }
    }
    return total;
}
fn main() {
    let supply: [i64; 3] = [20, 30, 25];
    let demand: [i64; 3] = [10, 35, 30];
    let costs: [i64; 9] = [8, 6, 10, 9, 12, 13, 14, 9, 16];
    let total: i64 = nw_corner_cost(supply, demand, costs);
    println!("transport_cost={}", total);
}

