fn critical_path(durations: [i64; 6], dep0: i64, dep1: i64, dep2: i64, dep3: i64, dep4: i64, dep5: i64) -> i64 {
    let mut es: [i64; 6] = [0, 0, 0, 0, 0, 0];
    es[0] = 0;
    if dep1 >= 0 { es[1] = es[0] + durations[0]; }
    if dep2 >= 0 { es[2] = es[0] + durations[0]; }
    es[3] = cpm_max(es[1] + durations[1], es[2] + durations[2]);
    es[4] = es[3] + durations[3];
    es[5] = es[4] + durations[4];
    return es[5] + durations[5];
}
