fn wfq_assign_credits(weights: [i64; 4], total_bw: i64) -> i64 {
    let sum_w: i64 = weights[0] + weights[1] + weights[2] + weights[3];
    return (weights[0] * total_bw) / sum_w;
}
fn wfq_next_queue(credits: [i64; 4], num_q: i64) -> i64 {
    let mut best: i64 = 0;
    let mut best_c: i64 = credits[0];
    let mut i: i64 = 1;
    while i < num_q {
        if credits[i] > best_c {
            best = i;
            best_c = credits[i];
        }
        i = i + 1;
    }
    return best;
}
