    let c1: i64 = (weights[1] * total_bw) / sum_w;
    let c2: i64 = (weights[2] * total_bw) / sum_w;
    let c3: i64 = (weights[3] * total_bw) / sum_w;
    let mut credits: [i64; 4] = [c0, c1, c2, c3];
    let next: i64 = wfq_next_queue(credits, 4);
    println!("credits: {} {} {} {} next={}", c0, c1, c2, c3, next);
}

