    rear = enqueue_idx(rear, cap);
    buf[rear] = 20;
    rear = enqueue_idx(rear, cap);
    buf[rear] = 30;
    rear = enqueue_idx(rear, cap);
    let v1: i64 = buf[front];
    front = dequeue_idx(front, cap);
    let v2: i64 = buf[front];
    front = dequeue_idx(front, cap);
