fn pad_width(n: i64, width: i64) -> i64 {
    let mut digits: i64 = 0;
    let mut tmp: i64 = n;
    if tmp == 0 { return width - 1; }
    if tmp < 0 { tmp = 0 - tmp; digits = 1; }
    while tmp > 0 {
        digits = digits + 1;
        tmp = tmp / 10;
    }
    if digits >= width { return 0; }
    return width - digits;
}
