fn f_quadratic(x: i64) -> i64 { return x * x; }
fn simpsons(a: i64, b: i64, n: i64) -> i64 {
    if n < 2 { return 0; }
    let h: i64 = (b - a) / n;
    if h == 0 { return 0; }
    let mut sum: i64 = f_quadratic(a) + f_quadratic(b);
    let mut i: i64 = 1;
    while i < n {
        let x: i64 = a + i * h;
        if i % 2 == 0 {
            sum = sum + 2 * f_quadratic(x);
        } else {
            sum = sum + 4 * f_quadratic(x);
        }
        i = i + 1;
    }
    return sum * h / 3;
}
fn main() {
