}

fn bit_and(a: i64, b: i64) -> i64 {
    let mut result: i64 = 0;
    let mut bit: i64 = 1;
    let mut i: i64 = 0;
    while i < 16 {
        let a_bit: i64 = (a / bit) % 2;
        let b_bit: i64 = (b / bit) % 2;
        if a_bit == 1 {
            if b_bit == 1 {
                result = result + bit;
            }
        }
        bit = bit * 2;
        i = i + 1;
    }
    return result;
}
fn bit_or(a: i64, b: i64) -> i64 {
    let mut result: i64 = 0;
    let mut bit: i64 = 1;
    let mut i: i64 = 0;
    while i < 16 {
        let a_bit: i64 = (a / bit) % 2;
        let b_bit: i64 = (b / bit) % 2;
        if a_bit == 1 {
            result = result + bit;
        } else if b_bit == 1 {
            result = result + bit;
        }
        bit = bit * 2;
        i = i + 1;
    }
    return result;
}
fn main() {
    println!("and(12,10)={}", bit_and(12, 10));
    println!("and(255,15)={}", bit_and(255, 15));
    println!("or(12,10)={}", bit_or(12, 10));
    println!("or(255,15)={}", bit_or(255, 15));
}

