fn ackermann_bounded(m: i64, n: i64, fuel: i64) -> i64 {
    if fuel <= 0 { return -1; }
    if m == 0 { return n + 1; }
    if n == 0 { return ackermann_bounded(m - 1, 1, fuel - 1); }
    let inner: i64 = ackermann_bounded(m, n - 1, fuel - 1);
    if inner == -1 { return -1; }
    return ackermann_bounded(m - 1, inner, fuel - 1);
}
