}

fn saturating_add(a: i64, b: i64) -> i64 {
    let max: i64 = 999999;
    let min: i64 = -999999;
    if b > 0 {
        if a > max - b { return max; }
    }
    if b < 0 {
        if a < min - b { return min; }
    }
    return a + b;
}
fn saturating_sub(a: i64, b: i64) -> i64 {
    return saturating_add(a, 0 - b);
}
