    if flags[0] == 1 { group_a = group_a + 1; }
    if flags[1] == 1 { group_a = group_a + 1; }
    if flags[2] == 1 { group_b = group_b + 1; }
    if flags[3] == 1 { group_b = group_b + 1; }
    if group_a > 1 { return -1; }
    if group_b > 1 { return -2; }
    if group_a >= 1 {
        if group_b >= 1 { return -3; }
    }
    return 0;
}
