fn sqrt_approx(n: i64) -> i64 {
    if n < 0 { return -9999; }
    if n == 0 { return 0; }
    let mut guess: i64 = n / 2;
    if guess == 0 { guess = 1; }
    let mut i: i64 = 0;
    while i < 20 {
        let next: i64 = divide(guess + divide(n, guess), 2);
        if next == -9999 { return -9999; }
        if next == guess { break; }
        guess = next;
        i = i + 1;
    }
    return guess;
}
fn main() {
