    println!("div(10,0)={}", divide(10, 0));
    println!("sqrt(100)={}", sqrt_approx(100));
    println!("sqrt(2)={}", sqrt_approx(2));
    println!("sqrt(0)={}", sqrt_approx(0));
    println!("sqrt(-4)={}", sqrt_approx(-4));
}

